(window.GIM_TS=window.GIM_TS||{})["Eruvin.4"]={"from":96,"a":[["\u0003אמר רבה: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב\u0004 האומר שלא אמר כלום כל עיקר — \u0003משום דלא מסיים אתריה\u0004 \u0005[שאין מקומו מוגדר]\u0006 תחת העץ וכיון שלא קבע שביתתו במקום מסוים אחד — לא קנה כלל.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 לשון אחרת \u0003אמר רבה: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רב\u0004 — \u0003משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003כל שאינו בזה אחר זה — אפילו בבת אחת אינו\u0004. כלומר: אם אין אפשרות (מצד ההלכה או מצד המציאות) לעשות שני דברים מסויימים, אחד אחד בזה אחר זה, גם אם עשאם בבת אחת — כאילו לא עשה דבר, וכל אחד מהם מבטל את משנהו. ואף כאן, כיון שלא היה יכול בתחילה לקנות שביתה בארבע אמות מסויימות ואחר כך בארבע אמות אחרות, לכן אינו יכול לקנות שביתה גם בבת אחת ביותר מארבע אמות שתחת האילן.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם],\u0006 בין שתי הלשונות הללו בדברי רבה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה בכגון ש\u0003אמר: \"ליקנו\u0004 \u0005[שיקנה]\u0006 \u0003לי\u0004 מקום של \u0003ארבע אמות מגו\u0004 \u0005[מתוך]\u0006 \u0003שמונה\u0004 או יותר אמות שיש תחת אותו אילן\u0003\".\u0004","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהנימוק הוא \u0003משום דלא מסיים אתריה\u0004 \u0005[שאין מקומו מוגדר]\u0006 — \u0003הא לא מסיים אתריה\u0004 \u0005[הרי\u0006 עדיין \u0005אין מקומו מוגדר],\u0006 שלא קבע בדיוק באלו ארבע אמות רצונו לשבות.","ואולם \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהטעם הוא \u0003משום \"כל שאינו בזה אחר זה אפילו בבת אחת אינו\" — האי\u0004 \u0005[זה]\u0006 \u0003כארבע אמות\u0004 בלבד \u0003דמי\u0004 \u0005[נחשב]\u0006 \u0003דהכא\u0004 \u0005[שכאן]\u0006 \u0003ארבע אמות\u0004 בלבד \u0003קאמר\u0004 \u0005[הוא שאמר],\u0006 וקנה שביתה בארבע אמות אלה.","\u0003גופא\u0004 \u0005[ולגופו]\u0006 של הכלל הזה שקבע \u0003רבה\u0004 ש\u0003\"כל דבר שאינו בזה אחר זה אפילו בבת אחת אינו\", איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבה,\u0004 שנינו בתוספתא: \u0003המרבה במעשרות\u0004 כגון המפריש מתבואתו למעשר לא עשירית כי אם שתי עשיריות — \u0003פירותיו,\u0004 כלומר שאר הפירות, \u0003מתוקנין,\u0004 שהרי הפריש מהם מעשר כדינו. \u0003ו\u0004אולם \u0003מעשרותיו מקולקלין\u0004 שהרי אין קדושת המעשר חלה אלא על עשירית אחת והעשירית האחרת המצויה בתוך מה שהפריש כמעשר — אין עליה קדושת מעשר, ואף לא נתקנה כשאר החולין, וכיון שלא ברור מהו המופרש למעשר ומהו העשירית האחרת — הכל מעורב ואי אפשר להשתמש במעשר זה לא כחולין ולא כמעשר.","ולשיטת רבה אפשר לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא הדין כך? \u0003לימא\u0004 \u0005[שנאמר]:\u0006 \u0003כל שאינו בזה אחר זה — אפילו בבת אחת אינו,\u0004 וכיון שאינו יכול להקדיש למעשר עשירית אחת ולחזור ולהקדיש עשירית אחרת כך גם לא יוכל להקדיש שתי עשיריות יחד, והרי זה כאילו לא עישר כלל ואם כן אף פירותיו לא יהיו מתוקנים!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מעשר דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003לחצאין,\u0004 ד\u0003אי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 \u0003אמר: \"תקדוש פלגא פלגא דחיטתא\"\u0004 \u0005[תתקדש\u0006 בקדושת מעשר \u0005חצי חצי חיטה] —\u0006 \u0003קדשה\u0004 \u0005[מתקדשת]\u0006 שכשם שאפשר להקדיש חיטה שלימה אפשר להקדיש חלק מכל חיטה למעשר. ואף כאן שהקדיש שתי עשיריות מן התבואה למעשר אין אנו אומרים שעשירית אחת מהן מעשר גמור והשאר רק חולין המעורב במעשר, \u0003אלא אפשר להבין שחלק מכל חיטה הוקדש בקדושת מעשר וחלה קדושה על כל מחצית חיטה מן המופרש, אלא כיון שאי אפשר לברר איזהו המוקדש —\u0004 מעשרותיו מקולקלין.","ועוד הקשה על שיטתו של רבה ממקור אחר: \u0003והרי מעשר בהמה דליתיה\u0004 \u0005[שאינו]\u0006 \u0003לחצאין\u0004 שאין אדם יכול להקדיש מחצית הבהמה למעשר.","ובשעת הפרשת מעשר בהמה הנוהג הוא שמוציאים את הוולדות של אותה שנה מהדיר וסופרים אותם עם יציאתם, וכל עשירי מתקדש בקדושת מעשר, \u0003ואמר רבה\u0004: אם \u0003יצאו שנים\u0004 יחד \u0003בעשירי, וקראן\u0004 לשניהם \u0003עשירי\u0004 — הרי \u0003עשירי ואחד עשר מעורבין זה בזה,\u0004 אחד מהם נתקדש בקדושת מעשר והאחר נשאר שלמים, אלא שלא ברור לנו מי הוא המוקדש, ועכשיו אם נקבל את הכלל ש\"כל שאינו בזה אחר זה אפילו בבת אחת אינו\" הרי מן הדין שלא תחול כל קדושה על שניהם!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מעשר בהמה דאיתיה\u0004 \u0005[שישנו,\u0006 שיש בו\u0005]\u0006 בכל זאת דין \u0003בזה אחר זה בטעות\u0004. שאף כי לכתחילה אי אפשר להקדיש שניים בזה אחר זה, בכל זאת אם נעשה הדבר בטעות הריהם מוקדשים.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם טעה ו\u0003קרא\u0004 לכבש ה\u0003תשיעי עשירי,\u0004 וטעה שוב וקרא \u0003לעשירי תשיעי ולאחד עשר עשירי — שלשתן מקודשין.\u0004 הראשון משום שנקרא עשירי, השני משום שהוא העשירי, אף השלישי משום שנקרא עשירי. משמע שהקדושה חלה גם על יותר מאחד אם הדבר נעשה על פי טעות. ואף כאן חלה קדושה מסויימת על השנים שיצאו כאחת כדין הקדש מעשר בהמה בטעות.","ועוד מקשים על הכלל: \u0003והרי\u0004 קרבן \u0003תודה, דליתה\u0004 \u0005[שאינה]\u0006 מתקדשת \u0003בטעות ו\u0004אף \u0003ליתה\u0004 \u0005[אינה]\u0006 מתקדשת \u0003בזה אחר זה, ו\u0004בכל זאת \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003תודה שנשחטה על שמונים חלות\u0004 שמקריב התודה הפריש לא ארבעים חלות, כמצווה, אלא כפליים, שמונים, \u0003חזקיה אמר: קדשו עלה\u0004 \u0005[עליה,\u0006 בגלל התודה\u0005]\u0006 \u0003ארבעים\u0004 חלות \u0003מתוך\u0004 ה\u0003שמונים,\u0004 אף על פי שאין אנו יודעים להחליט ולומר אלו הן, \u0003ר' יוחנן אמר: לא קדשו עלה\u0004 \u0005[עליה,\u0006 בגללה\u0005]\u0006 \u0003ארבעים מתוך שמונים\u0004 ולכאורה נראה שאכן נחלקו בבעיה אם חלה הקדושה בבת אחת או לא.","ודוחים: \u0003הא איתמר עלה\u0004 \u0005[הרי כבר נאמר עליה]\u0006 על מחלוקת זו, \u0003אמר ר' זירא: הכל מודים היכא דאמר \"ליקדשו\u0004 \u0005[במקום שאמר\u0006 המקדיש \u0005שיתקדשו]\u0006 \u0003ארבעים מתוך שמונים\" — דקדשי\u0004 \u0005[שמתקדשים\u0006 הם\u0005],\u0006 ואם אמר \u0003\"לא יקדשו ארבעים\u0004 חלות \u0003אלא אם כן קדשו שמונים\u0004 כולן \u0003\"\u0004— \u0003כולי עלמא לא פליגי דלא קדשו\u0004 \u0005[הכל אינם חולקים שאינן מתקדשות]\u0006 וכשיטת רבה.","אולם \u0003כי פליגי בסתמא\u0004 \u0005[כאשר נחלקו\u0006 ר' חזקיה ור' יוחנן, היה זה \u0005ב\u0006מקדיש \u0005סתם].\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 חזקיה\u0005]\u0006 \u0003סבר\u0004: \u0003לאחריות קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003ועל תנאי אייתינהו\u0004 \u0005[הביא אותן],\u0006 שחשש שמא יאבדו או יטמאו ארבעים החלות ולכן הביא עוד ארבעים חלות על תנאי שאם יארע פגם בראשונות יתקדשו האחרונות, ולכן חלה קדושה עליהן."],["\u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן\u0005]\u0006 \u0003סבר:\u0004 אותו אדם \u0003לקרבן גדול\u0004 לשמונים חלות \u0003קא מכוין\u0004 \u0005[הוא מתכוין]\u0006 ומן הדין אין לעשות כן.","\u0003אמר אביי: לא שנו\u0004 שלדברי רב אינו יכול לקנות שביתה תחת אילן בלי לקבוע מקום מסוים, \u0003אלא באילן ש\u0004יש \u0003תחתיו שתים עשרה אמה\u0004 לפחות שאינו יודע באיזה ארבע אמות מתוכן קנה שביתה, \u0003אבל באילן שאין\u0004 תחתיו \u0003שתים עשרה אמה\u0004 קנה שביתה, ש\u0003הרי מקצת ביתו ניכר,\u0004 שכן ארבע האמות האמצעיות תחת אילן זה נכנסות גם לתוך ארבע אמות הקרובות אליו וגם בתוך ארבע אמות הרחוקות ממנו, ונמצא שבכל אופן יש חלק ידוע מתחומו שהוא מוגדר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ממאי דבארבעי מציעתא קא מסיים\u0004 \u0005[מנין שבארבע\u0006 אמות \u0005אמצעיות הוא מגדיר]\u0006 את מקום שביתתו, שאז ברור שחלק מהן חופף גם לארבע אמות קרובות, או רחוקות, \u0003דלמא בארבעי דהאי גיסא ובארבעי דהאי גיסא קמסיים\u0004 \u0005[שמא בארבע שבצד זה ובארבע שבצד זה הוא מגדיר]\u0006 ומכיון שאינו יודע היכן הגדיר שביתתו הרי שלא קנה שביתה במקום מסוים אפילו כשאין תחת האילן אלא אחד עשר אמות!","\u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 יש לתקן את הדברים ולומר: \u0003לא שנו אלא באילן שתחתיו שמונה אמות, אבל באילן שתחתיו שבע אמות,\u0004 גם אם לא קבע מקום מסוים — קנה שביתה, ש\u0003הרי\u0004 אמה אחת ודאי מוגדרת ו\u0003מקצת ביתו ניכר\u0004.","על עצם המחלוקת בין רב ושמואל מעירים כי \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב,\u0004 ו\u0003תניא כוותיה\u0004 \u0005[ושנוייה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003שמואל.\u0004","ומפרטים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב: מי שבא בדרך וחשכה לו, והיה מכיר אילן או גדר, ואמר: \"שביתתי תחתיו\" — לא אמר כלום. אבל אם אמר: \"שביתתי במקום פלוני\u0004 (מסוים) \u0003\" — מהלך עד שמגיע לאותו מקום. הגיע לאותו מקום\u0004 שקנה בו שביתה — \u0003מהלך את כולו וחוצה לו\u0004 אפילו \u0003אלפים אמה.\u0004","\u0003במה דברים אמורים\u0004 שקונה ארבע אמות לשביתה ואלפיים מהם לכל צד — \u0003במקום המסויים,\u0004 שבחר לו מקום מוגדר ומותחם \u0003כגון ששבת בתל שהוא גבוה עשרה טפחים, והוא\u0004 בשטח \u0003מארבע אמות ועד בית סאתים\u0004 שהוא מקום שיש לו תחומים מסוימים.","\u0003וכן\u0004 אם רצה לשבות ב\u0003בקעה\u0004 (במישור) \u0003שהיא עמוקה\u0004 מסביבתה \u0003עשרה\u0004 טפחים, \u0003והיא מארבע אמות עד בית סאתים. אבל במקום שאין מסויים\u0004 כגון שבחר בתוך המישור, או במרחק אלף אמה — לא קנה שביתה ו\u0003אין לו אלא ארבע אמות.\u0004","ועוד אמרו לענין זה: \u0003היו שנים\u0004 מהלכים יחד, \u0003אחד מכיר\u0004 מקום מסויים במרחק, \u0003ואחד שאינו מכיר — זה שאינו מכיר מוסר שביתתו למכיר, והמכיר אומר: \"שביתתי במקום פלוני\".\u0004","\u0003במה דברים אמורים\u0004 שקונה ארבע אמות לשביתה ואלפיים מהם לכל צד — \u0003כשסיים\u0004 (הגדיר) במקום \u0003ארבע אמות שקבע\u0004 לשביתתו. \u0003אבל\u0004 אם \u0003לא סיים ארבע אמות שקבע — לא יזוז ממקומו\u0004. ומשמע כשיטת רב שאם לא קנה מקום מסוים — לא קנה שביתה כלל.","\u0003ושואלים: לימא תיהוי תיובתיה\u0004 \u0005[שמא תהא זאת קושיה חמורה]\u0006 לשיטת \u0003שמואל?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003שמואל: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה מיוחד \u0003כגון דאיכא\u0004 \u0005[שיש]\u0006 \u0003ממקום רגליו ועד עיקרו\u0004 של האילן \u0003תרי אלפי וארבע גרמידי\u0004 \u0005[אלפיים וארבע אמות],\u0006 \u0003דאי מוקמית ליה באידך גיסא דאילן\u0004 \u0005[שאם תעמיד אותו,\u0006 את מקום שביתתו, \u0005בצד האחר של האילן] —\u0006 \u0003קם ליה לבר מתחומא\u0004 \u0005[יעמוד מחוץ לתחום].\u0006","ולכן \u0003אי סיים\u0004 \u0005[אם\u0006 קבע והגדיר\u0005]\u0006 \u0003ארבע אמות\u0004 בצד הנכון — \u0003מצי אזיל\u0004 \u0005[יכול ללכת],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא מצי אזיל\u0004 \u0005[אינו יכול ללכת]\u0006 כלומר אותו אדם לא קנה שביתה במקום מסוים וחוששים שמא קבע מקום מחוץ לאלפיים אמה.","וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003שמואל: טעה ועירב לשתי רוחות\u0004 (שני צדדים) כאחת, כגון ש\u0003כמדומה הוא\u0004 שאפשר \u0003שמערבין לו לשתי רוחות,\u0004 כדי שיוכל ללכת במשך השבת לשני צדדים נגדיים \u0003או שאמר לעבדיו \"צאו וערבו לי\"\u0004, ולא אמר להם להיכן, \u0003אחד עירב עליו לצפון ואחד עירב עליו לדרום — מהלך לצפון כ\u0004פי שמותר לו להלך על פי \u0003עירובו לדרום,\u0004 ומותר לו להלך \u0003לדרום כ\u0004פי שמתיר לו ללכת \u0003עירובו לצפון\u0004.","כלומר: אנו מניחים שקנה שביתה בשני המקומות על פי שני העירובין יחד, ומותר לו לנוע ממקום למקום בהתחשב עם שניהם יחד. \u0003ו\u0004לכן \u0003אם מיצעו עליו את התחום\u0004 שנעשו העירובים כך שנמצא מרוחק אלפיים אמה גם מצפון גם מדרום — \u0003לא יזוז ממקומו\u0004 שאסור לו לצאת חוץ משני תחומיו ומכאן אפשר ללמוד שאף אם לא קבע שביתה במקום מסוים שהרי קנה שביתה בשני מקומות, בכל זאת מקבלים להלכה שהיתה כאן קניית שביתה, וכשיטת שמואל.","ושואלים: אם כן, \u0003לימא תיהוי תיובתיה\u0004 \u0005[שמא תהא זו קושיה חמורה]\u0006 לשיטת \u0003רב?\u0004 ומשיבים: אכן, ברייתא זו שונה ואינה כדעת רב, אולם אין היא עוקרת דבריו, שכן \u0003רב תנא הוא\u0004 בעצמו \u0003ופליג\u0004 \u0005[ו\u0006יכול \u0005לחלוק]\u0006 על דברי הברייתא\u0005.\u0006","נאמר במשנה שמי ש\u0003אמר שביתתי בעיקרו\u0004 של האילן — הרי זה \u0003מהלך ממקום רגליו ועד עיקרו\u0004 של האילן \u0003אלפים אמה, ומעיקרו\u0004 של האילן \u0003לביתו\u0004 עוד \u0003אלפים אמה\u0004. \u0003נמצא מהלך משחשיכה ארבעת אלפים אמה.\u0004"],["\u0003אמר רבא:\u0004 דין זה האמור במשנתנו שאם הגדיר את מקום שביתתו המדוייק תחת האילן קנה שם שביתה \u0003והוא דכי רהיט\u0004 \u0005[שכאשר ירוץ]\u0006 \u0003לעיקרו\u0004 של האילן \u0003מטי\u0004 \u0005[יכול להגיע]\u0006 עוד לפני שבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003\"חשכה לו\" קתני\u0004 \u0005[שנינו]\u0006 משמע שמרוחק הוא יותר מכדי מרחק זה!","ומשיבים: \u0003\"חשכה\"\u0004 משמעו — שלא יוכל להגיע בעוד יום \u0003לביתו, אבל לעיקרו של אילן מצי אזיל\u0004 \u0005[יכול\u0006 להספיק \u0005ללכת].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת \u0003אמר רבא: חשכה לו\u0004 משמעו \u0003כי מסגי קלי קלי\u0004 \u0005[כשהוא הולך לאט לאט],\u0006 \u0003אבל רהיט\u0004 \u0005[\u0006אם \u0005ירוץ] —\u0006 \u0003מטי\u0004 \u0005[יגיע].\u0006","\u0003רבה ורב יוסף הוו קא אזלי באורחא\u0004 \u0005[היו הולכים בדרך\u0006 יחד\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרב יוסף: תהא שביתתנו תותי דיקלא דסביל אחוה\u0004 \u0005[תחת הדקל הנושא את אחיו]\u0006 שהיה דקל אחר נשען עליו. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך אמר לו: \u0003תותי דיקלא דפריק מריה מכרגא\u0004 \u0005[תחת הדקל שהציל את בעליו ממס הקרקע]\u0006 שהיה הדקל הזה פורה במידה כזאת שמפירותיו היו בעליו משלמים את כל מיסי הקרקע.","ושאל: \u0003ידע ליה מר\u0004 \u0005[האם אדוני יודע,\u0006 מכיר \u0005אותו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא ליה\u0004 \u0005[איני מכיר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סמוך עלי, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: אם היו שנים, אחד מכיר ואחד שאינו מכיר — זה שאינו מכיר מוסר שביתתו למכיר,\u0004 ו\u0003זה שמכיר אומר: \"תהא שביתתנו במקום פלוני\".\u0004","ומעירים: \u0003ולא היא,\u0004 ואין הדבר כן בדיוק, \u0003לא תנא ליה\u0004 \u0005[לא נשנתה אותה\u0006 ברייתא\u0005]\u0006 \u0003כר' יוסי, אלא\u0004 אמר לו כן \u0003כי היכי דליקבל לה מיניה\u0004 \u0005[כדי שיקבל\u0006 רב יוסף \u0005ממנו]\u0006 \u0003משום\u0004 ש\u0003ר' יוסי נימוקו עמו\u0004 והלכה כר' יוסי ברוב דבריו, ולכן לא יבוא רב יוסף לפקפק בדבר.","במשנה שנינו ש\u0003אם אינו מכיר\u0004 אילן או מקום מסוים אחר, \u0003או שאינו בקי\u0004 בהלכה ואינו יודע שאפשר לקנות שביתה במקום רחוק, ואמר: \"שביתתי במקומי\" — זכה לו מקומו אלפים אמה לכל רוח.","\u0003ושואלים על כך: הני\u0004 \u0005[אותן]\u0006 \u0003אלפים אמה היכן כתיבן\u0004 \u0005[היכן\u0006 הם \u0005כתובות\u0006 בתורה\u0005]?\u0006 ומשיבים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"שבו איש תחתיו\"\u0004 (שמות טז, כט) משמעו — \u0003אלו ארבע אמות,\u0004 שהן התחום הקטן ביותר כגון ליוצא מחוץ לתחומו. \u0003\"אל יצא איש ממק מו\"\u0004 (שמות טז, כט) — \u0003אלו אלפים אמה\u0004 של תחום שבת לשובת במקום, ש\"מקום\" סתם שיעורו אלפים אמה.","ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שזה שיעור מקום? \u0003אמר רב חסדא: למדנו\u0004 בדרך גזירה שווה \"\u0003מקום\" מ\"מקום\"\u0004 שנאמר כאן \"אל יצא איש ממקומו\" ונאמר בפסוק ברוצח בשגגה \"ושמתי לך מקום אשר ינוס שמה\" (שמות כא, יג). \u0003ו\u0004בפסוק זה נאמר גם \"מקום\" וגם ענין מנוסה, \u0003ו\u0004למדים \"\u0003מקום\" מ\"ניסה\"\u0004 (מנוסה). \u0003ו\u0004למדים \u0003\"ניסה\" מ\"ניסה\",\u0004 מכתוב אחר באותו ענין \"ואם יצא יצא הרוצח את גבול עיר מקלטו אשר ינוס שמה\" (במדבר לה, כו) \u0003ו\u0004למדים \u0003ניסה מ\"גבול\"\u0004 האמור אף הוא באותו פסוק. \u0003ו\u0004נלמד שוב בגזירה שווה \u0003\"גבול\" מ\"גבול\"\u0004 שנאמר שם \"ומצא אותו גואל הדם מחוץ לגבול עיר מקלטו\" (במדבר לה, כז) ונלמד עוד \u0003\"גבול\" מ\"חוץ\"\u0004 שנאמר בפסוק זה, \u0003ו\u0004אף אנו נלמד שוב בגזירה שווה \u0003\"חוץ\" מ\"חוץ\", דכתיב\u0004 \u0005[שנאמר]\u0006 בערי הלויים (שהן היו ערי מקלט) \u0003\"ומדתם מחוץ לעיר את פאת קדמה אלפים באמה\u0004 ואת פאת נגב אלפים באמה ואת פאת ים אלפים באמה ואת פאת צפון אלפים באמה\u0003\"\u0004 (במדבר לה, ה)","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003\"מקיר העיר וחוצה אלף אמה\"\u0004 (במדבר לה, ד) שהתחום הוא אלף אמה בלבד. ומשיבים: \u0003דנין\u0004 בגזירה שווה מקום שנאמר בו \u0003\"חוץ\" מ\u0004מקום אחר שנאמר בו \u0003\"חוץ\", ואין דנין \"חוץ\" מ\"חוצה\"\u0004.","ומקשים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה יוצא מזה,\u0006 מה ההבדל בין הדברים\u0005]?\u0006 \u0003הא תנא דבי\u0004 \u0005[הרי שנינו בשם\u0006 חכם \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 שלמד גזירה שווה לענין נגעי בתים מפסוק אחד שנאמר בו \u0003\"ושב הכהן\"\u0004 (ויקרא יד, לט) ומפסוק אחר שנאמר בו \u0003\"ובא הכהן\"\u0004 (ויקרא יד, מד) \u0003שדרש: זו היא שיבה זו היא ביאה,\u0004 ואם כן, שינוי באות אחת ודאי אינו מעכב לימוד זה!","ודוחים: \u0003הני מילי היכא דליכא מידי דדמי ליה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן שאין דבר\u0006 מילה \u0005הדומה לו]\u0006 \u0003אבל היכא דאיכא מידי דדמי\u0004 \u0005[היכן שיש דבר\u0006 מילה \u0005הדומה לו],\u0006 \u0003ליה — מדמי ליה ילפינן\u0004 \u0005[מן הדומה לו אנו למדים]\u0006 ולא ממה שאינו בדיוק כמוהו.","נחלקו תנאים במשנתינו אם תחום \u0003אלפים אמה\u0004 הניתנות לכל אדם ממקום שביתתו הרי הן \u0003עגולות\u0004 או מרובעות כטבלא. ושואלים: \u0003ור' חנינא בן אנטיגנוס מה נפשך\u0004 \u0005[רצונך]\u0006 מהי בדיוק שיטתו, ובאיזה אופן נסביר אותה. שכן \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 כאן \u0003גזירה שוה,\u0004 והוא לומד הלכה זו מהנאמר בערי הלויים, הרי שם \u0003פיאות\u0004 (זוויות) \u0003כתיבן\u0004 \u0005[נאמרו],\u0006 ומשמע: תחומים מרובעים. \u0003אי לית ליה\u0004 \u0005[אם אין לו]\u0006 \u0003גזירה שוה — אלפים אמה\u0004 עצמן \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006","משיבים: \u0003לעולם\u0004 תאמר \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003גזירה שוה, ושאני הכא\u0004 \u0005[ושונה כאן\u0006 בענין הערים\u0005]\u0006 שכן \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"זה יהיה להם מגרשי הערים\"\u0004 (במדבר לה, ה) כוונתו: \u0003לזה,\u0004 למגרש העיר, \u0003אתה נותן פיאות\u0004 ומרובע, \u0003ואי\u0004 (אין) \u0003אתה נותן פיאות לשובתי שבת\u0004 בכל מקום שקנו שביתה, שאין מחשבים אלא תחום עגול.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מבינים הם הדגשה זו? ומשיבים: \u0003תני\u0004 \u0005[שנינו],\u0006 \u0003רב חנניה אומר: כזה יהו כל שובתי שבת\u0004 שכל החישובים בקשר לשביתת שבת יהיו זהים.","\u0003אמר רב אחא בר יעקב: המעביר ארבע אמות ברשות הרבים\u0004 אף שם \u0003אינו חייב עד שמעביר הן ואלכסונן,\u0004 שארבע אמות שנאמרו הן רק יסוד המידה שעל פיה מחשבים, אבל למעשה דנים על פי האלכסון הגדול יותר.","ו\u0003אמר רב פפא בדיק לן\u0004 \u0005[בחן אותנו]\u0006 \u0003רבא\u0004: \u0003עמוד ברשות הרבים גבוה עשרה\u0004 טפחים \u0003ורוחב ארבעה\u0004 טפחים, האם \u0003צריך\u0004 שארבעה טפחים אלה יהיו \u0003הן ואלכסונן או לא? ואמרינן ליה\u0004 \u0005[ואמרנו לו]:\u0006 \u0003לאו היינו\u0004 \u0005[אין זה]\u0006 כדברי \u0003רב חנניה? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רב חנניה אומר: כזה יהו כל שובתי שבת,\u0004 משמע שבכל דיני שביתה בשבת מודדים אנו גם את האלכסון.","שנינו במשנה: \u0003וזה הוא שאמרו: העני מערב ברגליו,\u0004 שיכול העני שאין ברשותו פת לעירוב לקנות שביתה כשנמצא בתוך תחום ואומר: קובע אני שביתתי במקום זה, \u0003אמר ר' מאיר: אנו אין לנו אלא עני\u0004 שיכול לעשות כן שהקלו עליו חכמים, אבל מי שיש פת בידו אינו יכול לקנות שביתה בדרך זו, אלא בפת. ואילו ר' יהודה אומר שבין עני ובין עשיר יכולים להשתמש בדרך זו של עירוב.","\u0003אמר רב נחמן: מחלוקת\u0004 זו בין ר' מאיר ור' יהודה היא באם אמר אדם: \u0003\"\u0004שביתתי \u0003במקומי\",\u0004 ש\u0003ר' מאיר סבר: עיקר\u0004 תיקונו ותקנתו של ה\u0003עירוב\u0004 הוא \u0003בפת,\u0004"],["\u0003עני\u0004 המהלך בדרכים ואין לו פת \u0003הוא דאקילו רבנן עילויה\u0004 \u0005[שהקילו חכמים עליו]\u0006 לשבות במקום על ידי שיאמר שביתתי בו, \u0003אבל עשיר\u0004 היושב בביתו ויש לו פת — \u0003לא.\u0004","\u0003ור' יהודה סבר: עיקר עירוב ברגל\u0004 שילך למקום ויאמר שקונה בו שביתה, \u0003אחד עני ואחד עשיר. אבל\u0004 לגבי האומר \u0003\"\u0004שביתתי \u0003במקום פלוני\"\u0004 והוא אינו מצוי שם — \u0003דברי הכל\u0004: שעירוב זה רק אם היה \u0003עני\u0004 ומהלך בדרך — \u0003אין\u0004 \u0005[כן]\u0006 אבל \u0003עשיר — לא.\u0004","\u0003\"וזו היא שאמרו\"\u0004 במשנה \"העני מערב ברגליו\" \u0003מאן קתני לה\u0004 \u0005[מי הוא\u0006 זה \u0005ששנה אותה]\u0006 — \u0003ר' מאיר. ואהייא קאי\u0004 \u0005[ועל איזה\u0006 דבר \u0005עומד,\u0006 מתייחס\u0005]\u0006 — על מה שאמרו \u0003\"אינו מכיר או שאינו בקי בהלכה\"\u0004 ואילו בהמשך הדברים במשנה \u0003\"ולא אמרו מערבין בפת אלא להקל\" מאן קתני לה\u0004 \u0005[מי שנה אותה]\u0006 הלא הוא \u0003ר' יהודה\u0004 ששיטתו שהעירוב נועד גם לעשיר.","ואילו \u0003רב חסדא אמר\u0004: לא כך יש להבין את המחלוקת במשנה, אלא ה\u0003מחלוקת\u0004 ביניהם היא באומר \u0003\"\u0004שביתתי \u0003במקום פלוני\"\u0004 שקניית השביתה אינה נעשית לא ברגל ולא בפת, ש\u0003ר' מאיר סבר: עני — אין\u0004 \u0005[כן]\u0006 קונה שביתה, \u0003עשיר — לא. ור' יהודה סבר: אחד עני ואחד עשיר. אבל\u0004 האומר: \u0003\"\u0004שביתתי \u0003במקומי\" דברי הכל: אחד עני ואחד עשיר\u0004 מועיל להם, שהכל מודים כי \u0003עיקר עירוב ברגל.\u0004","\u0003\"וזו היא שאמרו העני\u0004 מערב ברגליו \u0003\"מאן קתני לה\u0004 \u0005[מי הוא ששנה אותה]\u0006 — \u0003ר' מאיר, ואהייא קאי\u0004 \u0005[ועל איזה\u0006 דבר \u0005עומד,\u0006 מתייחס\u0005],\u0006 על דבר זה: \u0003\"מי שבא בדרך וחשכה\"\u0004 אבל לדעת ר' יהודה גם אם היה עשיר יכול לומר כך. \u0003\"ולא אמרו מערבין בפת אלא להקל\" מאן קתני לה\u0004 \u0005[מי הוא ששנה אותה]\u0006 — אלו \u0003דברי הכל\u0004.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן\u0004 שאמר שמחלוקת ר' מאיר ור' יהודה בשאמר \"שביתתי במקומי\": \u0003אחד עני ואחד עשיר מערבין בפת, ולא יצא עשיר חוץ לתחום ויאמר: \"שביתתי במקומי\" — לפי שלא אמרו מערבין ברגל אלא למי שבא בדרך וחשכה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה אומר: אחד עני ואחד עשיר מערבין ברגל, ו\u0004כן \u0003יצא\u0004 (יכול לצאת) \u0003עשיר חוץ לתחום ויאמר: \"תהא שביתתי במקומי\", וזה הוא עיקרו של עירוב. ו\u0004אולם \u0003התירו חכמים לבעל הבית לשלח עירובו ביד עבדו, ביד בנו, ביד שלוחו בשביל להקל עליו\u0004. ואם כן מבואר פה שהמחלוקת היא כפי שהגדיר רב נחמן.","\u0003אמר ר' יהודה: מעשה באנשי בית\u0004 משפחת \u0003ממל ובאנשי בית גוריון ב\u0004כפר \u0003ארומא\u0004 שהיה בתוך ארבעת אלפים אמה לתחומם \u0003שהיו מחלקין גרוגרות וצימוקין לעניים בשני בצורת, ובאין עניי כפר שיחין ועניי כפר חנניה ומחשיכין על התחום, למחרת משכימין ובאין\u0004 לקבל את הגרוגרות.","ורואים אם כן שמערבים ברגל אם אומר \"שביתתי במקומי\" \u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתינו גם כן מדוייקת]\u0006 כהסברו של רב נחמן, \u0003דקתני\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שיצא לילך לעיר שמערבין לה, והחזירו חבירו\u0004 שעיכבו מלכת — \u0003הוא מותר לילך, וכל בני העיר אסורין, דברי ר' יהודה.\u0004","\u0003והוינן\u0004 \u0005[והיינו עסוקים]\u0006 \u0003בה,\u0004 ומתקשים במשנה זו: \u0003מאי שנא איהו ומאי שנא אינהו\u0004 \u0005[במה שונה הוא ובמה שונים הם]\u0006 שלו מותר ולהם אסור? \u0003ואמר רב הונא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שיש לו\u0004 לאותו אדם שני \u0003בתים, ושני תחומי שבת ביניהן.\u0004","\u0003איהו\u0004 \u0005[הוא],\u0006 \u0003כיון דנפקא ליה לאורחא\u0004 \u0005[שיצא לו לדרך] —\u0006 \u0003הוה ליה\u0004 \u0005[הריהו נעשה]\u0006 כ\u0003עני,\u0004 שהרי לא נתכוין לחזור לביתו אלא להמשיך עד לביתו האחר, ולכן יכול הוא לקנות שביתה בסוף התחום באמירה בלבד.","\u0003והנך עשירין נינהו\u0004 \u0005[ואלה\u0006 בני עירו \u0005עשירים הם]\u0006 שהרי יש להם מזונות בבתיהם וצריכים לקנות עירוב מבעוד יום. \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0005ש\u0006\u0003כל\u0004 השנוי באומר \u0003\"\u0004שביתתי \u0003במקום פלוני\"\u0004 מדובר ש\u0003עני אין\u0004 \u0005[כן]\u0006 אבל \u0003עשיר — לא. ומסכמים: אכן, שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003מתני ליה\u0004 \u0005[היה משנה,\u0006 מלמד \u0005אותו]\u0006 \u0003רב חייא בר אשי לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 שהיה נוכח שם באותה שעה, את משנתינו \u0003\"אחד עני ואחד עשיר\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: סיים בה נמי\u0004 \u0005[גם כן]\u0006 לאחר לימוד ענין זה: \u0003הלכה כר' יהודה\u0004.","מסופר: \u0003רבה בר רב חנן הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דאתי\u0004 \u0005[לבוא]\u0006 מהעיר \u0003ארטיבנא לפומבדיתא.\u0004"],["\u0003אמר\u0004 (היה רגיל לומר): \u0003\"תהא שביתתי בצינתא\"\u0004 ישוב שנמצא בין התחומים של שני המקומות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אב יי: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה נוהג כן, משום ש\u0003ר' מאיר ור' יהודה — הלכה כר' יהודה, ואמר רב חסדא: מחלוקת\u0004 שאמר \u0003\"\u0004תהא שביתתי \u0003במקום פלוני\",\u0004 וסומך אתה על דברי ר' יהודה וקונה שביתה באמצע הדרך בעודך במקומך, ואולם","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמן\u0004 לא כך הסביר, \u0003ו\u0004עוד \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי\u0004 ולא אעשה עוד כן.","\u0003אמר רמי בר חמא: הרי אמרו\u0004 מי ש\u0003שבת\u0004 (קנה שביתה) ברגליו \u0003יש לו ארבע אמות\u0004 במקומו, וחוץ מהן עוד אלפיים אמה. \u0003הנותן את עירובו\u0004 במקום, האם \u0003יש לו ארבע אמות\u0004 סביב למקום העירוב, \u0003או לא?\u0004","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא ושמע\u0006 פתרון\u0005]\u0006 ממה ששנינו: \u0003לא אמרו מערבין בפת אלא להקל על העשיר, שלא יצא ויערב ברגליו. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שהמערב בפת \u0003אין לו\u0004 ארבע אמות — \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003להקל?! להחמיר הוא!\u0004 ואם כן בודאי כל ההקלות שיש במערב ברגליו, קיימות גם במערב בפת!","ודוחים: אין זו ראיה כי \u0003אפילו הכי\u0004 בלא שיהיו לו ארבע אמות \u0003ניחא ליה\u0004 \u0005[כך נוח לו],\u0006 \u0003כי היכי דלא נטרח וניפוק\u0004 \u0005[כדי שלא\u0006 יצטרך \u0005לטרוח ולצאת],\u0006 ואפשר לומר שעירוב בפת הוא הקלה אף שמפסיד על ידי כך ארבע אמות.","\u0003מי שיצא לילך בעיר שמערבין בה\u0004 ונמצאת בתוך תחום ארבעת אלפים אמה למקומו שאפשר להגיע אליה על ידי עירוב, \u0003והחזירו חבירו\u0004 שלא ילך בערב לעיר האחרת ונשאר בעירו — \u0003הוא מותר לילך\u0004 למחרת שנחשב כאילו קנה שביתה באמצע הדרך, אפילו לא פירש כן. \u0003וכל\u0004 שאר \u0003בני העיר — אסורין, דברי ר' יהודה.\u0004","\u0003ר' מאיר אומר: כל\u0004 מי \u0003שהוא יכול לערב,\u0004 ועקר שביתתו במקומו הראשון \u0003ולא עירב,\u0004 שלא אמר לפחות שהוא קונה שביתה במקום אחר — \u0003הרי זה חמר גמל\u0004 ונמשך לשני הצדדים, ולהלכה דנים אותו כאילו קנה שביתה בשני המקומות כאחת ואינו מותר אלא בתחום אלפיים אמה שבין עירו לעיר האחרת, אבל לא לצד השני, שיתכן שאכן קנה שביתה אף בעיר האחרת והרוויח את האלפיים אמה שמן העיר האחרת והלאה אבל הפסיד את האלפיים שבמצד שני לעירו.","על האמור במשנה שלו מותר ללכת ולשאר בני העיר אסור, שואלים: \u0003מאי שנא איהו ומאי שנא אינהו\u0004 \u0005[במה שונה הוא ומה שונים הם]\u0006 שלו מותר ולהם אסור? \u0003אמר רב הונא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שיש לו שני בתים, וביניהן שני תחומי שבת.\u0004","\u0003איהו\u0004 \u0005[הוא],\u0006 \u0003כיון דנפק ליה לאורחא\u0004 \u0005[שיצא לו לדרך] —\u0006 \u0003הוה ליה\u0004 \u0005[הריהו נעשה]\u0006 \u0003עני.\u0004 ועני יכול, כאמור, לקנות שביתה באמירה בלבד שרצונו לשבות ב\"מקום פלוני\". \u0003והני עשירי נינהו\u0004 \u0005[ואלה,\u0006 שאר בני העיר, \u0005עשירים הם]\u0006 שלא היה בדעתם כלל לצאת מן העיר בלילה ואינם יכולים לקנות שביתה בקצה התחום אלא אם כן יניחו שם עירוב.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מי שיש לו שני בתים, וביניהן שני תחומי שבת, כיון שהחזיק בדרך\u0004 שהחל ללכת וברור שהוא יוצא אף שלא אמר במפורש \"שביתתי בסוף תחום\" — \u0003קנה עירוב, דברי ר' יהודה.\u0004","\u0003יתר על כן אמר ר' יוסי בר' יהודה: אפילו מצאו חבירו\u0004 לפני צאתו ממש לדרך \u0003ואמר לו: \"לין פה, עת חמה הוא, עת צינה הוא\"\u0004 ואין כדאי ללכת כעת — \u0003למחר משכים והולך.\u0004","שדי במה שדעתו היתה ללכת \u0003אמר רבה: לומר\u0004 שהוא קונה שביתה \u0005—\u0006 \u0003כולי עלמא לא פליגי דצריך\u0004 \u0005[הכל אינם חולקים שהוא צריך],\u0006 שיאמר לו חבירו \"לין\" כו' ובלא אמירה זו יתכן שלא יקנה שביתה בביתו השני, שיש לומר שאולי מה שחזר לביתו הוא משום שחזר בו מהכוונה לקנות שם שביתה \u0003כי פליגי\u0004 \u0005[כאשר נחלקו] —\u0006 הרי זה אם צריך \u0003להחזיק.\u0004 שר' יהודה מדגיש ש\"החזיק בדרך\", ור' יוסי בר' יהודה סבור שאינו צריך אף להחזיק בדרך, ודי שהוא מתכוון לצאת.","\u0003ורב יוסף אמר\u0004, כך יש להבין את המחלוקת: \u0003להחזיק — דכולי עלמא לא פליגי דצריך\u0004 \u0005[הכל אינם חולקים שהוא צריך]\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה אם צריך הוא \u0003לומר\u0004 שהוא קונה שביתה בסוף התחום או אינו צריך לומר.","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר עולא: מי שהחזיק בדרך והחזירו חבירו — הרי הוא מוחזר ומוחזק.\u0004","ומתחילה תוהים על עצם לשונו של עולא: \u0003אי\u0004 \u0005[אם]\u0006 אמת ש\u0003מוחזר\u0004 הוא, משמע שהוא כבני המקום שנשאר בו, אם כן \u0003למה מוחזק\u0004 בדרך? \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מוחזק\u0004 הוא — \u0003למה\u0004 הוא \u0003מוחזר?\u0004","אלא יש לתקן ש\u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 עולא: \u0003אף על פי שמוחזר\u0004 ושוהה במקומו בכל זאת הריהו \u0003מוחזק. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 הוא\u0005]\u0006 אומר — \u0003כ\u0004שיטת \u0003רב יוסף,\u0004 שהכל מודים שצריך להחזיק בדרך, \u0003ואליבא\u0004 \u0005[ועל פי\u0006 דברי\u0005]\u0006 \u0003ר' יוסי בר' יהודה\u0004.","מסופר: \u0003רב יהודה בר אישתתא אייתי ליה\u0004 \u0005[הביא לו]\u0006 בליל שבת \u0003כלכלה\u0004 (סל) של \u0003פירי\u0004 \u0005[פירות]\u0006 \u0003לרב נתן בר אושעיא. כי הוה אזיל\u0004 \u0005[כאשר הלך]\u0006 לביתו \u0003שבקיה עד דנחית דרגא\u0004 \u0005[הניח לו עד שירד מדריגה\u0006 אחת מכבש המדריגות\u0005],\u0006 \u0005ואחר כך\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בית הכא\u0004 \u0005[לין כאן],\u0006 ומה שהניחו ללכת היה כדי שיחזיק בדרך. \u0003למחר קדים ואזיל\u0004 \u0005[למחרת השכים והלך]\u0006"],["\u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 עשה כן — \u0003כ\u0004דעת \u0003רב יוסף\u0004 שצריך להחזיק בדרך ושיאמרו לו \"לין פה\", \u0003ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי בר יהודה\u0004","ודוחים: \u0003לא,\u0004 כי אפשר לומר שנהג \u0003כרבה ואליבא\u0004 \u0005[ולפי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה,\u0004 ואמר קודם לכך שהוא קונה שביתה באמצע הדרך. במשנה שנינו: \u0003\"ר' מאיר אומר: כל שיכול לערב\u0004 ולא עירב הרי זה חמר גמל\u0003\"\u0004. ושואלים: \u0003הא תנינא חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005שנינו\u0006 בדומה לזה \u0005פעם אחת]:\u0006 \u0003ספק, ר' מאיר ור' יהודה אומרים: הרי זה חמר גמל.\u0004 ואף כאן פשוט שהרי בכל ספק פוסק כן ר' מאיר! \u0003א מר ר' ששת\u0004: יש בכל זאת צורך לומר זאת, כדי ש\u0003לא תימא טעמא\u0004 \u0005[שלא תאמר\u0006 ש\u0005הטעם]\u0006 של \u0003ר' מאיר\u0004 רק אם \u0003ספק עירב ספק לא עירב,\u0004 רק \u0003הוא דהוי\u0004 \u0005[שנעשה]\u0006 \u0003חמר גמל, אבל ודאי לא עירב — לא הוי\u0004 \u0005[אינו]\u0006 \u0003חמר גמל\u0004.","","","אלא שב להיות כבן מקומו, \u0003אלא\u0004 אמור: \u0003אפילו ודאי לא עירב\u0004 פעמים שהוא \u0003חמר גמל. דהא הכא\u0004 \u0005[שהרי כאן]\u0006 \u0003ודאי לא עירב\u0004 שהרי חזר למקומו, \u0003וקא הוי\u0004 \u0005[והרי הוא]\u0006 \u0003חמר גמל,\u0004 ולכן הוצרך לומר שאף במקרה זה כשאין ספק עירוב כלל אלא לא ברור היכן מקום שביתתו, אף זה דינו להיות חמר גמל.","\u0003מי שיצא\u0004 במזיד שלא לצורך מצוה \u0003חוץ לתחום — אפילו אמה אחת לא יכנס. ר' אליעזר אומר: שתים\u0004 אמות — \u0003יכנס, שלש — לא יכנס.\u0004","","","\u0003אמר ר' חנינא:\u0004 היתה \u0003רגלו אחת בתוך התחום, ורגלו אחת חוץ לתחום — לא יכנס, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם תשיב משבת רגלך\"\u0004 (ישעיהו נח, יג). \u0003\"רגלך\" כתיב\u0004 \u0005[נאמר]\u0006 בלשון יחיד. משמע אף בהכנסת רגל אחת יש משום חילול שבת.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רגלו אחת בתוך התחום ורגלו אחת חוץ לתחום — יכנס!\u0004 ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003אחרים היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחרים אומרים: למקום שרובו הוא נזקר\u0004 (פונה). הרי שמותר לו להיכנס שהרי לא הוציא אלא רגל אחת. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006 בלשון אחרת\u0005].\u0006 \u0003אמר ר' חנינא: רגלו אחת בתוך התחום ורגלו אחת חוץ לתחום — יכנס, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם תשיב משבת רגלך\" \"רגליך\"\u0004 מלשון רבים \u0003קרינן\u0004 \u0005[קוראים אנו],\u0006 אבל רגל אחת — מותר. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יכנס!\u0004 ומשיבים: \u0003הוא\u0004 ש\u0003אמר כ\u0004שיטת \u0003אחרים דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003למקום שרובו הוא נזקר.\u0004 דבמשנה שנינו: \u0003\"ר' אליעזר אומר: שתים — יכנס, שלש — לא יכנס\".\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: אחת — יכנס, שתים — לא יכנס.\u0004 ועונים: \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זו\u0006 משנתנו\u0005]\u0006 מדברת כש\u0003עקר\u0004 מאמה \u0003חדא וקם אתרתי\u0004 \u0005[אחת ועמד בשניה]\u0006 — מותר להיכנס. \u0003הא\u0004 \u0005[זו\u0006 הברייתא\u0005],\u0006 ש\u0003עקר\u0004 מאמה \u0003שניה ועמד בשלישית\u0004 — לא יכנס. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אליעזר אומר: אפילו אמה אחת לא יכנס!\u0004 ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר נשנתה אותה\u0006 ברייתא\u0005]\u0006 הרי היא \u0003למודד, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ולמודד\u0004 שאם שבת אדם במקומו ומודד משם את תחומו לפי פסיעותיו \u0003שאמרו נותנין לו אלפים אמה — אפילו סוף מדתו כלה במערה\u0004 לא יכנס פנימה אל תוכה אפילו אמה אחת יותר ממידתו.","","","\u0003מי שהחשיך\u0004 בדרך ולן במקומו ומצא שהוא \u0003חוץ לתחום — אפילו אמה אחת לא יכנס. ר' שמעון אומר: אפילו חמש עשרה אמות יכנס, שאין המשוחות\u0004 (המודדים) \u0003ממצין את המדות\u0004 לשים את סימן התחום בקצה הגבול ממש אלא פנימה ממנו \u0003מפני הטועין.\u0004 ו\u0003גמרא\u0004 על מה ששנינו במשנה \"מפני הטועים\" \u0003תנא\u0004 \u0005[שנה\u0006 בברייתא\u0005]:\u0006 \u0003מפני טועי המדה,\u0004 כלומר מתוך חשש שמא טעו במדידתם מחמירים הם ופוחתים קצת מן התחום.","","","\u0003כיצד מעברין את הערים\u0004 להחשיב בתחום העיר עצמה את כל הבליטות? עושים קו ישר בקצה העיר לארכה ולרחבה ואם היה \u0003בית נכנס\u0004 או \u0003בית יוצא\u0004 מקו זה, \u0003פגום\u0004 (בליטה) \u0003נכנס פגום יוצא,\u0004 וכן אם \u0003היו שם גדודיות\u0004 (שרידי כתלים וחומות) \u0003גבוהות עשרה טפחים,\u0004"],["\u0003וגשרים ונפשות\u0004 (מצבות קבר העשויות כמו בית) \u0003שיש בהן בית דירה — מוציאין את המדה\u0004 של העיר מהן והלאה כאילו יש \u0003כנגדן\u0004 מבנה דומה בזווית אחרת. \u0003ועושין אותה\u0004 (את העיר) לפני מדידת תחום שבת \u0003כמין טבלא מרובעת, כדי שיהא נשכר את הזויות\u0004 אף על פי שאין בתים באותן זויות.","מתחילה דנים בדיוק לשון המשנה. ובכך נחלקו \u0003רב ושמואל: חד תני\u0004 \u0005[אחד\u0006 מהם \u0005שנה]\u0006 \u0003\"מעברין\" וחד תני\u0004 \u0005[ואחד\u0006 מהם \u0005שנה]\u0006 \u0003\"מאברין\".\u0004","ומסבירים: \u0003מאן דתני\u0004 \u0005[מי ששנה]\u0006 \u0003\"מאברין\"\u0004 פירש שהכוונה במשנתינו היא מלשון \u0003אבר אבר\u0004 שיש בכך מעין הוספת איברים לעיר כנגד הקיימים ומהם נמדד התחום. \u0003ומאן דתני\u0004 \u0005[ומי ששנה]\u0006 \u0003\"מעברין\" — כאשה עוברה\u0004 שבולטת ביטנה, כך במשנתינו מדובר על הכנסת כל הבליטות הללו לתחום העיר.","ואגב מחלוקת זו של רב ושמואל בפירוש המילות, מביאים מחלוקות אחרות שלהם בדומה לכך: \u0003מערת המכפלה, רב ושמואל\u0004 נחלקו כיצד היתה כפולה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 במערה זו יש \u0003שני בתים זה לפנים מזה. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: בית ועלייה על גביו.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003זה על גב זה — היינו\u0004 \u0005[זוהי]\u0006 משמעות לשון \u0003\"מכפלה\". אלא למאן דאמר\u0004 \u0005[אלא ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שני בתים זה לפנים מזה, מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"מכפלה\"?\u0004 הרי בית רגיל הוא שיש בו שני חדרים!","אלא יש לפרש: \u0003כפולה בזוגות,\u0004 שקבורים בה זוגות זוגות. וכעין מה שדרשו שם העיר חברון הקרויה \u0003\"ממרא קרית הארבע\"\u0004 (בראשית לה, כז) \u0003אמר ר' יצחק: קרית הארבע זוגות\u0004 שנקברו שם: \u0003אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה.\u0004","ועוד נחלקו: \u0003\"ויהי בימי אמרפל\"\u0004 (בראשית יד, א), \u0003רב ושמואל\u0004 שניהם מסכימים שאמרפל הוא נמרוד אלא \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: נמרוד\u0004 הוא \u0003שמו\u0004 האמיתי. \u0003ולמה נקרא שמו אמרפל?\u0004 נוטריקון: \u0003שאמר\u0004 (ציוה) \u0003והפיל לאברהם אבינו בתוך כבשן האש\u0004 כשמרד בו ולא קבל את אלוהותו. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אמרפל\u0004 הוא \u0003שמו\u0004 האמיתי, \u0003ולמה נקרא שמו נמרוד — שהמריד את כל העולם כולו עליו במלכותו.\u0004","וכן נחלקו בפירוש הפסוק \u0003\"ויקם מלך חדש על מצרים\u0004 אשר לא ידע את יוסף\" (שמות א, ח) \u0003רב ושמואל. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מלך \u0003חדש ממש\u0004 היה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מלך ותיק היה, אלא \u0003שנתחדשו גזרותיו.\u0004","ומסבירים את שיטותיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003חדש ממש — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"חדש\", ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003שנתחדשו גזרותיו\u0004 — סומך \u0003מדלא כתיב\u0004 \u0005[מתוך שלא נאמר]\u0006 \u0003\"וימת וימלוך\"\u0004 כפי שנאמר במלכי אדום למשל, משמע שאותו מלך הוא.","ומקשים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003שנתחדשו גזרותיו, הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"אשר לא ידע את יוסף\"\u0004 ואם אותו מלך היה, כיצד לא ידע את יוסף? ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אשר לא ידע את יוסף\" — דהוה דמי כמאן\u0004 \u0005[שהיה דומה כמי]\u0006 ש\u0003לא ידע ליה\u0004 \u0005[לו\u0006 את\u0005]\u0006 \u0003יוסף כלל.\u0004","\u0003(סימן: שמונה עשרה ושנים עשר למדנו בדוד ויבן)\u0004 שהם סימני המסורות הכתובות להלן.","\u0003אמר ר' יוחנן: שמונה עשר ימים גדלתי אצל ר' אושעיא בריבי\u0004 (הדגול) \u0003ולא למדתי ממנו אלא דבר אחד במשנתינו: כיצד מאברין את הערים — באלף\u0004.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן שנים עשר תלמידים היו לו לר' אושעיא בריבי, ושמונה עשר ימים גידלתי ביניהן, ולמדתי לב כל אחד ואחד\u0004 כלומר מה מהותו ואופיו, \u0003ו\u0004כמה \u0003חכמת כל אחד ואחד,\u0004 וכיצד אמר שלא למד אלא דבר אחד?","ומשיבים: ייתכן ש\u0003לב כל אחד ואחד וחכמת כל אחד ואחד — גמר\u0004 \u0005[למד],\u0006 \u0003גמרא\u0004 \u0005[לימוד\u0006 של ממש\u0005] —\u0006 \u0003לא גמר\u0004 \u0005[למד].\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר אחר: \u0003מנייהו דידהו\u0004 \u0005[מהם עצמם] —\u0006 \u0003גמר\u0004 \u0005[למד],\u0006 \u0003מיניה דידיה\u0004 \u0005[ממנו עצמו] —\u0006 \u0003לא גמר\u0004 \u0005[למד].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דבר אחד במשנתינו קאמר\u0004 \u0005[שאמר]\u0006 ושאר לימודים היה בברייתות או בשאר עניני לימוד.","\u0003ואמר ר' יוחנן\u0004 על אותה תקופה: \u0003כשהיינו לומדים תורה אצל ר' אושעיא\u0004 היתה הדחקות מרובה כל כך ומספר התלמידים גדול כל כך ש\u0003היינו יושבין ארבעה ארבעה באמה\u0004 מרובעת. \u0003אמר רבי\u0004 מעין זה: \u0003כשהיינו לומדין תורה אצל ר' אלעזר בן שמוע, היינו יושבין ששה ששה באמה.\u0004","\u0003אמר ר' יוחנן\u0004 על רבו זה: \u0003ר' אושעיא בריבי בדורו\u0004 היה גדול \u0003כר' מאיר בדורו, מה ר' מאיר בדורו לא יכלו חבריו לעמוד על סוף דעתו\u0004 משום גדלותו היתירה — \u0003אף ר' אושעיא לא יכלו חבריו לעמוד על סוף דעתו\u0004.","וכיון שדובר באלה \u0003אמר ר' יוחנן: לבן של ראשונים\u0004 גדול \u0003כפתחו של אולם\u0004 (שהיה עשרים על ארבעים אמה). \u0003ו\u0004ליבם \u0003של אחרונים כפתחו של היכל\u0004 (עשר על עשרים אמה). \u0003ואנו\u0004 — לבנו \u0003כמלא נקב מחט סידקית\u0004 (מחט תפירה).","והוא מסביר: \u0003ראשונים\u0004 — הכוונה ל\u0003ר' עקיבא, אחרונים\u0004 — הכוונה לתלמידו \u0003ר' אלעזר בן שמוע. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך נתכוון: \u0003ראשונים — ר' אלעזר בן שמוע, אחרונים — ר' אושעיא בריבי. ואנו כמלא נקב מחט סידקית\u0004.","כיון שדובר בירידתם הנמשכת של הדורות, \u0003אמר אביי: ואנן, כי סיכתא בגודא לגמרא\u0004 \u0005[אנו\u0006 יכולתנו \u0005כמו יתד בכותל ל\u0006ענין \u0005לימוד]\u0006 שכשם שקשה מאוד להכניסו ולתוקעו שם כך גם הלימוד לנו. \u0003אמר רבא: ואנן, כי אצבעתא בקירא לסברא\u0004 \u0005[ואנו, כמו אצבע בשעווה ל\u0006ענין \u0005סברה]\u0006 שאין האצבע נכנסת היטב בשעווה ואינה מוציאה משם דבר. \u0003אמר רב אשי: אנן, כי אצבעתא בבירא\u0004 \u0005[אנו, כמו אצבע בבור]\u0006 \u0003ל\u0004ענין \u0003שכחה,\u0004 שכשם שהאצבע טובעת בתוך הבור הגדול בקלות רבה כך גם אנו ממהרים לשכוח תלמודנו.","וכיון שדובר בענין לימוד וקליטת הנלמד מביאים את ש\u0003אמר רב יהודה אמר רב: בני יהודה שהקפידו על\u0004 דקדוק \u0003לשונם\u0004 ונקיותה, \u0003נתקיימה תורתם בידם. בני גליל שלא הקפידו על לשונם, לא נתקיימה תורתם בידם\u0004.","ושואלים: \u0003מידי בקפידא תליא מילתא\u0004 \u0005[וכי בהקפדה\u0006 בדבר זה \u0005תלוי הדבר]?\u0006 הלא אין הדבר תלוי אם אדם מקפיד או אינו מקפיד בכך. \u0003אלא: בני יהודה דדייקי לישנא, ומתנחי להו סימנא\u0004 \u0005[שהיו מדייקים\u0006 מדקדקים \u0005בלשון\u0006 דיבורם \u0005ומניחים להם סימן\u0006 בלימודם\u0005],\u0006 \u0003נתקיימה תורתן בידן. בני גליל דלא דייקי לישנא, ולא מתנחי להו סימנא\u0004 \u0005[שלא היו מדייקים בלשונם ולא הניחו סימן],\u0006 \u0003לא נתקיימה תורתן בידם.\u0004","ועוד: \u0003בני יהודה גמרו מחד רבה\u0004 \u0005[למדו מרב אחד],\u0006 ולכן \u0003נתקיימה תורתן בידן,\u0004 שהיתה ביד הלומד שיטת יסוד אחת. \u0003בני גליל דלא גמרי מחד רבה\u0004 \u0005[שלא למדו מרב אחד],\u0006 אלא היו לומדים מכמה מורים, \u0003לא נתקיימה תורתן בידם,\u0004 שהיו מערבים גישות ושיטות של חכמים שונים.","\u0003רבינא אמר: בני יהודה דגלו מסכתא\u0004 \u0005[שהיו מגלים את המסכת\u0006 שילמדו\u0005],\u0006 שלפני תחילת הלימוד במסכת מסויימת היו מודיעים ומגלים ברבים שמסכת זו תילמד במחצית השנה הבאה, והיו הכל מתכוננים ללימודה (גאונים), נתקיימה \u0003תורתן בידם. בני גליל\u0004 ש\u0003לא גלו מסכתא\u0004 \u0005[היו מגלים את המסכת],\u0006 \u0003לא נתקיימה תורתן בידם.\u0004","וכן מסופר כי \u0003דוד גלי מסכתא\u0004 \u0005[היה מגלה את המסכת\u0006 שילמדו\u0005],\u0006 \u0003שאול לא גלי מסכתא\u0004 \u0005[לא היה מגלה את המסכת].\u0006 \u0003דוד דגלי מסכתא\u0004 \u0005[דוד שגלה מסכת]\u0006 \u0003כתיב ביה\u0004 \u0005[נאמר בו]:\u0006 \u0003\"יראיך יראוני וישמחו\"\u0004 (תהילים קיט, עד) שהיו הכל מוכנים ונהנים מתורתו, \u0003שאול\u0004 ש\u0003לא גלי מסכתא\u0004 \u0005[גלה מסכת]\u0006 \u0003כתיב ביה\u0004 \u0005[נאמר בו]:\u0006 \u0003\"אל כל אשר יפנה\u0004"],["\u0003ירשיע\"\u0004 (שמואל א' יד, מז). וכיון שדובר בשאול, באים לסיים בשבחו.","\u0003ואמר ר' יוחנן: מנין שמחל לו הקדוש ברוך הוא על אותו עון\u0004 שחטא בנוב עיר הכהנים — \u0003שנאמר\u0004 בדברי שמואל אליו: \u0003\"\u0004ויתן ה' גם את ישראל עמך ביד פלישתים \u0003ומחר אתה ובניך עמי\"\u0004 (שמואל א' כח, יט) ונדייק בלשון: \u0003עמי\u0004 — משמעו \u0003במחיצתי.\u0004 כלומר באותה דרגה עם צדיק גמור כשמואל.","וחוזרים לשאלה הקודמת בדבר הקריאה הנכונה של המלה עבור (אם בא' או בע'). \u0003אמר ר' אבא: אי איכא דמשאיל להו\u0004 \u0005[היש מי שישאל את]\u0006 \u0003בני יהודה דדייקי לשני\u0004 \u0005[שמדקדקים בלשונם]\u0006 האם \u0003מאברין תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003או מעברין תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]?\u0006 וכעין ספק זה במשנה אחרת לענין מומי בכור: \u0003אכוזו תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003או עכוזו תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]?\u0006 ומשיבים: \u0003ידעי\u0004 \u0005[ידעו הם],\u0006","\u0003שאילינהו\u0004 \u0005[שאלו\u0006 אותם\u0005]\u0006 \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]:\u0006 \u0003איכא דתני\u0004 \u0005[יש ששונה]\u0006 \u0003מאברין, ואיכא דתני\u0004 \u0005[ויש ששונה]\u0006 \u0003מעברין. איכא דתני\u0004 \u0005[יש ששונה]\u0006 \u0003אכוזו ואיכא דתני\u0004 \u0005[ויש שונה]\u0006 \u0003עכוזו.\u0004 כלומר נוסחאות עתיקות הן, ושתיהן אינן שיבוש.","כיון שהוזכר כי \u0003בני יהודה דייקי לישנא\u0004 \u0005[מדייקים בלשונם]\u0006 \u0003מאי היא\u0004 \u0005[מהו\u0006 ענין זה\u0005]?\u0006 מביאים דוגמא: \u0003דההוא\u0004 (אדם אחד) \u0003בר\u0004 \u0005[בן]\u0006 \u0003יהודה\u0004 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לשומעיו: \u0003טלית יש לי למכור. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003גוון טליתך? אמר להו\u0004 \u0005[להם]:\u0006 \u0003כתרדין עלי אדמה.\u0004 שאמר בלשון מדוקדקת מהו בדיוק גוון הטלית, שהוא ירוק כצבע התרד בשעת צמיחתו.","\u0003בני גליל דלא דייקי לישנא מאי היא\u0004 \u0005[בני הגליל שלא דייקו בלשונם מהו]?\u0006 ואף כאן מביאים דוגמאות: \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]\u0006 \u0003דההוא בר גלילא\u0004 \u0005[אדם אחד בן גליל],\u0006 \u0003דהוה קאזיל ואמר להו\u0004 \u0005[אותו שהיה הולך ואומר להם\u0006 לאנשים]: \u0003\"אמר למאן\u0004 \u0005[למי],\u0006 \u0003אמר למאן\u0004 \u0005[למי]\u0006 \u0003\"? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003גלילאה\u0004 \u0005[גלילי]\u0006 \u0003שוטה,\u0004 שאין אתה מדקדק בלשונך למה כוונתך? שהגליליים לא היו מבטאים כראוי את אותיות הגרון, ואין לדעת אם כוונתך: \u0003חמר למירכב\u0004 \u0005[חמור לרכוב\u0006 עליו\u0005]\u0006 \u0003או חמר למישתי\u0004 \u0005[יין לשתות]?\u0006 \u0003עמר למילבש\u0004 \u0005[צמר ללבוש]\u0006 \u0003או אימר לאיתכסאה\u0004 \u0005[כבש לשחוט]?\u0006 והרי זו דוגמה לחוסר הדיוק בלשונם של בני גליל.","ועוד דוגמה ללשון משובשת זו: \u0003ההיא איתתא דבעיא למימר\u0004 \u0005[אשה אחת שרצתה לומר]\u0006 \u0003לחברתה \"\u0004שלוכתי (שכנתי), \u0003תאי דאוכליך חלבא\"\u0004 \u0005[בואי ואאכילך חלב]\u0006 \u0003אמרה לה: \"שלוכתי\u0004 \u0005[שכנתי],\u0006 \u0003תוכליך לביא\"\u0004 \u0005[תאכלך הלביאה].\u0006 והכל משום חוסר הדיוק בלשון.","ועוד דוגמה לבערותם וגסותם של בני הגליל: \u0003ההיא אתתא דאתיא לקמיה דדיינא\u0004 \u0005[אשה אחת שבאה לפני הדיין]\u0006 ורצתה לומר לו: \"מרי קירי, טבלא הוית לי וגנבוה מיני\", כלומר: אדוני אדוני, טבלה היתה לי וגנבוה ממני. ובמקום זה \u0003אמרה ליה: מרי כירי, תפלא הוית לי וגנבוך מין\u0004 \u0005[אדוני עבדי, קורה היתה לי וגנבוך ממני],\u0006 \u0003וכדו הוות, דכד שדרו לך עילויה — לא מטי כרעיך אארעא\u0004 \u0005[וכך היתה\u0006 גדולה, \u0005שאם היו תולים אותך עליה, לא היו רגליך מגיעות לארץ].\u0006","ולעומת לשון גסה ונבערת זו מביאים דוגמאות ללשונם המחוכמת של בני יהודה ותלמידי חכמים: \u0003אמהתא דבי\u0004 \u0005[אמתו של בית]\u0006 \u0003רבי כי הוה משתעיא\u0004 \u0005[כשהיתה מדברת]\u0006 \u0003בלשון חכמה,\u0004 כלומר בלשון מליצה וחידה, \u0003אמרה הכי\u0004 \u0005[היתה אומרת כך]:\u0006 \u0003עלת נקפת\u0004 \u0005[הספל\u0006 שממנו דולים יין מן הכד כבר \u0005מקיש]\u0006 \u0003בכד,\u0004 שהתמעט היין עד שהספל אינו צף עוד על גביו. \u0003ידאון נישריא לקיניהון\u0004 \u0005[יעופו הנשרים לקניהם]\u0006 כלומר, יחזרו התלמידים לביתם, שהרי אין במה להשקותם.","\u0003וכד הוה בעי דליתבון, הוה אמרה להו\u0004 \u0005[וכאשר היה רוצה\u0006 רבי \u0005שישבו, היתה אומרת להם]:\u0006 \u0003יעדי\u0004 \u0005[נסיר]\u0006 מגופתה של חבית זו \u0003בתר\u0004 \u0005[אחרי]\u0006 \u0003חברתה\u0004 האחרת \u0003מינה\u0004 \u0005[ממנה],\u0006 \u0003ותתקפי עלת\u0004 \u0005[ותהא\u0006 צפה \u0005העלת]\u0006 \u0003בכד, כאילפא דאזלא בימא\u0004 \u0005[כספינה ההולכת בים].\u0006","ועוד מסופר: \u0003ר' יוסי בר אסיין, כי הוה משתעי\u0004 \u0005[כאשר היה מדבר]\u0006 \u0003בלשון חכמה אמר: עשו לי שור במשפט בטור מסכן,\u0004 שתרגם את ההברות הארמיות לעברית ולהיפך \"שור\" הוא \"תור\", \"משפט\" הוא \"דין\" וביחד — \"תרדין\", \"טור\" הוא \"הר\" או שהיה זה דומה במבטאם ל\"חר\", \"מסכן\" הוא \"דל\", וביחד חרדל. אם כן ביקש תרדין בחרדל.","\u0003וכד הוה שאיל באושפיזא, אמר הכי\u0004 \u0005[וכשהיה שואל בפונדק, היה אומר כך]:\u0006 \u0003גבר פום דין חי, מה זו טובה יש?\u0004 ו\"גבר פום דין חי\" הוא תרגום דומה של הברות: \"גבר\" משמעו \"איש\", \"פום\" משמעו \"פה\", \"דין\" משמעו \"זה\", \"חי\" הוא תרגום \"נא\" — וביחד כל זה מצטרף למעין: אושפזיכנא (ר\"ח), כלומר: פונדקאי.","\u0003ר' אבהו כי הוה משתעי\u0004 \u0005[כאשר היה מדבר]\u0006 \u0003בלשון חכמה, הוה אמר הכי\u0004 \u0005[היה אומר כך]\u0006 \u0003אתריגו לפחמין, ארקיעו לזהבין\u0004 \u0005[עשו את הפחמים בצבע האתרוג, רקעו את הזהבים]\u0006 כלומר שיטחו את הגחלים שכשהן בוערות הן אדומות כזהב \u0003ועשו לי שני מגידי בעלטה\u0004 הם תרנגולים המודיעים בעלטה (בלילה) מהי השעה. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בנוסח שונה במקצת: \u0003ויעשו לי בהן\u0004 בגחלים כלומר, יצלו על גביהן \u0003שני מגידי בעלטה\u0004 תרנגולים.","ובלשון חכמה דומה \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לר' אבהו: הצפיננו\u0004 (הראה לנו) \u0003היכן ר' אלעאי צפון\u0004 (מסתתר) שאיננו יודעים היכן הוא. \u0003אמר להן: עלץ בנערה אהרונית אחרונית עירנית והנעירתו\u0004 ולשון זו משתמעת לשני פנים:","\u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהכוונה היא ל\u0003אשה,\u0004 שנשא לאשה נערה ממשפחת כהנים (אהרונית) והיא אשתו השניה (אחרונית) בת כפר (עירנית) והיא העירתו בלילה ולכן ישן הוא ביום.","\u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 הכוונה היתה ל\u0003מסכתא.\u0004 \"נערה\" — הוא כינוי למסכת. \"אהרונית\" — מסכת העוסקת בסדר קדשים שהוא סדר עבודת הכהנים. \"אחרונית\" — שהיא אחרונה ללימודיו הקודמים. \"עירנית\" — שיש בה חריפות, ובלימודה היה נעור כל הלילה וכעת ישן.","מספרים, \u0003אמרי ליה לר' אלעאי: הצפיננו\u0004 (הראה לנו) \u0003היכן ר' אבהו צפון\u0004 (מסתתר). \u0003אמר להן: נתייעץ במכתיר\u0004 הוא הנשיא הממנה את החכמים \u0003והנגיב למפיבשת,\u0004 פנה דרומה לחכמי דרום המכונים על שם חכם גדול בדורו, הוא נכדו של שאול מפיבושת.","וכיון שדובר בלשון חכמה, מביאים מה ש\u0003אמר ר' יהושע בן חנניה: מימי לא נצחני אדם\u0004 בדברים \u0003חוץ מאשה תינוק ותינוקת. אשה מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 כיצד נצחתני? \u0003פעם אחת נתארחתי אצל אכסניא אחת, עשתה\u0004 (בישלה) \u0003לי\u0004 האשה \u0003פולין — ביום ראשון אכלתים ולא שיירתי מהן כלום,\u0004 אף שמדרך הנימוס הוא לשייר. \u0003שניה, ולא שיירתי מהן כלום.\u0004 ביום השלישי \u0003הקדיחתן במלח,\u0004 שמה בהם יותר מדי מלח, עד שאי אפשר היה לאכול מהם. \u0003כיון שטעמתי — משכתי ידי מהן.\u0004","\u0003אמרה לי: רבי, מפני מה אינך סועד\u0004 לבך בפולים היום כבכל יום? כיון שלא רציתי להעליבה, \u0003אמרתי לה\u0004: \u0003כבר סעדתי מבעוד יום. אמרה לי:\u0004 אם אינך רעב הלא \u0003היה לך למשוך ידיך מן הפת\u0004 ולא לאכול פת הרבה ואז היית יכול לא להימנע מאכילת הפולים!","אלא \u0003אמרה לי: רבי, שמא לא הנחת פאה\u0004 (שיירי אוכל) בקערה בימים \u0003ראשונים,\u0004 ומשום כך הנחת הפעם? \u0003ו\u0004כי \u0003לא כך אמרו חכמים: אין משיירין פאה באלפס\u0004 שאם שופכין מן האילפס שמטבילים בו לקערות הסועדים אין בשיור כל תוספת נימוס, \u0003אבל\u0004 מטעמי נימוס \u0003משיירין פאה בקערה\u0004 (תוס'). הרי שניצחה אותו אשה בדברים.","\u0003תינוקת מאי\u0004 \u0005[מה]\u0006 \u0003היא? פעם אחת הייתי מהלך בדרך, והיתה דרך עוברת בשדה והייתי מהלך בה. אמרה לי תינוקת אחת: רבי, לא שדה היא זו?\u0004 והרי אין עוברין בשדה כדי שלא להזיק לזרעים! \u0003אמרתי לה: לא, דרך כבושה היא\u0004 בשדה? והרי בשבילים שבשדה מותר ללכת. \u0003אמרה לי: ליסטים\u0004 (שודדים) \u0003כמותך כבשוה\u0004 כלומר אסור היה כלל ללכת בשדה זה, ורק אנשים שלא שמו לב לאיסור, כמותך, הלכו דרך השדה עד שכבשו בה שביל. והרי כאן נצחון התינוקת.","\u0003תינוק מאי\u0004 \u0005[מה]\u0006 \u0003היא? פעם אחת הייתי מהלך בדרך, וראיתי תינוק יושב על פרשת דרכים. ואמרתי לו: באיזה דרך נלך לעיר? אמר לי:\u0004 דרך \u0003זו קצרה וארוכה, ו\u0004דרך \u0003זו ארוכה וקצרה. והלכתי בקצרה וארוכה, כיון שהגעתי לעיר מצאתי שמקיפין אותה גנות ופרדיסין\u0004 ולא ידעתי את השבילים העוברים דרכם העירה.","\u0003חזרתי לאחורי. אמרתי לו: בני, הלא אמרת לי\u0004 שדרך זו \u0003קצרה? אמר לי: ו\u0004כי \u0003לא אמרתי לך\u0004 שהיא אף \u0003ארוכה? נשקתיו על ראשו, ואמרתי לו: אשריכם ישראל שכולכם חכמים גדולים אתם, מגדולכם ועד קטנכם\u0004.","ומשום שמדובר בלשון חכמה, ובחכמתן של נשי ישראל, מביאים את המעשה: \u0003ר' יוסי הגלילי הוה קא אזיל באורחא,\u0004 \u0005[היה מהלך בדרך]\u0006 \u0003אשכחה\u0004 \u0005[מצא]\u0006 את \u0003ברוריה אמר לה: באיזו דרך נלך ללוד? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003גלילי שוטה,\u0004 וכי \u0003לא כך אמרו חכמים: אל תרבה שיחה עם האשה?! היה לך לומר\u0004 בקיצור, כדי לא להרבות שיחה: \u0003\"באיזה ללוד\".\u0004","ועוד מדברי חכמתה של ברוריה: \u0003ברוריה אשכחתיה לההוא תלמידא דהוה קא גריס\u0004 \u0005[מצאה תלמיד אחד שהיה לומד]\u0006 \u0003בלחישה,\u0004 ולא הרים קולו בלימודו."],["\u0003בטשה ביה,\u0004 \u0005[בעטה בו]\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא כך כתוב \"ערוכה בכל ושמרה\"\u0004 (שמואל ב' כג, ה), משמע \u0003אם ערוכה\u0004 התורה \u0003במאתים ארבעים ושמונה איברים שלך\u0004 — כלומר שאתה מתאמץ בה גם בגופך \u0003משתמרת, ואם לאו — אינה משתמרת.\u0004 ומעין זה \u0003תנא\u0004 \u0005[שנה]:\u0006 \u0003תלמיד אחד היה לר' אליעזר שהיה שונה בלחש, לאחר שלש שנים שכח תלמודו.\u0004","ואגב מעשה זה בתלמיד ר' אליעזר מסופר גם: \u0003תנא\u0004 \u0005[שנה],\u0006 \u0003תלמיד אחד היה לר' אליעזר שנתחייב\u0004 בעונש \u0003שריפה למקום\u0004 (שכינה) בגלל חטאיו אך \u0003אמרו: הניחו לו\u0004 ולא תענישוהו כדינו משום ש\u0003אדם גדול שמש.\u0004","ומעין אותה הוראה של ברוריה \u0003אמר שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השינים],\u0006 \u0003פתח פומיך קרי\u0004 \u0005[פיך וקרא],\u0006 \u0003פתח פומיך תני, כי היכי דתתקיים ביך ותוריך חיי\u0004 \u0005[פיך ושנה כדי שתתקיים\u0006 התורה \u0005בך ותאריך ימים]\u0006 \u0003שנאמר \"כי חיים הם למצאיהם ולכל בשרו מרפא\"\u0004 (משלי ד, כב) \u0003אל תקרי\u0004 \u0005תקרא]\u0006 \u0003\"למצאיהם\" אלא \"למוציאיהם בפה\"\u0004.","ועוד הוראה \u0003אמר שמואל לרב יהודה\u0004 תלמידו החביב עליו: \u0003שיננא\u0004 \u0005[גדול השינים],\u0006 \u0003חטוף ואכול חטוף ואישתי, דעלמא דאזלינן מיניה כהלולא דמי\u0004 \u0005[ושתה, שהעולם שאנו הולכים ממנו כמשתה חתונה הוא]\u0006 ששמחתו רק לפי שעה, ואם אינו נהנה עכשיו לא יוכל ליהנות לאחר מכן.","ובדומה לכך \u0003אמר\u0004 לו \u0003רב לרב המנונא\u0004: \u0003בני, אם יש לך\u0004 ממון — \u0003היטב לך\u0004 לעצמך, ואין טעם להמתין \u0003שאין בשאול תענוג, ואין למות התמהמה, ואם תאמר\u0004 אחסוך כדי ש\u0003אניח לבני — חוק בשאול מי יגיד לך\u0004 מי משניכם יקדים למות (ערוך): שהרי לענין מיתה \u0003בני אדם דומים לעשבי השדה הללו נוצצין\u0004 גדלים ומתברכים מעשיהם \u0003והללו נובלין\u0004 מתים.","כיון שנדרש פסוק \"כי חיים הם למוצאיהם\" לענין תורה מביאים דרשה נוספת בשבח התורה הקשורה בפסוק זה. \u0003אמר ר' יהושע בן לוי: המהלך בדרך ואין עמו\u0004 בן \u0003לוייה\u0004 ומפחד — \u0003יעסוק בתורה,\u0004 שכן \u0003נאמר\u0004 על דברי תורה \u0003\"כי לוית חן הם\u0004 לראשך וענקים לגרגרותיך\u0003\"\u0004 (משלי א ט)","\u0003חש בראשו — יעסוק בתורה, שנאמר \"כי לוית חן הם לראשך\". חש בגרונו — יעסוק בתורה, שנאמר \"וענקים לגרגרתיך\". חש במעיו — יעסוק בתורה, שנאמר \"רפאות תהי לשרך\u0004 ושקוי לעצמותיך\u0003\"\u0004 (משלי ג, ח). \u0003חש בעצמותיו — יעסוק בתורה, שנאמר \"ושקוי לעצמותיך\". חש בכל גופו — יעסוק בתורה, שנאמר \"ולכל בשרו מרפא\"\u0004 (משלי ד, כב).","\u0003אמר רב יהודה בר' חייא: בא וראה, שלא כמדת הקדוש ברוך הוא מדת בשר ודם. מדת בשר ודם אדם נותן סם לחבירו — לזה\u0004 לחלק זה בגוף \u0003יפה, ולזה קשה\u0004 ומזיק. \u0003אבל הקדוש ברוך הוא אינו כן, נתן תורה לישראל — סם חיים לכל גופו, שנאמר \"ולכל בשרו מרפא\"\u0004.","ולשבחם של לימוד תורה וידיעתה \u0003אמר ר' אמי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי נעים כי תשמרם בבטנך יכנו יחדו על שפתיך\"\u0004 (משלי כב, יח) \u0003אימתי דברי תורה נעים — בזמן שתשמרם בבטנך\u0004 ותדעם, \u0003ואימתי תשמרם בבטנך — בזמן שיכנו יחדו על שפתיך\u0004 ואתה הוגה בקול ודורש בהם.","ו\u0003ר' זירא אמר\u0004 אותו רעיון \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"שמחה לאיש במענה פיו ודבר בעתו מה טוב\"\u0004 (משלי טו, כג), \u0003אימתי \"שמחה לאיש\" — בזמן שמענה\u0004 של דברי תורה \u0003בפיו. לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003אימתי שמחה לאיש במענה פיו — בזמן שדבר בעתו מה טוב\u0004 כלומר, יודע מתי וכיצד לומר כל דבר.","\u0003ר' יצחק אמר\u0004 אותו רעיון \u0003מהכא\u0004 \u0005[מכאן]\u0006 שנאמר: \u0003\"כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו\"\u0004 (דברים ל, יד) \u0003אימתי \"קרוב אליך\" — בזמן ש\"בפיך ובלבבך לעשותו\"\u0004 שאתה עוסק בהם בפיך.","\u0003רבא אמר\u0004 אותו ענין \u0003מהכא\u0004 \u0005[מכאן,\u0006 מפסוק אחר\u0005]\u0006 שנאמר: \u0003\"תאות לבו נתתה לו וארשת שפתיו בל מנעת סלה\"\u0004 (תהילים כא, ג), \u0003אימתי תאות לבו נתתה לו — בזמן שארשת שפתיו בל מנעת סלה,\u0004 והוא מדבר בדברי תורה.","\u0003רבא רמי\u0004 \u0005[הקשה,\u0006 הראה סתירה\u0005]\u0006 מאותו פסוק על עצמו: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"תאות לבו נתת לו\"\u0004 משמע שדי לו לאדם לבקש בלבו. ואילו בסופו \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וארשת שפתיו בל מנעת סלה\"\u0004 משמע שצריך לבטא תפילתו בפיו. והשיב בעצמו: אם \u0003זכה\u0004 אדם — \u0003תאות לבו נתתה לו,\u0004 ואינו צריך אף לבטא את תפילתו בפיו. ואם \u0003לא זכה\u0004 — הרי לפחות \u0003ארשת שפתיו בל מנעת סלה\u0004. ולסיומו של פסוק זה.","\u0003תנא\u0004 \u0005[שנה]\u0006 \u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית מדרשו]\u0006 של \u0003ר' אליעזר בן יעקב: כל מקום שנאמר \"נצח\u0004 או \u0003\"סלה\"\u0004 או \u0003\"ועד\" — אין לו הפסק עולמית\u0004. וראיה לדבר \u0003\"נצח\" דכתיב\u0004 \u0005[שנאמר]\u0006 בפסוק אחד: \u0003\"כי לא לעולם אריב ולא לנצח אקצוף\"\u0004 (ישעיה נז, טז) הרי שנצח משמעו כמו \"לעולם\".","\u0003סלה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כאשר שמענו כן ראינו בעיר ה' צבאות בעיר אלהינו אלהים יכוננה עד עולם סלה\"\u0004 (תהילים מח, ט) הרי שסלה פירושו \"עד עולם\". \u0003\"ועד\"\u0004 — שנאמר: \u0003\"ה' ימלך לעלם ועד\"\u0004 (שמות טו, יח).","בעקבות הפסוקים שעסקנו בהם ובמדרשם מביאים כמה מדרשי פסוקים שאמר ר' אליעזר ו\u0003סימן\u0004 נותנים להם \u0003\"ענקים\" \"לחייו\" \"לוחות\" \"חרות\". אמר ר' אליעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וענקים לגרגרתיך\"\u0004 (משלי א, ט), ופירושו: \u0003אם משים אדם עצמו כענק זה שרף\u0004 (רופף) \u0003על הצואר\u0004 כן גם התלמיד חכם אינו דוחק או מפריע לאחרים, אף \u0003נראה ואינו נראה\u0004 שהוא מכוסה בבגדים ובשיער כן גם התלמיד חכם שנמנע מלהיראות — \u0003תלמודו מתקיים בידו. ואם לאו,\u0004 שהיה נוהג בגסות הרוח, \u0003אין תלמודו מתקיים בידו,\u0004 ועוד","\u0003אמר ר' אליעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לחיו כערוגת הבשם\"\u0004 (שיר השירים ה יג) \u0003אם משים אדם עצמו כערוגה זו שהכל דשין\u0004 ועודרים \u0003בה, וכבושם זה שהכל מתבשמין בה\u0004 והנאתו לא רק למתבשם בו — \u0003תלמודו מתקיים, ואם לאו — אין תלמודו מתקיים.\u0004","\u0003ואמר ר' אליעזר\u0004: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לחת אבן\"\u0004 (שמות לא, יח), \u0003אם אדם משים עצמו את לחייו כאבן זו, שאינה נמחית — תלמודו מתקיים בידו, ואם\u0004 אינו כך, ואינו מתמיד עד כדי כך — \u0003אין תלמודו מתקיים בידו.\u0004","\u0003ואמר ר' אליעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"\u0004והלוחות מעשה אלוהים המה והמכתב מכתב אלוהים הוא \u0003חרות על הלחת\"\u0004 (שמות לב, טז). משמעו: \u0003אלמלי לא נשתברו לוחות הראשונים\u0004 שדבר זה נאמר בהם — \u0003לא נשתכחה תורה מישראל,\u0004 והיו דברי התורה חרוטים וחקוקים בלבבות.","\u0003רב אחא בר יעקב אמר:\u0004 אלמלא לא נשתברו אותם לוחות \u0003אין כל אומה ולשון שולטת בהן, שנאמר \"חרות\", אל תיקרי \"חרות\" אלא חירות.\u0004","ובאותו ענין \u0003אמר רב מתנה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"\u0004באר חפרוה שרים כרוה נדיבי עם במחוקק במשענתם \u0003וממדבר מתנה\"\u0004 (במדבר כא, יח), \u0003— אם משים אדם עצמו כמדבר זה\u0004 שהוא הפקר לכל — \u0003שהכל דשין\u0004 ודורכים \u0003בו — תלמודו מתקיים בידו\u0004 וניתן לו כמתנה. \u0003ואם לאו אין תלמודו מתקיים בידו\u0004.","מסופר: \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר חמא\u0004 הוא רבא סתם \u0003הוה ליה מלתא\u0004 \u0005[היה לו דבר\u0006 תרעומת\u0005]\u0006 \u0003לרב יוסף בהדיה\u0004 \u0005[עליו]\u0006 ומשום כך לא היו נפגשים, \u0003כי מטא מעלי יומא דכיפורי\u0004 \u0005[כאשר הגיע ערב יום הכפורים]\u0006 \u0003אמר\u0004 רבא: \u0003איזיל ואפייסיה\u0004 \u0005[אלך ואפייסהו]\u0006 \u0003אזל, אשכחיה לשמעיה דקא מזיג ליה כסא\u0004 \u0005[הלך מצא את שמשו\u0006 של רב יוסף \u0005שהוא מוזג לו כוס\u0006 יין\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו\u0006 לשמש\u0005]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי ואימזגיה אנא. יהב ליה, מזגיה\u0004 \u0005[ואמזגהו אני. נתן לו ומזגו]\u0006 ורב יוסף עיוור היה ולא ראה את האורח, \u0003כדטעמיה\u0004 \u0005[כאשר טעם]\u0006 מן היין \u0003אמר: דמי האי מזיגא למזיגא\u0004 \u0005[דומה מזיגה זו למזיגה]\u0006 של \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר חמא.\u0004 שהיה מוסיף מים יתרים ליין. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003הוא\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא תתיב אכרעיך עד דמפרשת לי הני קראי\u0004 \u0005[לא תשב על רגליך עד שתפרש לי פסוקים אלה]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וממדבר מתנה וממתנה נחליאל ומנחליאל במות ומבמות הגיא\u0004 אשר בשדה מואב ראש הפסגה ונשקפה על פני הישימון\u0003\"\u0004 (במדבר כא, יט-כ)?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם אדם משים עצמו כמדבר זה שהכל דשין בו — תורה ניתנת לו במתנה. וכיון שניתנה לו במתנה — נחלו\u0004 ועשה אותו ה\u0003אל\u0004 חלקו, \u0003שנאמר \"וממתנה נחליאל\". וכיון שנחלו אל — עולה, שנאמר \"ומנחליאל במות\"\u0004 שהן בגובה.","\u0003ואם מגיס לבו\u0004 (מתגאה) — \u0003הקדוש ברוך הוא משפילו, שנאמר \"ומבמות הגיא\". ואם חוזר בו\u0004 ומתחרט — \u0003הקדוש ברוך הוא מגביהו, שנאמר \"כל גיא ינשא\"\u0004 (ישעיה מ, ד)","\u0003אמר רב הונא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"חיתך ישבו בה תכין בטובתך לעני אלהים\"\u0004 (תהילים סח, יא) — \u0003אם אדם משים עצמו כחיה זו שדורסת ואוכלת,\u0004 מיד ואינה מקפידה על אכילתה וכן הוא, אם מחזר אחר תלמודו מיד לאחר ששמעו מפי רבו, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003שמסרחת ואוכלת\u0004 ואינה מקפידה על טיב מאכלה וכן היא, אם אינו מקפיד ומבזה את עצמו על תלמודו — \u0003תלמודו מתקיים בידו, ואם לאו — אין תלמודו מתקיים בידו. ואם עושה כן — הקדוש ברוך הוא עושה לו סעודה בעצמו, שנאמר \"תכין בטובתך לעני אלהים\",\u0004 הקדוש ברוך הוא מכין לו בטובו סעודה לאותו עני.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"נצר תאנה יאכל פריה\"\u0004 (משלי כז, יח) \u0003למה נמשלו דברי תורה כתאנה — מה תאנה זו\u0004"],["\u0003כל זמן שאדם ממשמש\u0004 ומחפש \u0003בה\u0004 פרי תאנה לאכול \u0003— מוצא בה תאנים,\u0004 לפי שאין התאנים מבשילות בבת אחת, ובכל עת שמחפשים, מוצאים תאנה שנתבשלה זה עתה. \u0003אף דברי תורה, כל זמן שאדם הוגה בהן — מוצא בהן טעם\u0004 חדש.","\u0003אמר ר' שמואל בר נחמני: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אילת אהבים ויעלת חן\u0004 דדיה ירווך בכל עת באהבתה תשגה תמיד\u0003\"\u0004 (משלי ה, יט), \u0003למה נמשלו דברי תורה לאילת? לומר לך: מה אילה רחמה צר, וחביבה על בועלה כל שעה ושעה כשעה ראשונה — אף דברי תורה חביבין על לומדיהן כל שעה ושעה כשעה ראשונה.\u0004","\u0003\"ויעלת חן\"\u0004 — נדרש: \u0003שמעלת חן על לומדיה. \"דדיה ירוך בכל עת\" — למה נמשלו דברי תורה כדד? מה דד זה כל זמן שהתינוק ממשמש בו, מוצא בו חלב. אף דברי תורה, כל זמן שאדם הוגה\u0004 ומוסיף להגות \u0003בהן — מוצא בהן טעם.\u0004","\u0003\"באהבתה תשגה תמיד\"\u0004 — שבשל אהבת התורה נעשה שוגה בעניני העולם, \u0003כגון ר' אליעזר בן פדת,\u0004 ש\u0003אמרו עליו על ר' אליעזר שהיה יושב ועוסק בתורה בשוק התחתון של ציפורי, וסדינו מוטל בשוק העליון של ציפורי.\u0004 שמחמת עיסוקו בתורה יצא מגדר מנהג העולם. ובענין זה מוסיפים לספר. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יצחק בן אלעזר: פעם אחת בא אדם ליטלו\u0004 שרצה לקחת סדין זה לעצמו, \u0003ומצא בו שרף\u0004 (נחש) השומר אותו.","ועוד לשבחה של התורה ולומדיה. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית\u0006 המדרש\u0005]\u0006 של \u0003רב ענן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"רכבי אתנות צחרות ישבי על מדין והלכי על דרך שיחו\"\u0004 (שופטים ה, י), \u0003\"רכבי אתנות\" — אלו תלמידי חכמים, שמהלכין מעיר לעיר וממדינה למדינה ללמוד בו תורה. \"צחרות\" — שעושין אותה\u0004 בהירה \u0003כצהרים,\u0004 כלומר מובנת. \u0003\"ישבי על מדין\" — שדנין דין אמת לאמיתו. \"והלכי\"\u0004 — \u0003אלו בעלי מקרא\u0004 שאינם חשובים כל כך. \u0003\"על דרך\" — אלו בעלי משנה. \"שיחו\" — אלו בעלי תלמוד\u0004 שחשובים הם ביותר, \u0003ש\u0004כן \u0003כל שיחתן דברי תורה.\u0004 ועוד בנושא זה.","\u0003אמר רב שיזבי משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לא יחרך רמיה צידו\"\u0004 (משלי יב, כז) — \u0003לא יחיה ולא יאריך ימים, צייד הרמאי\u0004 — מי שאינו מטפל בציפורים שניצודו על ידו כראוי, אינו יכול להחזיק בהם לאחר מכן. אף כאן מי שלומד הרבה ואינו חוזר, איננו יכול להשיג דבר. ונדרש \"יחרוך\" כצירוף של יחיה— ארוך.","\u0003רב ששת אמר:\u0004 וכי \u0003צייד הרמאי יחרוך?\u0004 והרי ההולך בדרך זו אינו אלא שוטה, ואין בזה דבר מן הערמומיות!","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר: משל לצייד שצד צפרים, אם ראשון ראשון\u0004 שצד \u0003משבר כנפיו\u0004 שלא יעוף — \u0003משתמר\u0004 בידו מה שצד, \u0003ואם לאו — אין משתמר.\u0004","ובדומה \u0003אמר רבה אמר רב סחורה אמר רב הונא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"הון מהבל ימעט וקבץ על יד ירבה\"\u0004 (משלי יג, יא) \u0003אם עושה אדם\u0004 את \u0003תורתו\u0004 (הון) \u0003חבילות חבילות\u0004 (שכאן המלה 'הבל' נדרשת בחילוף אותיות ה'-ח', חבל) — \u0003מתמעט\u0004 בתורתו, \u0003ואם לאו\u0004 שלומד מעט מעט וחוזר — \u0003קובץ על יד ירבה.\u0004","\u0003אמר רבה: ידעי רבנן להא מילתא, ועברי עלה\u0004 \u0005[יודעים חכמים דבר זה, ועוברים עליו]\u0006 שאינם נוהגים כן. \u0003אמר רב נחמן בר יצחק: אנא עבדתה\u0004 \u0005[אני עשיתיה\u0006 כזאת\u0005]\u0006 ושניתי כראוי כקובץ על יד, \u0003ו\u0004אכן \u0003איקיים בידאי\u0004 \u0005[התקיים\u0006 תלמודי \u0005בידי].\u0006","וכיון שדברנו בדרך הלימוד מביאים עוד. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003כיצד סדר משנה\u0004 כלומר, כיצד נלמדה התורה שבעל פה מתחילה: \u0003משה למד מפי הגבורה\u0004 (ה'). \u0003נכנס אהרן\u0004 וישב לפניו, \u0003ושנה לו משה פירקו\u0004 שלמד מפי הגבורה, \u0003נסתלק אהרן\u0004 מלימוד זה \u0003וישב לשמאל משה. נכנסו בניו\u0004 של אהרן, \u0003ושנה להן משה פירקן,\u0004 והיה אהרן מקשיב. \u0003נסתלקו בניו\u0004 של אהרן, \u0003אלעזר ישב לימין משה, ואיתמר לשמאל אהרן. ר' יהודה אומר: לעולם אהרן לימין משה חוזר\u0004 ושם מקום מושבו. שנחלקו בדבר האופן הראוי לסדר מקומות הישיבה ליד הרב. \u0003נכנסו זקנים\u0004 שבישראל \u0003ושנה להן משה פירקן. נסתלקו זקנים\u0004 לצד, \u0003נכנסו כל העם ושנה להן משה פירקן. נמצאו ביד אהרן ארבעה פעמים\u0004 ששמע את הפרק, \u0003ביד בניו שלשה, וביד הזקנים שנים, וביד כל העם אחד.\u0004","\u0003נסתלק משה\u0004 והלך לאהלו \u0003ושנה להן אהרן פירקו\u0004 שלמד מפי משה. \u0003נסתלק אהרן שנו להן בניו פירקן. נסתלקו בניו, שנו להן זקנים פירקן. נמצא ביד הכל ארבעה\u0004 שכל העם למדו ארבע פעמים את הפרק שנלמד מפי הגבורה.","\u0003מכאן אמר ר' אליעזר חייב אדם לשנות לתלמידו ארבעה פעמים. וקל וחומר, ומה אהרן שלמד מפי משה\u0004 עצמו, \u0003ומשה\u0004 הרי קיבל את הדבר במישרין \u0003מפי הגבורה — כך\u0004 היה צריך לחזור על תלמודו, \u0003הדיוט\u0004 הלומד \u0003מפי הדיוט — על אחת כמה וכמה\u0004 שצריך לחזור ארבע פעמים על פרקו.","\u0003ר' עקיבא אומר: מניין שחייב אדם לשנות לתלמידו\u0004 את דברי התורה \u0003עד שילמדנו\u0004 התלמיד ויקלוט את הדברים — \u0003שנאמר\u0004 \"ועתה כתבו לכם את השירה הזאת \u0003ולמדה את בני ישראל\u0004 שימה בפיהם למען תהיה לי השירה הזאת לעד בבני ישראל\" (דברים לא, יט) ומשמעו שצריך ללמד אותה להם, \u0003ומניין\u0004 שצריך ללמדם \u0003עד שתהא סדורה בפיהם — שנאמר \"שימה בפיהם\"\u0004 שאף הם יוכלו להיות מסוגלים ללמדה לאחרים,","\u0003ומניין שחייב\u0004 הרב \u0003להראות\u0004 לתלמידו \u0003פנים\u0004 כלומר: להסביר את טעמי הדברים — \u0003שנאמר: \"ואלה המשפטים אשר תשים לפניהם\"\u0004 (שמות כא, א) משמעו שצריך לשים את הנלמד שיהיה ערוך ומסודר בטעמיו לפני הלומדים.","על סדר הלימוד של משה שואלים: \u0003וליגמרו כולהו\u0004 \u0005[ושילמדו כולם]\u0006 \u0003ממשה\u0004 עצמו ארבע פעמים! ומשיבים: שנעשה הדבר רק \u0003כדי לחלוק כבוד לאהרן ובניו, וכבוד לזקנים.\u0004","ושואלים: והרי יש דרך שלא להטריח את משה כל כך, \u0003וניעול\u0004 \u0005[ושיכנס]\u0006 \u0003אהרן וניגמר\u0004 \u0005[וילמד]\u0006 \u0003ממשה, וליעיילו\u0004 \u0005[ושיכנסו]\u0006 \u0003בניו וליגמרו\u0004 \u0005[וילמדו]\u0006 \u0003מאהרן, וליעיילו\u0004 \u0005[ושיכנסו]\u0006 \u0003זקנים ולילפו\u0004 \u0005[וילמדו]\u0006 \u0003מבניו\u0004 של אהרן, \u0003וליזלו וליגמרינהו לכולהו\u0004 \u0005[וילכו וילמדו את כל]\u0006 \u0003ישראל!\u0004 ומשיבים: \u0003כיון\u0004 ש\u0003משה מפי הגבורה גמר\u0004 \u0005[למד],\u0006 \u0003מסתייעא מלתיה\u0004 \u0005[מצליח הדבר]\u0006 ורצוי שישמעו כל ישראל ממשה עצמו פעם אחת.","בדברים ששנינו \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003ר' יהודה אומר: לעולם אהרן לימין משה חוזר\u0004 כלומר שאהרן לעולם יושב לימינו של משה ואין הבדל במספר האנשים הנמצאים שם. ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנינו\u0006 בדיני נימוסין\u0005]:\u0006 \u0003שלשה שהיו מהלכין בדרך\u0004 ראוי הוא שיהא \u0003הרב באמצע, וגדול\u0004 שבין השניים הנותרים \u0003בימינו, וקטן בשמאלו. לימא\u0004 \u0005[האם לומר]\u0006 כשיטת \u0003ר' יהודה היא ולא\u0004 כשיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 שלפי שיטתם צריך הגדול להיות בשמאלו של הרב, כדי שיהיה צד ימינו פונה אל הרב.","ומשיבים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שברייתא זו \u0005כ\u0006שיטת \u0005חכמים\u0006 היא\u0005]\u0006 ומה שאמרו בענין שאהרן יושב לימין אפילו לאחר שנכנסו האחרים, שם היה טעם הדבר \u0003משום טירחא דאהרן\u0004 \u0005[טירחתו של אהרן]\u0006 כדי שלא יצטרך להתאמץ בקימה ובישיבה.","כיון שדובר בחשיבותה של חזרה על דברי תורה מסופר: \u0003ר' פרידא הוה ליה ההוא תלמידא דהוה תני ליה ארבע מאה זימני וגמר\u0004 \u0005[היה לו תלמיד אחד שהיה שונה לו ארבע מאות פעמים ו\u0006רק אז היה \u0005לומד],\u0006 שבפחות מכך לא היה מסוגל לקלוט תלמודו. \u0003יומא חד בעיוה למלתא דמצוה\u0004 \u0005[יום אחד בקשו אותו,\u0006 את ר' פרידא\u0005, לדבר מצוה]\u0006 שהיה יכול לעסוק בה לאחר זמן. \u0003תנא ליה\u0004 \u0005[שנה לו]\u0006 ר' פרידא ארבע מאות פעם \u0003ולא גמר\u0004 \u0005[למד]\u0006 התלמיד.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האידנא מאי שנא\u0004 \u0005[הפעם מה שונה]\u0006 שאינך יכול לקלוט? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדההיא שעתא דאמרו ליה למר איכא מילתא דמצוה — אסחאי לדעתאי\u0004 \u0005[מאותה שעה שאמרו לו לאדוני\u0006 ש\u0005יש דבר מצוה —\u0006 \u0005הסחתי את דעתי\u0006 מן הלימוד\u0005],\u0006 \u0003וכל שעתא אמינא: השתא קאי מר, השתא קאי מר\u0004 \u0005[וכל שעה אמרתי: עכשיו עומד אדוני, עכשיו עומד אדוני\u0006 לעסוק במצוה\u0005]\u0006 ולא יוכל ללמדני כראוי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב דעתיך ואתני לך\u0004 \u0005[תן דעתך\u0006 הפעם \u0005ואשנה לך]\u0006 ותדע שלא אקום עד שלא אגמור להשנות לך כראוי. \u0003הדר תנא ליה ארבע מאה זימני אחריני\u0004 \u0005[חזר\u0006 ו\u0005שנה לו ארבע מאות פעמים נוספות].\u0006","ובזכות זו, מחמת גודל מסירותו לתלמידיו, \u0003נפקא בת קלא ואמרה ליה: ניחא ליך דליספו לך ארבע מאה שני, או דתיזכו את ודרך לעלמא דאתי\u0004 \u0005[יצאה בת קול ואמרה לו:\u0006 האם \u0005נוח לך שיוסיפו לך\u0006 לשנותיך \u0005ארבע מאות שנים, או שתיזכו אתה ו\u0006בני \u0005דורך לעולם הבא]?\u0006 \u0003אמר: דניזכו אנא ודריי לעלמא דאתי\u0004 \u0005[שנזכה אני ודורי לעולם הבא].\u0006 \u0003אמר להן הקדוש ברוך הוא\u0004 למלאכים: \u0003תנו לו זו וזו;\u0004 שגם יאריך ימים מאד וגם יזכו הוא ובני דורו לחיי עולם הבא.","ועוד מדרכי לימוד התורה \u0003אמר רב חסדא: אין תורה נקנית אלא בסימנין\u0004 שעושין בה כדי להקל על הזכרון. \u0003שנאמר \"שימה בפיהם\", אל תקרי\u0004 \u0005[אל תקרא]\u0006 \u0003'שימה' אלא 'סימנה'\u0004 שכאשר עושים בה סימן הרי היא נשמרת בזכרון.","\u0003שמעה\u0004 לאימרה זו \u0003רב תחליפא ממערבא\u0004 \u0005[מארץ ישראל],\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003אמרה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו, אמר: אתון מהתם מתניתו לה, אנן מהכא מתנינן לה\u0004 \u0005[משם לומדים אותו\u0006 רעיון\u0005, אנחנו מכאן לומדים אותו]\u0006 שנאמר: \u0003\"הציבי לך צינים שימי לך\u0004 וגו'\u0003\"\u0004 (ירמיהו לא, כ) שמשמעו: \u0003עשו ציונים לתורה\u0004 — הם סימנים לזכרון. \u0003ומאי משמע דהאי ציון לישנא דסימנא הוא\u0004 \u0005[ומה\u0006 המקור לכך ש\u0005המשמעות שציון זה לשון סימן הוא]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בכתוב אחר: \u0003\"וראה עצם אדם ובנה אצלו ציון\"\u0004 (יחזקאל לט, טו) משמע: סימן שיש טומאה במקום.","\u0003ר' אליעזר אמר:\u0004 את אותו רעיון למדנו \u0003מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]:\u0006 \u0003\"אמר לחכמה אחתי את ומדע לבינה תקרא\"\u0004 (משלי ז, ד) כלומר: \u0003עשה מודעים\u0004 (סימנים המודיעים) \u0003לתורה. רבא אמר\u0004 על פסוק זה: \u0003עשה מועדים לתורה\u0004 שיש לקבוע זמן קבוע (\"מודע\" = מועד) ללימוד תורה."],["\u0003והיינו\u0004 \u0005[וזהו]\u0006 שאמרנו שצריך הלומד לעשות כל מאמץ כדי לקיים תורתו הוא כפי ש\u0003אמר אבדימי בר חמא בר דוסא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לא בשמים היא ולא מעבר לים היא\"\u0004 (דברים ל, יב-יג) \u0003\"לא בשמים היא\"\u0004 הכוונה: ש\u0003אם בשמים היא — אתה צריך לעלות אחריה, ואם מעבר לים היא — אתה צריך לעבור אחריה,\u0004 שיש לעשות כל מאמץ להגיע ללימוד התורה.","\u0003רבא אמר\u0004 דרשה אחרת על הכתוב: \u0003\"לא בשמים היא\" — לא תמצא\u0004 תורה \u0003במי שמגביה דעתו עליה כשמים, ולא תמצא במי שמרחיב דעתו עליה כים.\u0004","\u0003ר' יוחנן אמר: לא בשמים היא — לא תמצא\u0004 תורה \u0003בגסי רוח\u0004 המגביהים עצמם כאילו הם בשמים, \u0003\"ולא מעבר לים היא\" — לא תמצא לא בסחרנים ולא בתגרים\u0004 ההולכים מעבר לים, ואין להם פנאי לעסוק בתורה כראוי.","לאחר העיסוק בדברי אגדה שונים חוזרים לענין עיבור ערים שבמשנתנו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003כיצד מעברין\u0004 (מודדים) \u0003את\u0004 תחום \u0003הערים?\u0004 אם היתה העיר \u0003ארוכה\u0004 (מלבנית) — מודדין את תחומיה ממנה והלאה \u0003כמות שהיא.\u0004 אם היתה העיר \u0003עגולה — עושין לה זויות,\u0004 וכאילו שכל העיר תקבל צורת מרובע, ומשם חוזרים ומודדים את תחומה. אם היתה \u0003מרובעת — אין עושין לה זויות\u0004 אחרות. \u0003היתה\u0004 העיר \u0003רחבה מצד אחד וקצרה\u0004 (צרה) \u0003מצד אחר — רואין אותה כאילו היא שוה.\u0004 כלומר, מוסיפים על הצד הצר כדי ליצור מרובע.","\u0003היה בית אחד יוצא\u0004 מתחום העיר \u0003כמין פגום, או שני בתים יוצאין כמין שני פגומין — רואין אותן כאילו חוט מתוח עליהן\u0004 לכל אורך העיר, \u0003ומודד ממנו ולהלן אלפים אמה. היתה\u0004 העיר \u0003עשויה כמין קשת או כמין גאם\u0004 (כמו האות היוונית גמא) — \u0003רואין אותה כאילו היא מלאה בתים וחצירות\u0004 בתוך כל חלל הקשת, \u0003ומודד ממנו ולהלן אלפים אמה,\u0004","ומעתה באים לבאר את הדברים. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ארוכה — כמות שהיא.\u0004 ותוהים: \u0003פשיטא!\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לא צריכא, דאריכא וקטינא\u0004 \u0005[לא נצרך\u0006 אלא כ\u0005ש\u0006היא \u0005ארוכה וצרה],\u0006 \u0003מהו דתימא: ליתן לה פותיא אאורכה\u0004 \u0005[מהו שתאמר שניתן לה רוחבה על אורכה]\u0006 \u0005כלומר\u0006 שיעשה את העיר כאילו היא מרובעת ממש, שיהא אורכה כרוחבה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין צריך לעשות כן.","נאמר שבעיר \u0003מרובעת אין עושין לה זויות.\u0004 ושוב שואלים: \u0003פשיטא\u0004 \u0005[פשוט]!\u0006 וכי מדוע יוסיפו לה זויות? ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 אלא במקרה \u0003דמרבעא\u0004 \u0005[ש\u0006העיר \u0005מרובעת]\u0006 \u0003ו\u0004אולם \u0003לא מרבעא\u0004 \u0005[מרובעת]\u0006 \u0003בריבוע\u0004 לפי רוחות ה\u0003עולם. מהו דתימא: לירבעא\u0004 \u0005[מהו שתאמר שיעשה מרובעת]\u0006 \u0003בריבוע\u0004 לפי רוחות ה\u0003עולם.\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין עושין כן.","נאמר בתוספתא: \u0003היה בית אחד יוצא כמין פגום או שני בתים יוצאין כמין שני פגומין.\u0004 ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ב\u0003בית אחד אמרת\u0004 שמוסיפים לתחום העיר, \u0003שני בתים מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]?!\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא משתי רוחות,\u0004 כלומר הכוונה היא שלא רק אם היו שני בתים מצד אחד, אלא גם אם היה יוצא בית אחד מצד אחד ובית אחר מצד אחר שלה — מוסיפין על העיר משני הצדדים. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מרוח אחת — אמרינן\u0004 \u0005[אומרים אנו]\u0006 שאפשר להוסיף על העיר אפילו בשל בית אחד. \u0003משתי רוחות — לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם יש תוספת כל שהיא על העיר, ואפילו מכמה צדדים — קובעים את תחומה בקו ישר.","בתוספתא נאמר שאם \u0003היתה\u0004 העיר \u0003עשויה כמין קשת או כמין גאם, רואין אותה כאילו היא מלאה בתים וחצירות, ומודד ממנה ולהלן אלפים אמה. אמר רב הונא: עיר העשויה כקשת, אם יש\u0004 לה \u0003בין שני ראשיה פחות מארבעת אלפים אמה\u0004 שהם פחות משני תחומי שבת, ונמצא שהתחומים משני קצות העיר מובלעים זה בזה, — הרי היא נחשבת כאילו היתה מלאה כולה, אפילו בחלל שבין קצות הקשת. \u0003מודדין לה\u0004 את תחומה \u0003מן היתר\u0004 של הקשת הזו, \u0003ואם לאו,\u0004 שהיתה הקשת רחבה יותר — \u0003מודדין לה מן הקשת\u0004 עצמה והחלל נחשב מן המידה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הונא הכי\u0004 \u0005[כך],\u0006 שהמרחק הקובע הפרדה בין חלקיה של עיר אחת הוא ארבעת אלפים אמה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: חומת העיר שנפרצה\u0004 — משערים \u0003במאה וארבעים ואחת ושליש\u0004 אמות. ואם נפרצה העיר כולה ברוחב גדול יותר, הרי היא נחשבת כשתי ערים, משמע שלהבדיל בין עיר לעיר די בכמאה ארבעים ואחת אמות?","\u0003אמר רבה בר עולא: לא קשיא\u0004 \u0005[אינו קשה].\u0006 \u0003כאן,\u0004 שאנו נותנים שיעור גדול יותר — הרי זה כשהפירצה, המקום הריק, היה רק \u0003ברוח אחת\u0004 שהרי מן הצד השני, בקימורה של הקשת, מצוי מקום ישוב. \u0003כאן\u0004 בחומת העיר שנפרצה — שהיתה הפירצה \u0003משתי רוחות,\u0004 ואין כנגד המקום הפנוי לא כלום, והרי הוא ממש כשתי ערים נפרדות.","ושואלים: אם כן \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו]\u0006 רב הונא כאן לגבי החומה שנפרצה? ש\u0003נותנין קרפף לזו וקרפף לזו,\u0004 שמוסיפים על כל עיר כשיעור קרפף שהוא שבעים אמה ומשהו, וכך היא נמדדת. ואולם לשם מה לו לומר דבר זה? \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה רב הונא חדא זימנא\u0004 \u0005[פעם אחת]\u0006 הלכה זו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003נותנין קרפף לעיר,\u0004 כלומר מוסיפים לעיר כדי קרפף שהוא שבעים אמה ושיריים, ומשם מתחילים למדוד את התחום, אלו \u0003דברי ר' מאיר. וחכמים אומרים: לא אמרו קרפף אלא בין שתי עיירות,\u0004 שאם אין ביניהן יותר ממרחק זה, הרי הן נחשבות כעיר אחת.","\u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב הונא אמר: קרפף לזו וקרפף לזו,\u0004 וביחד הוא שיעור מאה ארבעים ואחת אמה ומשהו. \u0003וחייא בר רב אמר: אין נותנין אלא קרפף אחד לשניהם,\u0004 ואם כן הרי כבר אמר רב הונא שמוסיפים לערים שיעור שני קרפפים!","ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 בשני המקומות, \u0003דאי אשמעינן הכא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005כאן]\u0006 לגבי החומה שנפרצה, הייתי אומר — \u0003משום דהוה ליה\u0004 \u0005[שהיה לו]\u0006 \u0003צד היתר מעיקרא\u0004 \u0005[מתחילה],\u0006 שהרי היו שני חלקי העיר קודם לכן עיר אחת ממש. \u0003אבל התם\u0004 \u0005[שם]\u0006 בשתי העיירות, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 וכדי להחשיב את שתי העיירות כמחוברות צריך שיהיו מרוחקות רק כשיעור קרפף אחד בלבד.","ולהיפך, \u0003ואי אשמעינן התם\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005שם]\u0006 לגבי העיירות, הייתי אומר — \u0003משום דדחיקא תשמישתייהו\u0004 \u0005[שדחוק תשמישן],\u0006 שאין שיעור קרפף אחד בלבד מספיק לשתי הערים יחד להשתמש בו, \u0003אבל הכא דלא דחיק תשמישתייהו\u0004 \u0005[כאן שאין שימושם דחוק]\u0006 כיון שהמקום הפנוי הוא בתוך העיר עצמה ולפני שנפרצה חומתה כלל לא היה צורך בשטח זה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ויהא די בשיעור קרפף אחד, על כן \u0003צריכא\u0004 \u0005[נצרכה\u0006 להיאמר\u0005].\u0006","ושאלו: \u0003וכמה הוי\u0004 \u0005[הריהו]\u0006 המרחק שמותר שיהא \u0003בין\u0004 ה\u0003יתר\u0004 (הקו הדמיוני שבין ראשי הקשת) למרכז ה\u0003קשת\u0004 עצמה בעיר העשויה כקשת? \u0003רבה בר רב הונא אמר: אלפים אמה,\u0004 ואילו \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר רב הונא אמר: אפילו יתר מאלפים.\u0004","\u0003אמר אביי: כוותיה\u0004 \u0005[כדעתו]\u0006 של \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר רב הונא מסתברא\u0004 \u0005[מסתבר],\u0006 \u0003דאי בעי הדר אתי\u0004 \u0005[שאם ירצה יחזור ויבוא]\u0006 \u0003דרך בתים\u0004 של הקשת מכל חלק של העיר אל הקצה שלה, ומשם יעבור אל הקצה השני, ונמצא שאין לחלק אם היה היתר רחוק או קרוב.","נאמר שאם \u0003היו שם גדודיות גבוהות עשרה טפחים\u0004 — הרי הן נחשבות כחלק מן העיר ומהן מודדים את תחומה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003גדודיות\u0004 אלה? \u0003אמר רב יהודה:\u0004 הכוונה ל\u0003שלש מחיצות שאין עליהן תקרה.\u0004 שאינן לגמרי בבחינת בית, אבל ראויות הן להצטרף לעיר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שתי מחיצות ויש עליהן תקרה, מהו\u0004 דינן, האם נחשבות אף הן כבית או לא? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בתוספתא: \u0003אלו שמתעברין\u0004 ונחשבים עם העיר למדידת התחום: \u0003נפש,\u0004 כלומר בית שעל הקבר \u0003שיש בה ארבע אמות על ארבע אמות,\u0004 וכן \u0003הגשר\u0004 או \u0003הקבר שיש בהן בית דירה, ובית הכנסת\u0004 בתנאי \u0003שיש בה בית דירה לחזן\u0004 (או לשמש), ואינו משמש רק לתפילה בזמנים מסוימים. \u0003ו\u0004כן \u0003בית עבודה זרה שיש בה בית דירה לכומרים, ו\u0004כן \u0003אורוות\u0004 הסוסים \u0003ו\u0004כן \u0003האוצרות\u0004 (המחסנים) \u0003שבשדות ויש בהן בית דירה, והבורגנין שבתוכה\u0004 שבתוך השדה שהם מגדלי שמירה קטנים. \u0003ו\u0004כן \u0003הבית שבים\u0004 שמצוי על אי בתוך אגם או ים, הסמוך לעיר בתוך שבעים אמה — \u0003הרי אלו מתעברין עמה.\u0004","\u0003ואלו שאין מתעברין עמה: נפש שנפרצה משתי רוחותיה אילך ואילך, ו\u0004כן \u0003הגשר והקבר שאין להן בית דירה, ובית הכנסת שאין לה בית דירה לחזן, ובית עבודה זרה שאין לה בית דירה לכומרים, ואורוות ואוצרות שבשדות\u0004 אם \u0003אין להן בית דירה\u0004 ואינם משמשים למגורי אדם, \u0003ו\u0004כן \u0003בור ושיח\u0004 (בור מוארך), \u0003ומערה\u0004 (בור שיש עליו גג) \u0003וגדר ושובך שבתוכה,\u0004 בתוך השדה, וכן \u0003הבית שבספינה\u0004 שאינו קבוע במרחק שבעים אמה לעיר — \u0003אין אלו מתעברין עמה.\u0004","\u0003קתני מיהת\u0004 \u0005[מכל מקום למדנו]:\u0006 \u0003נפש שנפרצה משתי רוחותיה אילך ואילך\u0004 — שוב אינה מצטרפת אל העיר. \u0003מאי לאו דאיכא\u0004 \u0005[האם לא\u0006 מדובר כאן \u0005שיש]\u0006 \u0003תקרה\u0004 על הנפש הזו, הרי ששתי המחיצות שנשארו שלימות, אף שיש עליהן תקרה, אינן מצטרפות לתחום גודלה של העיר! ומשיבים: \u0003לא!\u0004 מדובר כאן במקרה \u0003דליכא\u0004 \u0005[שאין]\u0006 עליהן \u0003תקרה.\u0004","\u0003ושואלים: בית שבים למאי חזי\u0004 \u0005[למה\u0006 הוא \u0005ראוי]\u0006 אם איננו ממש חלק מן הישוב. \u0003אמר רב פפא: בית שעשוי לפנות בו כלים שבספינה\u0004 לפי שעה.","ומתוך שהביאו תוספתא זו שואלים על דבריה: \u0003ו\u0004האם \u0003מערה אין מתעברת עמה\u0004 (עם העיר), \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: מערה מתעברת עמה! אמר אביי: כשיש בנין על פיה\u0004 של המערה — אז מצטרפת היא להיות כבית הבנוי סמוך לעיר.","ותוהים: אם אמנם יש בנין על פיה, לשם מה מוזכרת המערה, \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו \u0003משום בנין גופיה\u0004 \u0005[עצמו]\u0006 שראוי להצטרף לעיר! וקובעים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003להשלים,\u0004 שאם הבית קטן מאד, ויחד עם המערה שטחו ארבע אמות על ארבע אמות (שהוא השיעור המינימלי לבית) — הרי המערה מצטרפת.","כל מה שנאמר בקשר לעירובי תחומין מדובר בעיר בנויה ממש. \u0003אמר רב הונא: יושבי צריפין,\u0004 היושבים בבתים הקלועים קש וענפי ערבות, אינם נחשבים כיושבי עיר, ו\u0003אין מודדין להן\u0004 תחום \u0003אלא מפתח בתיהן,\u0004 ואין מצרפים כמה צריפים להיחשב כעיר ממש.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חסדא:\u0004 הלא נאמר בבני ישראל בהיותם במדבר \u0003\"ויחנו על הירדן מבית הישמת\u0004 עד אבל השיטים בערבות מואב\u0003\"\u0004 (במדבר לג, מט), \u0003ואמר רבה בר בר חנא אמר ר' יוחנן: לדידי חזי לי ההוא אתרא, והוי תלתא פרסי על תלתא פרסי\u0004 \u0005[אני עצמי ראיתי אותו מקום, והריהו שלש פרסות על שלש פרסות]\u0006 שהם שנים עשר מיל.","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשהן נפנין\u0004 לצרכיהם בהיותם במדבר — \u0003אין נפנין לא לפניהן\u0004 (לפני מהלך המחנה), \u0003ולא לצדיהן\u0004 מפני כבוד השכינה, \u0003אלא לאחריהן\u0004 (לאחורי המחנה). משמע שאף ביום השבת, כשהיו צריכים להיפנות לצרכיהם, היו הולכים לכל אורך המחנה שהוא גדול בהרבה מאלפיים אמה (שהם שני מילין בלבד). ואם כן ברור שמחנה ישראל נחשב כעיר אף שהיה מורכב מאהלים בלבד. וכיצד אמר רב הונא שיושבי צריפין אינן נחשבים כעיר?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: דגלי מדבר\u0004 (בני ישראל שהלכו ב\"דגלים\" ומחנה במדבר) \u0003קאמרת\u0004 \u0005[אמרת]?\u0006 \u0003כיון דכתיב בהו\u0004 \u0005[שנאמר בהן]\u0006 \u0003\"על פי ה' יחנו ועל פי ה' יסעו\"\u0004 (במדבר ט, כ) — \u0003כמאן דקביע דמי\u0004 \u0005[כמי שקבוע להם\u0006 מקום \u0005נחשבים],\u0006 וקביעת מקום שעל פי דיבור ה', קביעות גמורה היא.","\u0003אמר רב חיננא בר רב כהנא אמר רב אשי: אם יש שם\u0004 במחנה הצריפים \u0003שלש חצירות של שני בתים\u0004 בנויים כראוי בכל חצר — \u0003הוקבעו\u0004 להיות כמקום ישוב, שכן תחומין נמדדים מקצה העיר.","כיון שהוזכרו יושבי צריפין \u0003אמר רב יהודה אמר רב: יושבי צריפין\u0004 (רועים העוברים ממקום למקום עם צאנם ואינם שוהים במקום אחד אלא זמן קצר) \u0003והולכי מדברות\u0004 עם משפחתם — \u0003חייהן אינן חיים\u0004 שחייהם קשים ביותר, \u0003ונשיהן ובניהן אינן שלהן\u0004 כפי שיבואר להלן.","\u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]\u0006 \u0003אליעזר איש ביריא אומר: יושבי צריפין כיושבי קברים. ועל\u0004 הנושא את \u0003בנותיהן הוא אומר \"ארור שכב עם כל בהמה\"\u0004 (דברים כז, כא).","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 נאמרו דברים אלו על בנותיהם? \u0003עולא אמר:\u0004 מפני \u0003שאין להן מרחצאות\u0004 והולכים הגברים לרחוץ במקום רחוק, ויש לחוש שמא בזמן שהלכו בעליהן נאפו הנשים, ואין ילדיהן שלהם. \u0003ור' יוחנן אמר: מפני שמרגישין זה לזה בטבילה\u0004 שכמו בעליהן היו הן הולכות לטבול במקום רחוק, ומאחר שהמקום קטן והכל יודעים מתי הולכות הנשים לטבול, פעמים משתמש בידיעה זו אדם שאינו הגון ומנאף עם הנשים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 \u0003נהרא דסמיך לביתא\u0004 \u0005[נהר הסמוך לבית]\u0006 וראוי לטבילה ולא לרחיצה. ולכן לשם טבילה, אין הנשים מרחיקות ואין לחשוש להן. אבל למרחצאות, מרחיקים הבעלים ללכת.","כיון שנזכרו מקומות ישוב שונים, מזכירים מה ש\u0003אמר רב הונא\u0004 בדומה לזה: \u0003כל עיר שאין בה ירק — אין תלמיד חכם רשאי לדור בה,\u0004 מפני חשש לבריאותו. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003ירק מעליא\u0004 \u0005[מעולה]\u0006 הוא? \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלשה\u0004 דברים \u0003מרבין את הזבל וכופפין את הקומה, ונוטלים אחד מחמש מאות ממאור עיניו של אדם, ואלו הן:\u0004"],["\u0003פת קיבר\u0004 (לחם עשוי מקמח גס שלא נופה כל צורכו) \u0003ושכר חדש וירק,\u0004 ואם כן משמע שירק מזיק! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בתומי וכרתי\u0004 \u0005[בשומים וכרישים]\u0006 שמעולים הם, \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בשאר ירקי\u0004 \u0005[ירקות]\u0006 שמזיקים. \u0003כדתניא\u0004 \u0005[כמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שום — ירק\u0004 משובח, \u0003כרישין — חצי ירק, נראה צנון — נראה סם חיים\u0004 שהוא יפה לגוף.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו]:\u0006 \u0003נראה צנון — נראה סם המות!\u0004 ומתרצים \u0003לא קשיא\u0004 שאינו קשה: \u0003כאן,\u0004 שגינוהו — מדובר \u0003בעלין\u0004 של צנון. \u0003כאן,\u0004 ששיבחוהו — \u0003באמהות\u0004 (גוף הירק). או באופן זה: \u0003כאן — בימות החמה,\u0004 מועיל, \u0003כאן — בימות הגשמים,\u0004 מזיק.","ועוד \u0003אמר רב יהודה אמר רב\u0004 בענין טבע המקומות: \u0003כל עיר שיש בה מעלות ומורדות,\u0004 והרי הם מייגעים את הגוף, \u0003אדם ובהמה שבה מתים בחצי ימיהן.\u0004 ותוהים: \u0003מתים סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הרי רואים אנו שאנשים חיים שם כרגיל! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מזקינים בחצי ימיהן\u0004 מחמת טרחת המעלות והמורדות. וכן \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הני מולייתא דבי בירי ודבי נרש אזקנון\u0004 \u0005[אותן העליות\u0006 והמורדות \u0005של בית בירי ושל בית נרש\u0006 שאני גר בהם, הם \u0005הזקינונו].\u0006","לענין עיבור העיר \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003בא לרבעה\u0004 לעשות את תחומי העיר עצמה כתבנית ריבוע — \u0003מרבעה בריבוע עולם\u0004 שצלעותיו של ריבוע זה תהיינה זהות עם רוחות העולם, \u0003נותן צפונה\u0004 של העיר \u0003לצפון עולם ודרומה לדרום עולם, וסימניך\u0004 כדי לדעת איפה צפון ואיפה דרום: מזל \u0003עגלה בצפון, ו\u0004מזל \u0003עקרב בדרום.\u0004 ולפי כיוון מזלות אלה קובעים את כיווני העיר.","\u0003ר' יוסי אומר: אם אינו יודע לרבעה בריבוע של עולם,\u0004 שאינו יודע לכוון לפי המזלות — \u0003מרבעה כמין התקופה.\u0004 כלומר, על פי חשבון מהלך השמש, אף שאינו מדוייק כל כך. \u0003כיצד?\u0004 כאשר \u0003חמה יוצאה ביום ארוך ושוקעת ביום ארוך\u0004 — מהלך חמה \u0003זה הוא פני צפון,\u0004 כלומר החמה זורחת מכיוון צפון— מזרח. ולהיפך, \u0003חמה יוצאה ביום קצר ושוקעת ביום קצר — זה הוא פני דרום.\u0004 ואילו ב\u0003תקופת ניסן ותקופת תשרי\u0004 שבהן שווים היום והלילה — \u0003חמה יוצאה ב\u0004כוון \u0003חצי מזרח ושוקעת בחצי מערב,\u0004","\u0003שנאמר\u0004 במקרא: \"דור הולך ודור בא והארץ לעולם עומדת. וזרח השמש ובא השמש ואל מקומו שואף זורח הוא שם. \u0003הולך אל דרום וסובב אל צפון\u0004 סובב סובב הולך הרוח ועל סביבותיו שב הרוח\" (קהלת א, ד-ו) ומבארים פסוק זה כמתאר את כיוון זריחת השמש: \"הולך אל דרום וסובב אל צפון\", ובאופן זה: \u0003\"הולך אל דרום\" — ביום. \"וסובב אל צפון\"\u0004 מצידו האחר של העולם — \u0003בלילה. \"סובב סבב הולך הרוח\"\u0004 (\"רוח\" במשמעות צד, כיוון) — \u0003אלו פני מזרח ופני מערב,\u0004 ש\u0003פעמים\u0004 השמש \u0003מהלכתן ופעמים מסבבתן,\u0004 שלפעמים עוברת השמש בגלוי בכיוון זה, ופעמים אינה עוברת.","\u0003אמר רב משרשיא: ליתנהו להני כללי\u0004 \u0005[אין\u0006 ממש \u0005באותם הכללים]\u0006 שקבע ר' יוסי, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יצאה חמה מעולם\u0004 אפילו בימי הקיץ \u0003מקרן מזרחית צפונית ושקעה בקרן מערבית צפונית, ולא יצאה חמה\u0004 אף בחורף \u0003מקרן מזרחית דרומית ושקעה בקרן מערבית דרומית.\u0004 ולכן אין לסמוך על כך, אלא על מהלך השמש שבימי הסתיו והאביב בלבד.","ואגב הדיבור בזה ובחישוב כיוון הרוחות לפי מהלך התקופה, \u0003אמר שמואל: אין תקופת ניסן\u0004 (שויון היום והלילה) \u0003נופלת\u0004 (מזדמנת) \u0003אלא בארבעה רבעי היום\u0004 (היממה), \u0003או בתחלת היום\u0004 ברגע של תחילת היום \u0003או ב\u0004רגע \u0003תחילת הלילה, או בחצי היום או בחצי הלילה.\u0004","וכן \u0003אין תקופת תמוז נופלת אלא או ב\u0004שעה \u0003אחת ומחצה, או בשבע\u0004 שעות \u0003ומחצה, בין ביום ובין בלילה. ואין תקופת תשרי נופלת אלא או בשלש שעות או בתשע שעות, בין ביום ובין בלילה. ואין תקופת טבת נופלת אלא או בארבע ומחצה או בעשר ומחצה, בין ביום ובין בלילה.\u0004","\u0003ו\u0004כל זה נסמך על העיקרון כי \u0003אין בין תקופה לתקופה אלא תשעים ואחד יום ושבע שעות ומחצה,\u0004 שלדעתו ימות השנה הם בדיוק שלש מאות ששים וחמשה יום ורבע. \u0003ו\u0004כן גם \u0003אין תקופה מושכת מחברתה\u0004 כלומר מאחרת, לפי חשבון המזלות ששעות היום קשורות בהם, \u0003אלא חצי שעה.\u0004","\u0003ואמר שמואל: אין לך תקופת ניסן שנופלת ב\u0004שעת מזל \u0003צדק, שאינה\u0004 בשעה שתהיה בה רוח \u0003משברת את האילנות. ואין לך תקופת טבת שנופלת\u0004 בשעתו של מזל \u0003צדק, שאינה מייבשת את הזרעים. והוא,\u0004 ודברים אלה אמורים \u0003דאיתליד\u0004 \u0005[שהיה מולד]\u0006 ה\u0003לבנה או ב\u0004שעת מזל \u0003לבנה או ב\u0004שעת מזל \u0003צדק.\u0004"],["\u0003תנו רבנן\u0004 \u0005[\u0006שנו חכמים]: \u0003המרבע את העיר\u0004 לצורך קביעת תחום שבת, אם לא היתה מרובעת — \u0003עושה אותה כמין טבלא מרובעת. וחוזר ומרבע את התחומין, ועושה\u0004 אף \u0003אותן כמין טבלא מרובעת,\u0004 לאחר שריבע את העיר מוסיף לכל צלע ריבוע נוסף של אלף אמה על אלפיים אמה.","\u0003וכשהוא מודד\u0004 את תחום העיר, \u0003לא ימדוד מאמצע הקרן\u0004 (זוית ריבוע העיר) \u0003אלפים אמה — מפני שהוא מפסיד את הזויות,\u0004 שעל ידי כך נמצא שיהא המרחק אלפיים אמה בכל צד ממש. \u0003אלא\u0004 עושה חשבון כאילו היה \u0003מביא טבלא מרובעת שהיא אלפיים אמה על אלפים אמה, ומניחה בקרן באלכסונה,\u0004 ו","\u0003נמצאת העיר משתכרת\u0004 (מקבלת, מוסיפה לעצמה) \u0003ארבע מאות אמות לכאן וארבע מאות אמות לכאן,\u0004 שעל ידי תוספת זו של ריבוע נעשו כעין זויות לעיר, ואפשר ללכת מקצה העיגול עד לסוף הזויות שבריבוע ארבע מאות אמה. וכאשר אתה מוסיף טבלה גם בזוויות ריבוע העיר הרי \u0003נמצאו תחומין\u0004 של העיר \u0003משתכרין\u0004 (מוסיפין) על ידי תבנית זו \u0003שמונה מאות אמות לכאן ושמונה מאות\u0004 אמות \u0003לכאן. נמצאו העיר ותחומין\u0004 יחד \u0003משתכרין אלף ומאתים\u0004 אמה \u0003לכאן ואלף ומאתים\u0004 אמה \u0003לכאן,\u0004 על ידי שעושין את תחומי העיר בריבועים.","\u0003אמר אביי: ומשכחת לה במתא דהויא תרי אלפי אתרי אלפי\u0004 \u0005[ומוצא אתה אותה\u0006 במדות שנאמרו \u0005בעיר שהיא אלפים\u0006 אמה \u0005על אלפים\u0006 אמה\u0005],\u0006 שאם היתה עיר עגולה בקוטר זה ומרבעים וחוזרים ומרבעים אותה, מקבלים תוספת בשיעורים אלה.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 העוסקת בנושא קרוב ביחס למדידת ערי הלויים \u0003אמר ר' אליעזר בר' יוסי: תחום ערי לוים\u0004 מחוץ לגבול העיר ממש \u0003אלפים אמה\u0004 לכל צד. \u0003צא\u0004 (הוצא) \u0003מהן\u0004 מתחום \u0003אלף אמה\u0004 של \u0003מגרש\u0004 העיר הנשאר פנוי — \u0003נמצא מגרש רביע\u0004 משטח העיר ותחומיה, \u0003והשאר שדות וכרמים.\u0004","ושואלים מתחילה: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שמידת המגרש היא אלף אמה? \u0003אמר רבא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ו\u0004מגרשי הערים אשר תתנו ללויים \u0003מקיר העיר וחוצה אלף אמה סביב\"\u0004 (במדבר לה, ד), \u0003אמרה תורה: סבב את העיר באלף\u0004 אמה מכל צד לצורך מגרש, ועל ידי כך \u0003נמצא מגרש רביע\u0004 העיר.","ושואלים: וכי \u0003רביע\u0004 הוא?! \u0003פלגא הוי\u0004 \u0005[חצי הינו]!\u0006 הרי אלף חצי הוא מאלפיים שהם תחום \u0003העיר, אמר רבא: בר אדא משוחאה\u0004 \u0005[המודד]\u0006 \u0003אסברה\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 כיצד לחשב זאת — \u0003משכחת לה במתא דהויא תרי אלפי אתרי אלפי\u0004 \u0005[מוצא אתה\u0006 זאת \u0005בעיר שהיא\u0006 עצמה \u0005אלפים על אלפים\u0006 אמה\u0005].\u0006 \u0003תחום\u0004 העיר עצמה, ללא הפינות, \u0003כמה\u0004 אמות \u0003הויא\u0004 \u0005[הוא]?\u0006 \u0003שיתסר\u0004 \u0005[ששה עשר\u0006 אלף\u0005].\u0006 כיצד? אם מחשבים לכל צד אלפים אמה לרוחב העיר ועוד אלפים תחום, נמצא שבכל צד של העיר יש שטח של ארבעת אלפים אמה כפול ארבע שהם ששה עשר אלף אמות. \u0003קרנות\u0004 העיר \u0003כמה\u0004 אמות \u0003הויין\u0004 \u0005[הן]?\u0006 \u0003שיתסר\u0004 \u0005[ששה עשר\u0006 אלף\u0005],\u0006 שהרי כפי שנאמר יש טבלה בת אלפים על אלפים אמה בכל פינה של העיר. \u0003דל\u0004 \u0005[הוצא,\u0006 הפחת\u0005]\u0006 את תחום המגרש, מוצא אתה שם \u0003תמניא דתחומין\u0004 \u0005[שמונה\u0006 אלפים \u0005של תחומין]\u0006 שהם רוחב אלפים אמה ברוחב אלף לכל צד, \u0003ו\u0004עוד \u0003ארבעה\u0004 אלפים של \u0003קרנות, כמה הוי\u0004 \u0005[כמה הוא\u0006 סך הכל\u0005]\u0006 — \u0003תריסר\u0004 \u0005[שנים עשר].\u0006","ומקשים: איך לחשבון זה \u0003נמצא מגרש רביע\u0004 העיר, הלא \u0003טפי מתלתא נינהו\u0004 \u0005[יותר משליש הוא],\u0006 שאם כל תחום העיר הוא שלשים ושניים אלף אמה מרובעות והמגרש הוא שנים עשר אלף, הרי שהמגרש הוא יותר משליש תחום העיר ולא רבע!","ומסבירים: \u0003אייתי ארבעה דמתא שדי עלייהו\u0004 \u0005[הבא,\u0006 הוסף עוד את \u0005ארבעת\u0006 אלפים האמה \u0005של העיר\u0006 עצמה, ו\u0005הוסף עליהם\u0006 על שטח התחומין\u0005]\u0006 ועל ידי כך תמצא יחס זה. ומקשים: \u0003אכתי תילתא הוי\u0004 \u0005[עדיין שליש הוא],\u0006 שאם כל שטח העיר הוא שלושים וששה אלף אמה מרובעות, והמגרש שנים עשר אלף, נמצא שהמגרש הוא שליש העיר בדיוק!","ומשיבים: \u0003מי סברת בריבועא קאמר\u0004 \u0005[האם סבור אתה\u0006 שבעיר \u0005מרובעת נאמרה\u0006 הלכה זו\u0005]?\u0006 \u0003בעיגולא קאמר\u0004 \u0005[בעיגול נאמרה]\u0006 וכשהעיר עגולה, אף מגרש העיר עגול, ואילו לתחומי העיר מרבעים סביב. ונמצא שתחום העיר הוא כאמור שלשים וששה אלף אמה.","ומעתה נחשב: \u0003כמה מרובע יתר\u0004 בשטחו \u0003על העגול? רביע, דל\u0004 \u0005[הוצא]\u0006 \u0003רביע מינייהו\u0004 \u0005[מהם]\u0006 מחשבון המגרש שאמרנו, שהוא שנים עשר אלף — \u0003פשו להו\u0004 \u0005[נשארו להם]\u0006 \u0003תשעה\u0004 אלפים. \u0003ותשעה מתלתין ושיתא, ריבעה הוי\u0004 \u0005[משלושים וששה, רבע הוא].\u0006","\u0003אביי אמר: משכחת לה נמי במתא דהויא אלפא באלפא\u0004 \u0005[מוצא אתה אותה גם כן בעיר שהיא אלף על אלף\u0006 אמה\u0005].\u0006 \u0003תחומין כמה הוו\u0004 \u0005[הם],\u0006 \u0003תמניא\u0004 \u0005[שמונה\u0006 אלפים\u0005].\u0006 כיצד? אלף אמה אורך מכל צד ואלפים אמה לרוחב התחום, נמצא שאלפיים אמה כפול ארבע, שהם שמונת אלפים אמה. שיעור \u0003קרנות\u0004 בעיר \u0003כמה הוי\u0004 \u0005[הוא]\u0006 — כפי שנאמר כבר, הוא \u0003שיתסר\u0004 \u0005[ששה עשר\u0006 אלף אמה\u0005],\u0006"],["\u0003דל\u0004 \u0005[הוצא]\u0006 לצורך המגרש \u0003ארבע\u0004 אלפים של \u0003תחומין\u0004 עצמם, \u0003וארבע\u0004 אלפים של ה\u0003קרנות.\u0004 שהרי למגרש אלף אמה, ובכל צד של העיר אלף על אלף, נמצא אלף על אלף ארבע פעמים ועוד ארבע פעמים אלף בפינות העיר \u0003כמה הוי\u0004 \u0005[הוא]\u0006 — \u0003תמניא\u0004 \u0005[שמונה].\u0006","ומקשים: אם כן, אם כל תחום העיר — \u0003תילתא הוו\u0004 \u0005[הרי הוא שליש]\u0006 מעשרים וארבעה אלף! ומשיבים: כפי שאמרנו \u0003מי סברת בריבועא קאמר\u0004 \u0005[האם סבור אתה\u0006 שבעיר \u0005מרובעת נאמר]?\u0006 \u0003בעיגולא קאמר\u0004 \u0005[ב\u0006עיר \u0005עגולה נאמר].\u0006 \u0003כמה מרובע יתר על העגול\u0004 בשטחו — \u0003רביע, דל רביע — פשו לה שיתא\u0004 \u0005[הוצא רבע —\u0006 \u0005נשארו להם שש].\u0006 שהעיר עצמה והתחומים מהמגרש של שמונת אלפים חסר רביע הרי הם ששה. \u0003ושיתא\u0004 \u0005[וששה]\u0006 \u0003מעשרים וארבע, ריבעא הוי\u0004 \u0005[רבע הוא].\u0006","\u0003רבינא אמר: מאי\u0004 \u0005[מהו]\u0006 \u0003רביע\u0004 שנאמר שם שהמגרש רביע הוא, הכוונה \u0003רביע\u0004 של \u0003תחומין.\u0004 שמדובר כאן בעיר מרובעת, אלא שלאמיתו של דבר אין נותנים מגרש לקרנות העיר אלא רק לתחומים עצמם. שלעיר בת אלפיים אמה ניתנים לפי החשבון תחומים של עשרים וארבע אלף. ובדרך זו נמצא כי המגרש שהוא אלף על אלפיים אמה לכל צד ובחשבון כולל הוא שמונת אלפים אמה, הרי הוא רבע משטח התחומים.","\u0003רב אשי אמר\u0004 להיפך: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003רביע\u0004 שנאמר, הרי זה \u0003רביע קרנות.\u0004 שאין נותנים לעיר מגרש לפניה, אלא נותנים לה מגרש רק בפינות העיר. נמצא שמגרש העיר הוא אלף אמה על אלף אמה בכל פינה, שהם ארבעת אלפים אמה יחד. ואילו שטח התחומין הוא אלפים על אלפים בכל צד, וביחד הם ששה עשר אלף אמה. נמצא שמגרש העיר הוא רבע ממגרש התחומים.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבינא לרב אשי: והא\u0004 \u0005[והרי]\u0006 \u0003\"סביב\" כתיב\u0004 [\u0005נאמר].\u0006 משמע שהתחום צריך להיות בכל סביבות העיר ולא בפינות!","ענה לו: \u0003מאי\u0004 \u0005[מהו\u0006 שנאמר\u0005]\u0006 \u0003\"סביב\" — סביב\u0004 של \u0003קרנות,\u0004 שבכל פינה נותנים מגרש כזה. \u0003דאי לא תימא הכי\u0004 \u0005[ש\u0006כן \u0005אם לא תאמר כך]\u0006 שאף מה שנמצא בכל פינה קרוי \"סביב\", אף \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עולה דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"וזרקו את הדם על המזבח סביב\"\u0004 (ויקרא א, ה) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003סביב ממש,\u0004 שצריך לזרוק את הדם \"סביב\" — סביב למזבח ממש?! \u0003אלא מאי\u0004 \u0005[מהו]\u0006 שנאמר \"\u0003סביב\" — סביב\u0004 של \u0003קרנות,\u0004 שהמצוה לזרוק את הדם בפינות ממש, והוא נחשב סביב. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מאי\u0004 \u0005[מהו\u0006 שנאמר\u0005]\u0006 \u0003\"סביב\" — סביב\u0004 של \u0003קרנות.\u0004","עתה חוזרים לשאלה ולהסבר שנאמר במשנה ביחס לעודף שנוסף על תחום העיר על ידי ריבועה ולא על ידי העמדת תחומים עגולים כפי צורתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבי מחוזנאה\u0004 \u0005[ממחוזא]\u0006 \u0003לרב אשי: והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מורשא דקרנתא\u0004 \u0005[פינת הקרנות],\u0006 איך לחשבון זה יהיו אלף אמה מגרש בכל צד, והרי לכשמרבעים את העיר נכנסים קרנות הריבוע בתוך תחום המגרש ומפחיתים משטחו!","ענה לו: מדובר כאן \u0003במתא עיגולתא\u0004 \u0005[בעיר עגולה]\u0006 ובעיר כזו זוהי התוספת הן לצורך הריבוע של העיר והן בריבוע התחומין. שאל אותו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ריבעוה\u0004 את העיר, ושוב אין להחשיב את התוספת שיש בה בעיגולה? ענה לו רב אשי: \u0003אימור דאמרינן חזינן כמאן דמרבעא\u0004 \u0005[אמור שאנו אומרים: רואים אנו\u0006 את העיר \u0005כמו שהיתה מרובעת]\u0006 \u0003רבועי ודאי מי מרבענא\u0004 \u0005[לרבע ממש האם מרבעים אותה]?\u0006 וכי מוסיפים לה בתים בריבוע?! ואף שלצורך חשבון רואים אנו כאילו היתה מרובעת, מכל מקום המרחק הממשי מקצה העיר עד זוית תחום העיר גדול יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנילאי מחוזנאה\u0004 \u0005[ממחוזא]\u0006 \u0003לרב אשי: מכדי\u0004 \u0005[מכיון]\u0006 ש\u0003כמה מרובע יתר על העגול — רביע,\u0004 ואם נחשוב לפי זה את חשבון אלפים אמות של העיר, האם על ידי התוספת בריבוע נגיע לכדי \u0003הני תמני מאה\u0004 \u0005[אותם שמונה מאות]\u0006 שהוזכרו, הלא לפי החשבון רק \u0003שית מאה ושיתין ושבע נכי תילתא הוי\u0004 \u0005[שש מאות וששים ושבע פחות שליש יש\u0006 אמות יתירות\u0005]\u0006 ולא שמונה מאות!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי בעיגולא מגו\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בעגול מתוך]\u0006 \u0003רבוע,\u0004 כלומר ששטח העיגול הוא שלשה רבעים משטח הריבוע החוסם אותו. \u0003אבל באלכסונא — בעינא טפי\u0004 \u0005[\u0006לגבי \u0005האלכסון\u0006 הנוסף בשל קרנות הריבוע \u0005—\u0006 \u0005דרוש יותר],\u0006 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל אמתא\u0004 \u0005[אמה]\u0006 ש\u0003בריבוע —\u0004 הוא \u0003אמתא ותרי חומשי באלכסונא\u0004 \u0005[אמה ושתי חמישיות באלכסון],\u0006 ולפי זה החשבון מדוייק.","\u0003נותנין\u0004 לכל עיר, נוסף על תחומה הממשי, גם \u0003קרפף\u0004 (שבעים אמה ומשהו) \u0003לעיר\u0004 שיהא לה מגרש קטן פנוי סביב, אלה \u0003דברי ר' מאיר. וחכמים אומרים: לא אמרו\u0004 תוספת \u0003קרפף אלא בין שתי עיירות,\u0004 כיצד? \u0003אם יש לזו שבעים אמה ושיריים\u0004 פנויים בצידה, \u0003ולזו שבעים אמה ושיריים — עושה קרפף את שתיהן להיות\u0004 כמקום \u0003אחד.\u0004","\u0003וכן שלושה כפרים המשולשין,\u0004 המצויים כבקודקודיו של משולש, \u0003אם יש בין שנים חיצונים מאה וארבעים ואחת ושליש\u0004 אמות בלבד — \u0003עשה\u0004 הכפר ה\u0003אמצעי את שלשתן להיות אחד.\u0004","שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שמוסיפים על העיר תחום קרפף? \u0003אמר רבא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ומגרשי הערים אשר תתנו ללוים \u0003מקיר העיר וחוצה\u0004 אלף אמה סביב. ומדתם מחוץ לעיר את פאת קדמה אלפים באמה\" (במדבר לה, ד-ה) \u0003אמרה תורה: תן חוצה,\u0004 מגרש מסויים שיהיו חוצות לעיר, שיהא מקום פנוי לה, \u0003ואחר כך מדוד.\u0004","במשנה שנינו: \u0003וחכמים אומרים\u0004 שנותנים קרפף רק לשתי עיירות צמודות. בנושא זה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים; \u0003רב הונא אמר: נותנין קרפף לזו וקרפף לזו\u0004 כלומר לשתי הערים יחד נותנים מאה ארבעים ואחת אמות ומשהו. ואילו \u0003חייא בר רב אמר:\u0004 נותנין רק \u0003קרפף אחד\u0004 משותף \u0003לשתיהן.\u0004","ומעתה דנים בראיות שיש לסברות אלה; \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003וחכמים אומרים: לא אמרו קרפף אלא בין שתי עיירות,\u0004 ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 על\u0005]\u0006 \u0003רב הונא,\u0004 שהרי נאמר כאן קרפף ולא קרפפים!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003רב הונא\u0004 בתירוץ קושיה זו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003קרפף,\u0004 הכוונה ל\u0003תורת\u0004 (דין) \u0003קרפף ולעולם\u0004 (ולמעשה) נותנין \u0003קרפף לזו וקרפף לזו.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 בהבנת הדברים, \u0003מדקתני סיפא\u0004 \u0005[ממה ששנינו\u0006 ב\u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אם יש לזו שבעים אמה ושיריים ולזו שבעים אמה ושיריים — עושה קרפף לשתיהן להיות אחד,\u0004 נמצא שכל עיר מוסיפין לה שבעים אמה ושיריים. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[נלמד ממנה]\u0006 שכן הוא דיוקה של משנה.","ושואלים: אם כן \u0003לימא תיהוי תיובתיה\u0004 \u0005[האם לומר\u0006 ש\u0005תהא זו קושיה חמורה\u0006 על\u0005]\u0006 \u0003חייא בר רב\u0004 מאותה משנה עצמה, שהרי לדעתו אין נותנים לשתי ערים סמוכות אלא קרפף אחד! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003חייא בר רב:\u0004"],["\u0003הא מני\u0004 \u0005[\u0006הלכה \u0005זו כ\u0006שיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' מאיר היא\u0004 האומר שלכל עיר נותנים קרפף.","ומוסיפים להקשות: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' מאיר היא, הא תני ליה רישא\u0004 \u0005[הרי\u0006 כבר \u0005שנינו אותו מתחילה]:\u0006 \u0003נותנין קרפף לעיר, דברי ר' מאיר,\u0004 ולמה יש לחזור על כך?","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 בכל זאת לומר גם דבר זה, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מההיא,\u0004 מהלכה ראשונה בלבד, \u0003הוה אמינא: חד לחדא, וחד לתרתי\u0004 \u0005[הייתי אומר:\u0006 קרפף \u0005אחד ל\u0006עיר \u0005אחת, ואחד לשתיים],\u0006 שדי שיהא שטח פנוי אחד, \u0003קא משמע לן דלתרתי תרי יהבינן להו\u0004 \u0005[משמיע לנו שלשתי\u0006 ערים \u0005שני\u0006 קרפפים \u0005נותנים להן].\u0006","ולהיפך, \u0003ואי אשמעינן הכא\u0004 \u0005[ואם היה משמיע לנו\u0006 רק \u0005כאן\u0006 בענין שתי ערים נפרדות\u0005]\u0006 היינו סבורים שנותנים קרפף לכל אחת לחוד, \u0003משום דדחיקא תשמישתייהו\u0004 \u0005[שדחוק תשמישן],\u0006 ששתיהן משתמשות שם ובין שתי ערים הסמוכות זו לזו יש לתת מקום יתר, \u0003אבל התם דלא דחיקא תשמישתייהו\u0004 \u0005[שם\u0006 בעיר אחת \u0005שאין שימושם דחוק]\u0006 ויכולים להסתפק בתחום העיר שלהם, \u0003אימא לא\u0004 \u0005[אמור\u0006 ש\u0005לא]\u0006 יתנו להן קרפף כלל, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 להשמיענו שתי הלכות אלה.","ועוד מנסים להוכיח ממשנתנו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה: \u0003וכן שלשה כפרים המשולשין\u0004 שכל השלושה נמצאים בקו ישר, \u0003אם יש בין שנים החיצונים מאה וארבעים ואחת אמה ושליש — עושה אמצעי את שלשתן להיות אחד,\u0004 ונדייק: \u0003טעמא דאיכא\u0004 \u0005[הטעם\u0006 הוא, דווקא משום \u0005שיש]\u0006 \u0003אמצעי, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003אמצעי — לא\u0004 היו נחשבות לאחד. \u0003תיובתא\u0004 \u0005[\u0006הרי זה \u0005קושיה חמורה]\u0006 ל\u0003רב הונא\u0004 שהרי לשיטת רב הונא גם בלא כפר אמצעי היו שני הכפרים נחשבים כאחד בשל הקרפף הכפול!","\u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003רב הונא: הא אתמר עלה\u0004 \u0005[הרי נאמר על\u0006 משנה זו\u0005],\u0006 \u0003אמר רבה אמר רב אידי אמר ר' חנינא: לא משולשין ממש\u0004 שהיו הכפרים מצויים בשורה אחת סמוכים זה לזה, אלא שהאמצעי נוטה כלפי חוץ, ובכל זאת אינם נאסרים זה בזה, \u0003אלא\u0004 אפילו היו הכפרים רחוקים יותר משני קרפפים \u0003רואין כל שאילו מטיל אמצעי ביניהן,\u0004 כלומר אילו היו מקרבים את האמצעי ואז \u0003יהיו משולשין, ואין בין זה לזה אלא מאה וארבעים אמה ואחת ושליש.\u0004 הרי במקרה זה \u0003עשה אמצעי את שלשתן להיות אחד.\u0004 ולפי הסבר זה הרי לפנינו דין מיוחד, ולא עוד אלא שיש בו סיוע מסויים לדברי רב הונא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי\u0004 באותו ענין: \u0003כמה יהא\u0004 המרחק \u0003בין\u0004 כפר \u0003חיצון לאמצעי\u0004 שאפשר יהא לומר שייחשב הכפר האמצעי כאילו הוא בין שני החיצונים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אלפים אמה,\u0004 אמר לו רבא:","\u0003והא את הוא דאמרת\u0004 \u0005[והרי אתה\u0006 עצמך \u0005הוא\u0006 זה \u0005שאמרת]:\u0006 \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר רב הונא מסתברא\u0004 \u0005[מסתבר],\u0006 ש\u0003אמר:\u0004 עיר העשויה כקשת, מודדים את כל השטח הפנוי שבקשת כחלק מן העיר, ואפילו היה המרחק בין היתר לקשת \u0003יותר מאלפים אמה!\u0004 ומדוע לא נחשוב אף כאן את שלושת הכפרים כאחד, גם אם היו מרוחקים יותר מאלפיים אמה?","ודחה אביי את ההשוואה: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בעיר העשויה כקשת, \u0003איכא\u0004 \u0005[יש]\u0006 \u0003בתים\u0004 המחברים את העיר כולה להיות כיחידה אחת. ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003בתים\u0004 המחברים בין החיצוני והפנימי. ואין לראות שני כפרים, המרוחקים זה מזה יותר מתחום שבת, כאילו היה זה אחד.","\u0003ו\u0004עוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי: כמה יהא\u0004 המרחק \u0003בין חיצון לחיצון?\u0004 ותהה אביי: מה מקום לשאלה \u0003כמה יהא?! מאי נפקא לך מינה\u0004 [\u0005מה יוצא לך\u0006 משאלה \u0005זו]?\u0006 והרי אין כל הבדל להלכה בדבר, אלא \u0003כל שאילו מכניס אמצעי ביניהן ואין בין זה לזה אלא מאה וארבעים ואחת ושליש\u0004 אמה, ואין מתחשבים במרחק שבין החיצונים, אלא בגודלו של הכפר האמצעי.","והוסיף רבא ושאל: \u0003ואפילו\u0004 אם יהא המרחק \u0003ארבעת אלפים אמה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן\u0006 הוא\u0005].\u0006 והוסיף ושאל: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: עיר העשויה כקשת, אם יש בין שני ראשיה פחות מארבעת אלפים אמה — מודדין לה\u0004 תחום שבת \u0003מן היתר, ואם לאו — מודדין לה מן הקשת!\u0004 נמצא שבמרחק הגדול מארבעת אלפים אמה אף בעיר הבנויה ברציפות אומרים שהמרחק בין קצותיה גדול משתיחשב כעיר אחת?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בעיר העשויה כקשת \u0003ליכא למימר \"מלי\"\u0004 \u0005[אין\u0006 מקום \u0005לומר \"מלא\"],\u0006 שהרי אין לך במה למלא את תחום העיר. \u0003הכא איכא למימר \"מלי\"\u0004 \u0005[כאן יש\u0006 מקום \u0005לומר \"מלא\"]\u0006 והכנס את הכפר האמצעי ביניהם, והרי הם כסמוכים זה לזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לרבא: הרי בני\u0004 העיר \u0003אקיסטפון, דמשחינן להו תחומא מהאי גיסא\u0004 \u0005[שמודדים אנו להם את התחום מצד זה]\u0006 של העיר \u0003ארדשיר, ובני תחומא דארדשיר משחינן להו תחומא מהאי גיסא\u0004 \u0005[ובני התחום של ארדשיר\u0006 שהיא מעברו השני של הנהר \u0005מודדים אנו להם את התחום מצד זה]\u0006 של \u0003אקיסטפון,\u0004 ומחשיבים את שתי הערים כאילו היו לעיר אחת. ואולם \u0003הא איכא דגלת\u0004 \u0005[הרי ישנו\u0006 הנהר \u0005חידקל]\u0006 \u0003דמפסקא\u0004 \u0005[המפסיק]\u0006 ביניהן בשיעור \u0003יתר ממאה וארבעים ואחת ושליש\u0004 אמות? וכיצד מצרפין את הערים, שהמרחק ביניהן גדול אף משיעור שני קרפפים?","\u0003נפק, אחוי ליה הנך אטמהתא דשורא, דמבלעי בדגלת\u0004 \u0005[יצא, הראה לו אותם יסודות החומה\u0006 של אחת הערים\u0005, הנבלעים בחידקל]\u0006 \u0003בשבעים אמה ושיריים\u0004 מן העיר השניה. שבאמת היו שתי הערים מחוברות זו לזו על ידי שרידי החומה שבנהר.","\u0003אין מודדין\u0004 תחומין \u0003אלא בחבל\u0004 שאורכו \u0003חמישים אמה, לא פחות ולא יותר,\u0004 כאשר יבואר בגמרא. \u0003ולא ימדוד אלא כנגד לבו,\u0004 שכל אחד מהמודדים יחזיק את החבל כנגד לבו.","\u0003היה מודד והגיע לגיא או לגדר,\u0004 אינו צריך לחשוב בתוך אלפיים אמה את גובה הגדר או עומק הגיא, אלא \u0003מבליעו\u0004 כאילו לא היה כלל, \u0003וחוזר למדתו,\u0004 כאילו היה זה שטח מישור ללא עליות וירידות. \u0003הגיע להר,\u0004 אינו צריך למדוד את גובהו, אלא \u0003מבליעו וחוזר למדתו,\u0004 כאילו לא היה כאן הר."],["\u0003ובלבד שלא יצא\u0004 אגב כך \u0003חוץ לתחום\u0004 שבת של העיר, שמא יטעו הרואים את המודד ויחשבו שעד שם מגיע התחום.","\u0003אם אינו יכול להבליעו\u0004 משום שהיו הגיא או ההר רחבים ביותר — \u0003בזו אמר ר' דוסתאי בר ינאי משום ר' מאיר: שמעתי שמקדרין\u0004 (שכאילו עושים כעין נקב) \u0003בהרים,\u0004 כלומר מודדים במדרון באופן שאפשר לחשב היכן מסתיים תחום שבת בתוך שטח הגיא וההר.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שצריך למדוד בחבל שאורכו חמישים אמה? \u0003אמר רב יהודה אמר רב:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ארך החצר מאה באמה ורחב חמשים בחמשים\"\u0004 (שמות כז, יח) \u0003אמרה תורה: בחבל של חמשים אמה מדוד\u0004 כלומר את אורך החצר ורוחבה יש למדוד \"בחמישים\", חבל שאורכו חמישים אמה.","ומקשים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006הכפלה \u0005זו נצרכת לו]\u0006 ללמדנו ענין אחר, ששטחה של חצר הוא כריבוע ששטחו כחצר המשכן, ולשם חישוב זה צריך \u0003ליטול חמשים\u0004 אמה \u0003ולסבב\u0004 מסביב להם עוד \u0003חמשים\u0004 אמה כדי לבנות ריבוע.","ומשיבים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]:\u0006 \u0003\"חמשים חמשים\"\u0004 ודי בכך ללמדנו מה שטח החצר, \u0003מאי\u0004 \u0005[מה\u0006 ההדגשה של\u0005]\u0006 \u0003\"חמשים בחמשים\" — שמעת מינה\u0004 \u0005[שומע אתה מכאן]\u0006 \u0003תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 גם לענין ריבוע וגם לענין אורך כלי המידה.","במשנה נאמר שמידת חבל זה קבועה, \u0003\"לא פחות ולא יותר\". תנא\u0004 \u0005[\u0006בתוספתא \u0005שנינו]:\u0006 \u0003\"לא פחות\"\u0004 — משום שאם החבל קצר, \u0003מרבה\u0004 את התחום. שהחבל ניתן למתיחה יותר ממדתו. \u0003\"ולא יותר\"\u0004 ולא יוסיף במידת החבל, \u0003מפני שממעט\u0004 במידות. שמחמת כובד החבל תתמעט המידה.","\u0003אמר ר' אסי: אין מודדין אלא בחבל של אפסקימא.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003אפסקימא? אמר ר' אבא:\u0004 הוא הצמח \u0003נרגילא,\u0004 ואף זה משמעותו לא היתה ידועה לכל. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003נרגילא? אמר ר' יעקב: דיקלא דחד נברא\u0004 \u0005[דקל ש\u0006מסביבו מסתלסל רק \u0005סיב אחד]\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאמרו\u0006 בלשון אחרת\u0005],\u0006 ששאלו: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003אפסקימא? ר' אבא אמר:\u0004 הוא הצמח \u0003נרגילא, ר' יעקב אמר:\u0004 הוא \u0003דיקלא דחד נברא\u0004 \u0005[דקל\u0006 בעל \u0005סיב אחד].\u0006","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהושע בן חנניא:\u0004 האמת היא ש\u0003אין לך\u0004 דבר \u0003שיפה למדידה\u0004 שאינו ניתן להימתח יתר על מידתו \u0003יותר משלשלאות של ברזל, אבל מה נעשה שהרי אמרה תורה: \"\u0004ואשא עיני וארא והנה איש \u0003ובידו חבל מדה\"\u0004 (זכריה ב, ה), ומכאן למדים שדרך המדידה היא בחבל.","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בכתוב אף דרך אחרת של מדידה: \u0003\"וביד האיש קנה המדה\u0004 שש אמות באמה וטפח\u0003\"\u0004 (יחזקאל מ, ה), משמע שאפשר למדוד אף בקנים! ומשיבים: \u0003ההוא, לתרעי\u0004 \u0005[ל\u0006ענין רוחב \u0005השערים]\u0006 שמידתם קטנה וקשה למדוד אותם בחבל המידה הארוך.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: שלשה\u0004 סוגי \u0003חבלים הם\u0004 שדובר בהם בהלכה: חבל \u0003של מגג\u0004 (מין קנה סוף), חבל \u0003של נצר\u0004 (שעושים מסיבי הדקל) \u0003ו\u0004חבל \u0003של פשתן.\u0004","ושימושם: חבל \u0003של מגג\u0004 משתמשים בו בשריפת ה\u0003פרה\u0004 האדומה, כפי ששנינו בדרך עשייתה: \u0003כפתוה\u0004 את הפרה \u0003בחבל המגג, ונתנוה על גב מערכתה,\u0004 העצים הערוכים שם, שישרפוה עליהם לאחר שחיטתה. חבל \u0003של נצרים\u0004 משמש \u0003ל\u0004צורך \u0003סוטה. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 שלפני שמשקים אותה את המים המאררים (במדבר ו) קורעים את בגדיה, \u0003ואחר כך מביא\u0004 הכהן \u0003חבל המצרי\u0004 העשוי נצרים \u0003וקושרו למעלה מדדיה\u0004 שלא יפלו בגדיה. חבל \u0003של פשתן\u0004 הוא העשוי \u0003למדידה.\u0004","שנינו במשנה: \u0003היה מודד והגיע\u0004 להר או לגדר, מבליעו וחוזר למידתו, ומעירים על כך: \u0003מדתני\u0004 \u0005[ממה ששנינו]\u0006 \u0003\"חוזר למידתו\" מכלל\u0004 הדברים נלמד ש\u0003אם אינו יכול להבליעו, הולך למקום שיכול להבליעו, ומבליעו, וצופה\u0004 באותו מקום \u0003כנגד מידתו\u0004 באותו מרחק \u0003וחוזר.\u0004","ומעירים כי אכן \u0003תנינא להא\u0004 \u0005[שנינו\u0006 דבר \u0005זה],\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003היה מודד והגיע המידה לגיא, אם יכול להבליעו\u0004 את הגיא \u0003בחבל של חמשים אמה,\u0004 שרוחב הגיא פחות מחמשים — מ\u0003בליעו. ואם לאו — הולך למקום שיכול להבליעו ומבליעו, וצופה וחוזר למידתו באותו מקום. ו\u0004","\u0003אם היה גיא מעוקם\u0004 שהוא סביב לעיר מכמה צדדים, ואינו יכול להבליעו — \u0003מקדיר ועולה, מקדיר ויורד,\u0004 ומודד את רוחבו חלקים חלקים. \u0003הגיע לכותל — אין אומרים יקוב הכותל\u0004 כדי למדוד רוחבו בדיוק, \u0003אלא אומדו והולך לו.\u0004","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]:\u0006 \u0003מבליעו וחוזר למידתו,\u0004 ומדוע אין עושין כן גם בכותל? ומסבירים: \u0003התם ניחא תשמישתא\u0004 \u0005[שם\u0006 בגיא \u0005נוח השימוש\u0006 בו\u0005]\u0006 ולכן אם יכול, הריהו מבליעו. ואם לא, הריהו מקדיר. \u0003הכא, לא ניחא תשמישתא\u0004 \u0005[כאן\u0006 בכותל, \u0005לא נוח השימוש\u0006 בו\u0005].\u0006","\u0003אמר רב יהודה אמר שמואל: לא שנו\u0004 שמקדרים בהרים וגיאיות \u0003אלא\u0004 כשאין הגיא תלול עד \u0003שאין חוט המשקולת יורד כנגדו\u0004 כלומר שיש בו שיפוע,"],["\u0003אבל\u0004 אם היה \u0003חוט המשקולת יורד כנגדו,\u0004 שהיה קיר הגיא תלול מאוד — \u0003מודדו מדידה יפה\u0004 בתחתיתו ואינו מחשיב כלל במידתו את גובה הקיר.","ושאלו: \u0003וכמה עומקו של גיא\u0004 שמבליעים אותו במידה, אם אינו רחב חמישים אמה? \u0003אמר רב יוסף:\u0004 עד \u0003אלפים\u0004 אמה, ואם היה יתר על כן יש למדוד את המדרון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: היה הגיא \u0003עמוק מאה ורוחב חמשים — מבליעו\u0004 במדידה. \u0003ואם לאו — אין מבליעו,\u0004 וכיצד אמר רב עד אלפים? ומשיבים: \u0003הוא\u0004 רב יוסף ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003אחרים, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: אפילו\u0004 היה הגיא \u0003עמוק אלפים ורוחב חמשים מבליעו.\u0004 דיון זה נמסר גם בנוסח שונה.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 לשון אחרת, \u0003אמר רב יוסף:\u0004 עומק הגיא אין לו שיעור \u0003אפילו יתר מאלפים.\u0004 ותוהים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 הרי זה ש\u0003לא כ\u0004דעת ה\u0003תנא קמא\u0004 הוא \u0003ולא כ\u0004שיטת \u0003אחרים!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם\u0006 שנחלקו בעומק הגיא\u0005]\u0006 מדובר \u0003שאין חוט המשקולת יורד כנגדו\u0004 ויש טעם אף במדידת המדרון. \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003בחוט המשקולת יורד כנגדו,\u0004 ואם היה גיא תלול מאוד, אין מודדים.","ושואלים: \u0003וכי אין חוט המשקולת יורד כנגדו, עד כמה\u0004 יתרחק מכנגדו וייחשב כמדרון ולא ככותל זקוף? \u0003אמר אבימי: ארבע\u0004 אמות. כלומר, אם יש שיפוע של ארבע אמות בין שפת הגיא לתחתיתו, יש לחזור ולמדוד את המדרון עצמו. \u0003וכן תני\u0004 \u0005[שנה]\u0006 על סמך ברייתא \u0003רמי בר יחזקאל: ארבע\u0004 אמות.","נאמר במשנה שאם \u0003הגיע להר מבליעו וחוזר למדתו. אמר רבא: לא שנו אלא בהר המתלקט עשרה\u0004 טפחים בגובה \u0003מתוך\u0004 מדרון שאורכו \u0003ארבע\u0004 אמות, \u0003אבל בהר\u0004 שהוא משופע יותר, כגון ש\u0003מתלקט\u0004 ומגיע לגובה של \u0003עשרה\u0004 טפחים \u0003מתוך חמש\u0004 אמות — \u0003מודדו מדידה יפה\u0004 אף את המדרון.","זו היתה גירסה אחת, \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן מתני לקולא\u0004 \u0005[היה שונה\u0006 הלכה זו בנוסח \u0005מיקל]\u0006 \u0003וכך היה שונה, אמר רבא: לא שנו אלא בהר המתלקט עשרה מתוך חמש, אבל בהר המתלקט עשרה מתוך ארבע,\u0004 שהוא תלול יותר — אינו צריך למדוד, אלא \u0003אומדו\u0004 כמה רוחבו \u0003והולך לו,\u0004 ואינו צריך כל מדידה.","במשנה נאמר שאפילו בשעה שהוא מודד את הגיא או ההר שבתחום, \u0003ובלבד שלא יצא חוץ לתחום.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של איסור זה? \u0003אמר רב כהנא: גזירה שמא יאמרו מדת תחומין באה לכאן.\u0004 שאנשים יודעים שמודד זה בא לקבוע את התחומים, וכאשר יראוהו מודד במקום מסויים, יחשבו שאף לשם הגיע התחום.","נאמר במשנה ש\u0003אם אינו יכול להבליעו\u0004 הרי הוא מקדר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בהסבר הדבר: \u0003כיצד מקדרין,\u0004 ה\u0003תחתון\u0004 מחזיק את החבל \u0003כנגד לבו,\u0004 ה\u0003עליון\u0004 מחזיקו \u0003כנגד מרגלותיו,\u0004 וכך מודדים. \u0003אמר אביי: נקיטינן\u0004 \u0005[מוחזקים אנו\u0006 בהלכה זו\u0005]\u0006 ש\u0003אין מקדרין אלא בחבל של ארבע אמות.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה: נקיטינן\u0004 \u0005[מוחזקים אנו\u0006 בכלל זה\u0005]:\u0006 \u0003אין מקדרין לא\u0004 במדידת המרחק \u0003ב\u0004דין \u0003עגלה ערופה\u0004 לקבוע איזו היא העיר הקרובה ביותר אל החלל (דברים כ״א:ו׳), \u0003ולא ב\u0004קביעת תחומין של \u0003ערי מקלט\u0004 לדעת עד לאיזה תחום קולטת עיר המקלט ומצילה מגואל הדם (במדבר לב). \u0003מפני\u0004 שמידות אלה \u0003הן של תורה,\u0004 ובמידות אלה לא ניתנה רשות להשתמש בדרכי עקיפין של קידור או אומדן, אלא יש למדוד בפועל כאילו היה הכל שטח ישר.","\u0003אין מודדין אלא מן המומחה\u0004 בעניני מדידה. אם יתברר לאחר זמן ש\u0003ריבה\u0004 והגדיל את התחום \u0003למקום אחד, ומיעט למקום אחר,\u0004 ואין קו התחום מכוון — \u0003שומעין\u0004 וקובעים על פי ה\u0003מקום שריבה,\u0004 ומיישרים לפיו את התחום. וכן אם \u0003ריבה לאחד ומיעט לאחד — שומעין למרובה.\u0004","\u0003ו\u0004עוד, \u0003אפילו עבד אפילו שפחה\u0004 שאינם נאמנים בעדויות אחרות \u0003נאמנין לומר עד כאן תחום שבת, ש\u0004כן \u0003לא אמרו חכמים את הדבר\u0004 של דיני תחומין \u0003להחמיר, אלא להקל,\u0004 שכל דבר שהוא מדברי חכמים יש ללכת בהם לצד ההקלה וההיתר."],["\u0003שואלים: למקום שריבה — אין\u0004 \u0005[כן]\u0006 עושים כדבריו, ו\u0003למקום שמיעט\u0004 — לא יעשו כדבריו, ומדוע לא והרי הוא בכלל השטח המרובה? ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אף למקום שריבה\u0004 נוהגים כפי שציין את התחום, ואין חוששים שמא טעה (תוס'), אבל כמובן ששומעים לו למקום שמיעט.","נאמר במשנה שאם \u0003ריבה לאחד ומיעט לאחד\u0004 שומעים למרובה, ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי?\u0004 והרי זה \u0003היינו הך\u0004 \u0005[אותו דבר]\u0006 כי הלא שני המשפטים במשנה זהים בתוכנם! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש לתקן\u0005]:\u0006 אם היו שני מודדים, ו\u0003ריבה אחד\u0004 מהם את התחום, \u0003ומיעט אחד — שומעין לזה שריבה.\u0004","\u0003אמר אביי: ובלבד שלא ירבה יותר ממדת העיר באלכסונא\u0004 \u0005[באלכסון]\u0006 ואם היה ההבדל גדול יותר — ראוי למדוד שנית, שאם היה השיעור קטן מאלכסונה של העיר יש לתלות שמא המודד הראשון לא שיער יפה את תחום האלכסון.","במשנה נאמר: \u0003שלא אמרו חכמים את הדבר להחמיר אלא להקל.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא אמרו חכמים את הדבר להקל אלא להחמיר?\u0004","\u0003אמר רבינא:\u0004 אין שתי הגירסות סותרות זו את זו, אלא כאן יש להבין שעצם גזירת איסור התחומים \u0003לא להקל על דברי תורה\u0004 באה, כיון שמדין התורה אין כלל איסור תחומין, \u0003אלא להחמיר על דברי תורה, ותחומין דרבנן,\u0004 ומשום כך במקרים מסויימים התירו חכמים לסמוך בשיעור התחומים על ההקלות שכרגיל אין לדעתם לסמוך עליהן.","במשנה זו שבים לדון בדיני עירובי חצירות, אף כי הפרק כולו עסק בעירובי תחומין. \u0003עיר של יחיד,\u0004 שלא היו בה תושבים מרובים, \u0003ונעשית\u0004 מקום \u0003של רבים — מערבין את כולה,\u0004 ואפשר לעשותה כולה כחצר אחת על ידי עירוב מבואותיה ושיתוף חצרותיה אם אין בה רשות הרבים גמורה.","ואולם עיר \u0003של רבים\u0004 ש\u0003נעשית\u0004 במשך הזמן \u0003של יחיד,\u0004 שנתמעטו בה התושבים — \u0003אין מערבין את כולה, אלא אם כן עשה חוצה לה\u0004 מקום מסוים שאיננו נכלל בהיתר העירוב ושיעורו ויהיה אסור לטלטל בו. וזאת להיכר, כדי שלא תשתכח תורת עירוב, \u0003כ\u0004מו \u0003עיר\u0004 ששמה \u0003חדשה\u0004 אשר \u0003ביהודה, שיש בה חמשים דיורין,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 אין חייבים ליחד מקום גדול למטרת זכרון תורת עירוב, אלא די שלא יכלול בעירוב \u0003שלש חצירות של שני בתים\u0004 בכל חצר, והרי זה סימן היכר מספיק לדעת שלא כל העיר כולה מעורבת.","שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 מצב זה של \u0003עיר של יחיד ונעשית של רבים? אמר רב יהודה: כגון דאיסקרתא דריש גלותא\u0004 \u0005[מקומו של ראש הגולה]\u0006 שהיה כעין כפר קטן שהיה מיוחד למשפחת ראש הגולה ומשרתיו, ומאחר שבאים אליו רבים נעשתה כעיר של רבים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: מאי טעמא\u0004 \u0005[מה טעם]\u0006 סבור אתה כך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דשכיחי גבי הרמנא\u0004 \u0005[שמצויים\u0006 הרבים \u0005אצל המושל]\u0006 כדי לקבל רשיונות, \u0003מדכרי אהדדי\u0004 \u0005[מזכירים הם זה את זה].\u0006 שאמנם מצויים שם רבים, אבל לא יבואו להתיר משום כך מקום אחר שנעשה של רבים. ואולם אם לביאור הענין סומכים על העובדה שבמשך זמן מסוים מצויים הרבים בחבורה אחת, אם כן \u0003כולהו ישראל נמי בצפרא דשבתא שכיחי גבי הדדי\u0004 \u0005[כל ישראל גם כן בבוקר השבת מצויים זה אצל זה]\u0006 כאשר הם באים להתפלל, וכל עיר נעשית אז כעיר של רבים שהרבים מזכירים זה לזה. \u0003אלא אמר רב נחמן: כגון דיסקרתא\u0004 \u0005[העיר]\u0006 של \u0003נתזואי\u0004 שהיתה שייכת ליחיד, ונוספו בה תושבים מרובים, ונעשתה עיר של רבים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003עיר של יחיד ונעשית של רבים ורשות הרבים\u0004 גמורה \u0003עוברת בתוכה, כיצד מערבין אותה? עושה\u0004 לרשות הרבים \u0003לחי מכאן ולחי מכאן, או קורה מכאן וקורה מכאן, ונושא ונותן באמצע.\u0004 שרשות הרבים נעשית אף היא כאחת מחצירות העיר. \u0003ואין מערבין אותה,\u0004 את העיר הזו \u0003לחצאין אלא או כולה, או מבוי מבוי בפני עצמו\u0004 בלא לערב את שאר חלקי העיר.","\u0003היתה\u0004 זאת מתחילתה עיר \u0003של רבים, והרי היא\u0004 עיר \u0003של רבים\u0004"],["\u0003ואין לה אלא פתח אחד,\u0004 שהיא מוקפת חומה או שפתח רשות הרבים שבה סגור על ידי בתים — \u0003מערבין את כולה.\u0004","ושואלים על ברייתא זו: \u0003מאן תנא\u0004 \u0005[מיהו התנא\u0006 הסבור\u0005]\u0006 \u0003דמיערבא\u0004 \u0005[שניתנת לעירוב]\u0006 \u0003רשות הרבים\u0004 ושאפשר לעשותה בדרך כזו לרשות היחיד? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יתר על כן אמר ר' יהודה: מי שיש לו שני בתים בשני צידי רשות הרבים — עושה לחי מכאן ולחי מכאן, או קורה מכאן וקורה מכאן, ונושא ונותן באמצע.\u0004 שעל ידי כך עשה את השטח שביניהם כרשות היחיד. \u0003אמרו לו: אין מערבין רשות הרבים בכך.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא ש\u0003אין מערבין אותה לחצאין. אמר רב פפא: לא אמרו אלא לארכה,\u0004 כאשר כל תושבי חלק העיר שמשני צידי ראשה האחד של רשות הרבים — רוצים לערב לעצמם ללא תושבי ראשה השני. \u0003אבל לרחבה\u0004 שלכל חלק מן העיר מצרפים את רשות הרבים שבחלק זה ומשתתפים תושביו ביניהם לבין עצמם ואין אלה משתתפים, עם אלה באותה רשות הרבים — \u0003מערבין.\u0004 וטעמו של דבר: שבמקרה הראשון כשהיתה רשות הרבים בין שני חלקי העיר נמצא שרשות הרבים משותפת לשניהן ונעשו כרשות אחת על ידה. אבל כאשר העיר מחולקת לרוחבה, אין בני חלק זה משתמשים ברשות הרבים של חלק האחר.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 היא\u0005]\u0006 הלכה זו — ש\u0003לא כ\u0004דעת \u0003ר' עקיבא. דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא, הא\u0004 \u0005[הרי]\u0006 \u0003אמר: רגל המותרת במקומה אוסרת אפילו שלא במקומה.\u0004 שאם היתה חצר בתוך חצר אחרת, ועירבו בני כל חצר לעצמם, אמר ר' עקיבא שאף שבני החצר הפנימית מותר להם ללכת במקומם, ורגלם (הליכתם, דרכם) היא איפוא \"רגל המותרת במקומה\" — מכל מקום אוסרים הם לבני החצר החיצונה שהם עוברים בה, שרגלם \"אוסרת אפילו שלא במקומה\". ואף לעניננו: כיון שלבני מחצית העיר האחת מותר ללכת באותה המחצית שלהם, אבל אסור להם לטלטל במחציתה השניה — הרי זה בגדר \"רגל המותרת במקומה ואסורה במקום אחר\", ולפי שיטת ר' עקיבא צריך היה לאסור את העיר כולה אף באופן זה.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003ר' עקיבא,\u0004 אלא שיש להבחין בין המקרים: \u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' עקיבא התם\u0004 \u0005[שם]\u0006 \u0003אלא בשתי חצירות זו לפנים מזו,\u0004 שלחצר ה\u0003פנימית לית לה פיתחא אחרינא\u0004 \u0005[אין לה פתח אחר],\u0006 ודיירי הפנימית מוכרחים לעבור דרך החצר החיצונית, נמצא שהם מקלקלים את יחודה של חצר זו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשני חצאי העיר, \u0003הני נפקי בהאי פיתחא, והני נפקי בהאי פיתחא\u0004 \u0005[אלו יוצאים בפתח זה\u0006 של רשות הרבים, \u0005ואלו יוצאים בפתח זה\u0006 של רשות הרבים\u0005].\u0006 ומאחר שאינם חייבים לעבור דרך רשותם של האחרים, אפילו עוברים שם אינם אוסרים.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ענין זה בלשון אחרת, \u0003אמר רב פפא: לא תימא\u0004 \u0005[תאמר]\u0006 שרק \u0003לארכה הוא\u0004 ש\u0003לא מערבין\u0004 את העיר לשני חלקים, \u0003אבל לרחבה מערבין, אלא אפילו לרחבה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מערבין.\u0004","ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי],\u0006 \u0003כר' עקיבא!\u0004 ודוחים שאין הכרח לומר כן, אלא \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שדבר זה כשיטת \u0005חכמים]\u0006 כי, \u0003עד כאן לא\u0004 שמענו \u0003קאמרי רבנן התם\u0004 \u0005[שאמרו חכמים שם]\u0006 בענין חצירות \u0003אלא בשתי חצירות זו לפנים מזו,\u0004 ש\u0003פנימית אחדא לדשא ומשתמשא\u0004 \u0005[אוחזת את הדלת סגורה\u0006 בפני החצר החיצונה \u0005ומשתמשת\u0006 לעצמה\u0005],\u0006 ואפשר לומר שלפחות בני החצר הפנימית מותרים להלך בחצרם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בחלוקת העיר, \u0003מי מצו מסלקי\u0004 \u0005[האם יכולים\u0006 הם \u0005לסלק]\u0006 את \u0003רשות הרבים מהכא\u0004 \u0005[מכאן]?!\u0006 ובני עבר אחד יכולים להשתמש ברשות הרבים שמן העבר השני בלי שאפשר למנוע אותם, ובמקרה זה אפילו חכמים יודו שאין העירוב מועיל.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא שעיר כזו \u0003או\u0004 שתיערב \u0003כולה או מבוי מבוי בפני עצמו.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 ש\u0003לחצאין\u0004 ש\u0003לא,\u0004 שאסור לבני העיר לערב, משום שהם \u0003אסרי אהדדי\u0004 \u0005[אוסרים זה על זה]\u0006 שהרי בני מבוי אחד נכנסים במבוי האחר, ואולם \u0003מבוי מבוי נמי אסרי אהדדי\u0004 \u0005[גם כן אוסרים\u0006 הם \u0005זה על זה],\u0006 שהרי בני מבוי אחד רגילים להכנס במבוי האחר?!","\u0003ומשיבים: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון דעבוד\u0004 \u0005[שעשו]\u0006 \u0003דקה,\u0004 כעין מחיצה בפתח המבוי, להודיע שאינם מתכוונים להשתמש ולהוציא מן המבוי החוצה. \u0003וכי הא\u0004 \u0005[וכמו זה]\u0006 ש\u0003אמר רב אידי בר אבין אמר רב חסדא: אחד מבני מבוי שעשה דקה לפתחו\u0004 היוצא אל המבוי, והוכיח בכך שאינו רוצה להוציא דברים מביתו — \u0003אינו אוסר על בני מבוי\u0004 אם לא עירב עמם, שהרי הוכיח בכך שדעתו לסלק רשותו מן המבוי.","נאמר בברייתא שעיר ש\u0003היתה של רבים והרי היא\u0004 של רבים ויש לה פתח אחד לרשות הרבים, מערבים את כולה. מסופר: \u0003ר' זירא עירבה למתא דבי ר' חייא, ולא שבק\u0004 \u0005[ערב את העיר\u0006 שהיתה מכונה: \u0005זו של ר' חייא, ולא הניח]\u0006 \u0003לה שיור\u0004 בלי עירוב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי טעמא עבד מר הכי\u0004 \u0005[מה הטעם עשה אדוני כך]\u0006 ולא השאיר שיור לעיר כראוי?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סבי דידה אמרי\u0004 \u0005[הזקנים שלה,\u0006 של העיר הזו \u0005אמרו]\u0006 \u0003לי: רב חייא בר אסי\u0004 היה \u0003מערב\u0004 את העיר \u0003כולה ואמינא\u0004 \u0005[ואמרתי]:\u0006 מזה שהיה מערב את העיר כולה \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 כי מתחילה \u0003עיר של יחיד ונעשית של רבים היא,\u0004 ובעיר כזו, כאמור, אפשר לערב את העיר ללא שיור.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לדידי\u0004 \u0005[לי עצמי]\u0006 \u0003אמרו לי הנהו סבי\u0004 \u0005[אותם הזקנים]:\u0006 כי לא זה היה הטעם, אלא \u0003ההיא\u0004 \u0005[איזו]\u0006 ערימת \u0003אשפה הוה\u0004 \u0005[היתה]\u0006 \u0003לה\u0004 לעיר הזו \u0003מחד גיסא\u0004 \u0005[מצד אחד]\u0006 של רשות הרבים, שסתמה את רשות הרבים עד שלא היה לה אלא פתח אחד. \u0003והשתא דאיפניא\u0004 \u0005[ועכשיו שהתפנתה]\u0006 \u0003לה אשפה, הוה\u0004 \u0005[נהיתה]\u0006 \u0003לה כשני פתחים ואסיר\u0004 \u0005[ואסור],\u0006 שהרי רשות הרבים עוברת מפולשת בעיר, ובמקרה זה יש להשאיר שיור. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אדעתאי\u0004 \u0005[לא היה על דעתי],\u0006 כלומר לא ידעתי דבר זה.","\u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב אמי בר אדא הרפנאה\u0004 \u0005[מהרפניא]\u0006 \u0003מרבה:\u0004 אם היתה רשות הרבים הסגורה מצד אחד ויש בה \u0003סולם\u0004 המשמש לחציית חומתה \u0003מכאן,\u0004 אבל לא פתח ממש, \u0003ופתח מכאן, מהו,\u0004 האם לומר שרשות הרבים זו נחשבת כמפולשת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: סולם תורת פתח עליו,\u0004 ואם כן רשות הרבים מעין זו דינה כמפולשת.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: לא תציתו ליה\u0004 \u0005[אל תשמעו,\u0006 תצייתו\u0005, לו]\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב אדא אמר רב: סולם תורת פתח עליו\u0004 לדברים מסויימים, \u0003ו\u0004אף \u0003תורת מחיצה עליו\u0004 לדברים אחרים. \u0003תורת מחיצה עליו, כדאמרן\u0004 \u0005[כמו שאמרנו],\u0006 שסולם בקצה רשות הרבים אינו כפתח, ונחשבת רשות הרבים כסתומה. \u0003תורת פתח עליו,\u0004 כגון \u0003בסולם שבין שתי חצירות\u0004 השייכות לאנשים פרטיים שאם \u0003רצו\u0004 — מערבים עירוב אחד ומצרפים את שתי החצירות על ידי הסולם להיות כחצר אחת. ואם \u0003רצו —\u0004 ב\u0003שניים\u0004 עירובין הם \u0003מערבין.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב נחמן הכי\u0004 \u0005[כך]\u0006 בדין סולם? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר\u0004 בשם \u0003שמואל: אנשי חצר\u0004 הגרים בקומת קרקע \u0003ואנשי מרפסת\u0004 הגרים בקומה הראשונה מעליהם \u0003ששכחו\u0004"],["\u0003ולא עירבו\u0004 בני החצר עם בני המרפסת, \u0003אם יש לפניהם,\u0004 לפני פתחה של המרפסת, \u0003דקה\u0004 (כעין מחיצה) שרחבה \u0003ארבעה\u0004 טפחים — \u0003אינה\u0004 אין המרפסת \u0003אוסרת\u0004 על החצר, אף שלא עירבה עמה, שכל אחת משתמשת לעצמה. \u0003ואם לאו — אוסרת.\u0004 משמע שאף שבני המרפסת קשורים לקומת הקרקע על ידי סולם או מדרגות, בכל זאת נחשבות מדרגות אלה כפתח ממש, ובני המרפסת אוסרים.","ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 לענין חצר ומרפסת \u0005במה אנו עוסקים]\u0006 במקרה ש\u0003לא גבוה\u0004 ה\u0003מרפסת\u0004 מהקרקע \u0003עשרה\u0004 טפחים. וכיון שכן, אינה נחשבת כרשות לעצמה, אלא היא כחלק מהחצר.","ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא גבוה מרפסת עשרה,\u0004 והיא חלק מהחצר, \u0003כי קא עביד\u0004 \u0005[כאשר עושה]\u0006 \u0003דקה, מאי הוי\u0004 [\u0005מה נהיה\u0006 על ידי כך\u0005]?\u0006 הלא גם עם הדקה נחשבת המרפסת כחלק מהחצר! ומתרצים שכאן מדובר \u0003ב\u0004מרפסת \u0003מגופפת\u0004 (מוקפת גדר) \u0003עד\u0004 רוחב \u0003עשר אמות,\u0004 והיה פתח מסויים בתוך גפה (גדר) זו, ש\u0003כיון דעביד\u0004 \u0005[שעושה]\u0006 \u0003דקה,\u0004 מחיצה כל שהיא, בפתח זה — \u0003איסתלוקי איסתלוק ליה מהכא\u0004 \u0005[סילק עצמו מכאן]\u0006 מן השימוש בשאר החצר.","\u0003אמר רב יהודה אמר שמואל: כותל שרצפה\u0004 (מלא אותה) \u0003בסולמות, אפילו\u0004 ברוחב \u0003יתר מעשר\u0004 אמות — \u0003תורת מחיצה עליו\u0004 עדיין, ואין אנו אומרים שהסולמות נחשבים כפתחים שרוחבם עולה יחד למעלה מעשר אמות וכאילו נפרץ הכותל באותו מקום, ותיבטל תורת המחיצה.","\u0003רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב ברונא לרב יהודה במעצרתא דבי\u0004 \u0005[בבית הבד]\u0006 של \u0003רב חנינא: מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל\u0004 שכותל כזה \u0003תורת מחיצה עליו? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן אמר שמואל: אנשי מרפסת ואנשי חצר ששכחו ולא עירבו, אם יש לפניה דקה ארבעה — אינה אוסרת, ואם לאו\u0004 \u0005[לא],\u0006 אף אם גבוהה המרפסת עשרה טפחים ועומד שם סולם — \u0003אוסרת.\u0004 משמע שסולם דינו כפתח בכל דבר!","והשיב לו ר' יהודה, כפי שענינו לפני כן: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 כש\u0003לא גבוה מרפסת עשרה,\u0004 ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא גבוה מרפסת עשרה, כי עביד\u0004 \u0005[כאשר עושה]\u0006 \u0003דקה מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005],\u0006 ובמה מועיל הדבר, הלא כחצר אחת הן? ומשיבים: \u0003במגופפת\u0004 המרפסת בגדר \u0003עד עשר אמות\u0004 ויש בה פתח, ש\u0003כיון דעביד\u0004 \u0005[שעושה]\u0006 עוד \u0003דקה — איסתלוקי איסתלק מהכא\u0004 \u0005[סילק עצמו מכאן]\u0006 ואינו אוסר עוד\u0005].\u0006","\u0003הנהו בני קקונאי דאתי לקמיה\u0004 \u0005[אותם בני העיר קקוניא שבאו לפני]\u0006 \u0003רב יוסף, אמרו ליה: הב לן גברא דליערב לן מאתין\u0004 \u0005[אמרו לו: תן לנו אדם שיערב לנו את עירנו]\u0006 שהיתה בתחילה של רבים ונעשתה של יחיד, ואין מערבים אותה בלא להניח בה שיור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף \u0003לאביי: זיל ערב להו, וחזי דלא מצווחת עלה בבי מדרשא\u0004 \u0005[לך ערב להם, וראה\u0006 והזהר \u0005שלא תהיה צווחה על כך בבית המדרש]\u0006 שלא יסכימו החכמים לתיקונך. \u0003אזל, חזא להנהו בתי דפתיחי לנהרא\u0004 \u0005[הלך, ראה אותם בתים שהיו פתוחים לנהר]\u0006 ולא היו פתוחים לעיר. \u0003אמר: הני להוי\u0004 \u0005[אלה שיהיו]\u0006 \u0003שיור למתא\u0004 \u0005[לעיר],\u0006 ולא יצטרפו לעירוב עם שאר חלקי העיר.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר:\u0004 אי אפשר לעשות כן, שכן \u0003\"אין מערבין את כולה\" תנן\u0004 \u0005[שנינו],\u0006 \u0003מכלל דאי בעי לעירובי, מצי מערבי\u0004 \u0005[מכאן שאם היו רוצים לערב, היו יכולים לערב].\u0006 ואילו בתים אלה אינם יכולים כלל לערב עם אנשי העיר, ולכן אינם יכולים להיות שיור להם. \u0003אלא איעביד להו כווי\u0004 \u0005[אעשה להם חלונות]\u0006 בין חצרות בתיהם לעיר, \u0003דאי בעו לעירובי\u0004 \u0005[שאם ירצו לערב]\u0006 \u0003דרך חלונות — מצו מערבי\u0004 \u0005[יוכלו לערב].\u0006 ויכולים בתים אלו להיות אם כן שיור לעיר.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר: לא בעי\u0004 \u0005[צריך]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רבה בר אבוה\u0004 היה \u0003מערב לה לכולה\u0004 \u0005[את כל]\u0006 העיר \u0003מחוזא\u0004 שהיתה עיר של רבים ונעשתה של יחיד, \u0003ערסייתא ערסייתא\u0004 \u0005[שכונות שכונות]\u0006 \u0003משום פירא דבי תורי, דכל חד וחד הוי שיור לחבריה\u0004 \u0005[החפירה של השוורים, שכל אחד ואחד הריהו שיור לחבירו].\u0006 שבשל הבורות העמוקים (ששימשו כדי להאכיל בהם את השוורים) שהיו מפסיקים בין השכונות עירב רבה בר אבוה את מחוזא שכונה שכונה לעצמה, ולא חשש לערב כל מבוי שבשכונה בפני עצמו. ולא עשה שיור מיוחד לעיר, אלא סבר שכל שכונה תהיה שיור לחברתה. \u0003ואף על גב דאי בעו לערובי בהדי הדדי, לא מצו מערבי\u0004 \u0005[ואף על פי שאם היו רוצות\u0006 אותן השכונות \u0005לערב זו עם זו, לא היו יכולות]\u0006 בגלל ההפסק שבאמצע.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר: לא דמי\u0004 \u0005[דומה]\u0006 לאותו מקרה. \u0003התם, אי בעי לערובי\u0004 \u0005[שם, אם היו רוצים\u0006 היו יכולים \u0005לערב]\u0006 \u0003דרך גגות והני לא מערבי, הילכך נעבדן כווי\u0004 \u0005[ואלה\u0006 הבתים כאן \u0005אינם מערבים\u0006 עם שאר הבתים שבעיר, \u0005על כן נעשה\u0006 להם \u0005חלונות].\u0006","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר: כווי נמי לא בעי\u0004 \u0005[חלונות גם כן אינו צריך],\u0006 \u0003דההוא בי תיבנא דהוה ליה\u0004 \u0005[שאותו אוצר תבן שהיה לו]\u0006 \u0003למר בר פופידתא מפומבדיתא, ושויה\u0004 \u0005[ועשו אותו]\u0006 \u0003שיור\u0004 לעירוב \u0003ל\u0004עיר \u0003פומבדיתא.\u0004 משמע שאין צורך שיהיה המקום מסוגל לערב עם העיר כולה.","\u0003אמר\u0004 אביי לעצמו: \u0003היינו דאמר לי מר: \"חזי דלא מצווחת עלה בבי מדרשא\"\u0004 \u0005[זהו שאמר לי רבי,\u0006 רב יוסף: \u0005ראה שלא\u0006 תגרום בהוראתך שתהיה \u0005צווחה עליה בבית המדרש].\u0006 שכן נוכח לדעת בעצמו שיש כמה שיקולים בדבר, ויש ליזהר מלהוציא מסקנה חטופה.","נאמר במשנה שעיר של רבים ונעשתה של יחיד אין מערבים את כולה כאחת \u0003אלא אם כן עשה חוצה לה כעיר חדשה\u0004 שביהודה. ובביאור הדברים: \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה עיר אחת היתה ביהודה וחדשה שמה, והיו בה חמשים דיורים אנשים ונשים וטף, ובה היו משערים חכמים\u0004 את גודל השיור הנדרש לעירוב עיר, \u0003והיא\u0004 עצמה \u0003היתה שיור\u0004 לעיר גדולה שעמדה בצידה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003חדשה\u0004 עצמה \u0003מהו,\u0004 האם אפשר לערב אותה בפני עצמה בלא שיור? ומשיבים: \u0003חדשה, כי היכי דאיהי הויא\u0004 \u0005[כמו שהיא נהיית]\u0006 \u0003שיור לגדולה — גדולה נמי הויא\u0004 \u0005[גם כן נהיית]\u0006 \u0003שיור לקטנה,\u0004","\u0003אלא\u0004 השאלה היא לגבי עיר קטנה \u0003כעין חדשה\u0004 העומדת לבדה, \u0003מהו?\u0004 האם צריכה היא שיור, או לא? נחלקו בדבר \u0003רב הונא ורב יהודה; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: בעיא\u0004 \u0005[צריכה\u0006 היא\u0005]\u0006 \u0003שיור, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003שיור.\u0004","נאמר במשנה ש\u0003ר' שמעון אומר\u0004 כי לשם שיור אין צורך בעיר שלימה אלא די \u0003בשלש חצירות,\u0004 ובכל חצר שני בתים. \u0003אמר רב חמא בר גוריא אמר רב: הלכה כר' שמעון.\u0004 ואילו \u0003ר' יצחק אמר: אפילו בית אחד וחצר אחת.\u0004 ותוהים על לשון הדברים: \u0003חצר אחת סלקא דעתך\u0004 \u0005[עולה על דעתך],\u0006 האם מספיקה חצר סתם שאין בה בית?! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003בית אחד בחצר אחת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003ר' יצחק, גמרא\u0004 \u0005[מסורת\u0006 היא\u0005]\u0006 \u0003או סברא\u0004 משל עצמו היא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי נפקא לן מינה\u0004 \u0005[מה יוצא לנו מזה]\u0006 הלכה למעשה לדעת מה מקור דברי ר' יצחק? \u0003אמר ליה\u0004 \u0005[לו]\u0006 לפי הפתגם העממי: \u0003גמרא גמור, זמורתא תהא\u0004 \u0005[תלמוד תלמד, וזמר תהיה]\u0006 כלומר האם תשנן את הדברים כדברי זמר בלא להבין אותם?! אלא ראוי לחקור בצדדים השונים של דברי חכמים, אף שלא תמיד יש לכך חשיבות.","\u0003מי שהיה\u0004 בשעת כניסת השבת \u0003במזרח\u0004 העיר, \u0003ואמר לבנו\u0004 מבעוד יום: \u0003\"ערב לי במערב\".\u0004 או שהיה \u0003במערב, ואמר לבנו: \"ערב לי במזרח\". אם יש\u0004 מרחק \u0003הימנו ולביתו אלפים אמה, ולעירובו\u0004 אפילו \u0003יותר מכאן — מותר לביתו,\u0004 כלומר שדינו הוא כאילו שבת בביתו והולך ממנו אלפיים אמה, ואולם \u0003אסור\u0004 ללכת ממקום \u0003עירובו.\u0004","ואם היה למקום \u0003עירובו אלפים אמה, ולביתו יתר מכאן — אסור\u0004 ממקום \u0003ביתו, ומותר\u0004 ממקום \u0003עירובו.\u0004 כלומר, הכל נקבע לפי המקום שהוא שוהה בו כעת, ואין אדם יכול לעשות לו עירוב או לקנות לעצמו שביתה יותר מאלפים אמה מהמקום שהוא נמצא בו בכניסת השבת.","ועוד אמרו: \u0003הנותן את עירובו בעיבורה של עיר,\u0004 בתוך שטח שבעים אמה ושיריים לעיר, הרי זה כאילו \u0003לא עשה ולא כלום.\u0004 שכל העיר נחשבת כיחידה אחת, ותחום אלפיים האמה המותרים מתחיל מכל קצה של העיר, ואין הוא מרויח כלום אם אפילו הניח את העירוב לקצה האחר של העיר.","ואולם אם \u0003נתנו\u0004 לעירוב \u0003חוץ לתחום\u0004 העיר עצמה, \u0003אפילו\u0004 נתנו \u0003אמה אחת\u0004 חוץ לעיר"],["\u0003מה שנשכר\u0004 שמתיר לו עירובו ללכת יותר לצד זה \u0003הוא מפסיד\u0004 בצד האחר.","\u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתך\u0006 להבין\u0005]\u0006 שמה שאמור במשנה שהיה \u0003ל\u0004צד ה\u0003מזרח,\u0004 כוונתו שהיה עומד \u0003למזרח ביתו\u0004 והורה לבנו לערב למערבו. ומה שאמר במשנה \u0003\"למערב\"\u0004 פירושו: שעומד \u0003למערב ביתו\u0004 והורה לבנו לערב למזרחו, ונמצא שביתו עומד בינו לבין מקום עירובו.","ואם כן הרי יש מקום לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שתהא אפשרות שהמרחק \u0003הימנו ולביתו אלפים אמה ולעירובו יתר מכאן — משכחת לה\u0004 \u0005[מוצא אתה]\u0006 אפשרות זו, וכגון \u0003דמטי לביתיה ולא מטי\u0004 \u0005[שמגיעה\u0006 מידה זו עד \u0005לביתו ואינה מגיעה]\u0006 \u0003לעירובו, אלא \"הימנו ולעירובו אלפים אמה ולביתו יתר מכאן\" היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה\u0006 אפשרות\u0005]?\u0006 הלא הבית נמצא תמיד בינו ובין עירובו!","\u0003אמר ר' יצחק: מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003\"למזרח\"\u0004 משמעו שעומד \u0003למזרח ביתו, ו\"למערב\"\u0004 פירושו שעומד \u0003למערב ביתו?! לא, \"למזרח\"\u0004 הכוונה היא \u0003למזרח\u0004 ממקום \u0003בנו\u0004 ששם את העירוב, \u0003\"למערב\"\u0004 — פירושו: \u0003למערב בנו,\u0004 והבית עומד במקום אחר ובזוית.","\u0003רבא בר רב שילא אמר: אפילו תימא\u0004 \u0005[תאמר,\u0006 תתרץ\u0005]\u0006 \u0003\"למזרח\"\u0004 — כונתו \u0003למזרח ביתו, ו\"למערב\" — למערב ביתו,\u0004 אלא \u0003כגון דקאי ביתיה באלכסונא\u0004 \u0005[כגון שעומד ביתו באלכסון]\u0006 לצד אחר שאף שהוא עומד למערב ביתו, מכל מקום הבית מרוחק ממנו יותר מאשר מקום העירוב.","נאמר במשנה: \u0003הנותן עירובו בתוך עיבורה\u0004 של עיר לא עשה ולא כלום. ותוהים: \u0003חוץ לתחום סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 הלא הניח את העירוב מחוץ לתחום שבת, ואיננו יכול להגיע לשם או לקנות שם שביתה, ואיך יועיל עירוב זה? \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 \u0003חוץ לעיבורה\u0004 (שבעים אמה ושיריים) של העיר, ואם מניח העירוב שם קנה שביתה במקום.","נאמר במשנה ש\u0003מה שנשכר\u0004 בצד אחד \u0003הוא מפסיד\u0004 בצד השני. ותוהים: האם מדוייק הוא לומר שמפסיד \u0003מה שנשכר ותו לא\u0004 \u0005[ולא עוד]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הנותן את עירובו בתוך עיבורה של עיר — לא עשה ולא כלום. נתנו חוץ לעיבורה של עיר, אפילו אמה אחת — משתכר אותה אמה, ומפסיד את כל העיר כולה,\u0004 שכל העיר כולה שלאחרי אלפיים האמה ממקום העירוב אסורה עליו \u0003מפני שמדת העיר עולה לו במדת התחום!\u0004 כלומר, שטח העיר עולה בחשבון תחום האלפיים שבתוך המעורב, ואם כן לפעמים הוא מפסיד יותר ממה שהוא נשכר!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן — שכלתה מדתו בחצי העיר, כאן — שכלתה מדתו בסוף העיר.\u0004 שאם כלתה מדתו מעבר לה, מותר לו להלך בכל העיר.","\u0003וכדרבי ר' אידי,\u0004 ש\u0003אמר ר' אידי אמר\u0004 בשם \u0003ר' יהושע בן לוי:\u0004 אדם ששבת מחוץ לעיר ו\u0003היה מודד ובא\u0004 תחום שבת שלו \u0003וכלתה מדתו בחצי העיר — אין לו אלא חצי העיר,\u0004 ואינו יכול ללכת אלא כמידת העירוב בלבד. ואולם אם \u0003כלתה מדתו בסוף העיר — נעשית לו העיר כולה כארבע אמות, ומשלימין לו את השאר\u0004 שמנקים מחשבון תחומו עבור כל העיר רק ארבע אמות.","\u0003אמר ר' אידי: אין אלו אלא דברי נביאות.\u0004 כלומר, אין אני יכול למצוא נימוק הגיוני לדברים אלה. כי יש להקשות: \u0003מה לי\u0004 אם \u0003כלתה\u0004 המידה \u0003בחצי העיר, מה לי\u0004 אם \u0003כלתה בסוף העיר?\u0004","לכאורה אין שום הבדל, \u0003אמר רבא:\u0004 לא דברי נביאות הם שהרי \u0003תרוייהו תננהי\u0004 \u0005[שניהם שנינו]\u0006 במשנה במרומז: \u0003אנשי עיר גדולה,\u0004 שבתוך אלפיים אמה שלה היתה עיר קטנה, \u0003מהלכין את כל עיר קטנה,\u0004 ומחשבים את כולה כארבע אמות, ומשלימים את חשבון תחומם הלאה מיכן עד סוף אלפיים אמה."],["\u0003ואין אנשי עיר קטנה מהלכין את כל עיר גדולה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 חלוקה זו — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהני\u0004 \u0005[שאלה\u0006 בני העיר הקטנה\u0005],\u0006 \u0003כלתה מדתן\u0004 של התחום \u0003בחצי העיר\u0004 הגדולה, ולכן אינם יכולים להלך את כל העיר כולה. \u0003והני\u0004 \u0005[ואלה,\u0006 בני העיר הגדולה\u0005],\u0006 \u0003כלתה מדתן בסוף העיר\u0004 הקטנה, ויכולים הם להלך את כל העיר ויותר, עד סוף אלפיים אמה מתחום עירם.","\u0003ור' אידי\u0004 שאמר שאין מקור לדברי ר' יהושע בן לוי, יש לומר שהוא לא גרס במשנה \"אין מהלכין\" אלא \u0003\"אנשי אנשי\" תני\u0004 \u0005[שנה].\u0006 שלגרסתו כתוב (כבמשנה להלן) שאנשי עיר קטנה מהלכים בעיר הגדולה, \u0003ומוקים לה\u0004 \u0005[ומעמיד אותה]\u0006 \u0003בנותן\u0004 עירובו בתוך העיר האחרת, שהיא בתוך תחום עירוב שלו. וממילא נעשית לו אותה עיר כארבע אמות, \u0003אבל מודד\u0004 אלפיים אמה ממקומו \u0003לא תנן\u0004 \u0005[שנינו]\u0006 לחלק בין חצייה לכולה, ועוד תוהים:","\u0003ולא,\u0004 וכי לא כן הוא?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ולמודד שאמרו נותנין לו אלפים אמה, שאפילו סוף מדתו כלה במערה,\u0004 לא יוסיף להיכנס עוד בתוך המערה. הרי שאף שהמערה גדורה כולה ודינה כרשות היחיד, כיון שכלתה מידתו בחציה, אינו יכול להוסיף, ודין זה בדיוק כדין מי שכלתה מידתו בחצי העיר!","ומשיבים: אמנם דבר זה יש לו מקור, אבל זה שכלתה מידתו ב\u0003סוף העיר\u0004 שיש לו כל העיר כולה \u0003איצטריכא ליה, דלא תנן\u0004 \u0005[צריך לו, שלא שנינו]\u0006 דוגמתו.","וביחס למשנה זו עצמה מביאים מה ש\u0003אמר רב נחמן: מאן דתני\u0004 \u0005[מי ששונה]\u0006 בשני המשפטים \u0003\"אנשי\" לא משתבש\u0004 בגירסתו, \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"אין אנשי\u0004 עיר קטנה מהלכים \u0003\"\u0004אף הוא \u0003לא משתבש.\u0004","ומסביר את הדבר: \u0003מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003\"אנשי\" לא משתבש — דמוקים לה\u0004 \u0005[שמעמיד אותה\u0006 את המשנה\u0005]\u0006 \u0003בנותן\u0004 עירובו בעיר גדולה או בעיר קטנה. \u0003ומאן דתני\u0004 \u0005[ומי ששונה]\u0006 \u0003\"אין אנשי\"\u0004 אף הוא \u0003לא משתבש, דמוקים לה\u0004 \u0005[שמעמיד אותה\u0006 את המשנה\u0005]\u0006 \u0003במודד\u0004 מן תחום עירוב והלאה,","\u0003וחסורי מחסרא, והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה, \u0005וכך יש לשנותה]:\u0006 \u0003אנשי עיר גדולה מהלכין את כל עיר קטנה, ואין אנשי עיר קטנה מהלכין את כל עיר גדולה. במה דברים אמורים — במודד\u0004 מתחומו והלאה. \u0003אבל מי שהיה בעיר גדולה והניח את עירובו בעיר קטנה, היה בעיר קטנה והניח את עירובו בעיר גדולה — מהלך את כולה וחוצה לה אלפים אמה.\u0004","\u0003אמר רב יוסף אמר רמי בר אבא אמר רב הונא: עיר שיושבת על שפת הנחל, אם יש לפניה דקה\u0004 (מעין מחיצה) שגובהה \u0003ארבעה\u0004 אמות לאורך כל שפת הנחל הסמוכה לעיר — \u0003מודדים לה\u0004 תחום \u0003משפת הנחל,\u0004 שהוא נחשב כגבול לעיר. \u0003ואם לאו\u0004 \u0005[לא] —\u0006 \u0003אין מודדין לה אלא מפתח ביתו\u0004 של כל אדם הדר באותו מקום. שבהעדר מחיצה זו אין העיר נחשבת כישוב קבע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דקה\u0004 בגובה \u0003ארבע אמות אמרת לן עלה\u0004 \u0005[לנו עליה]\u0006 שיש לעשות כאן מחיצה מיוחדת. ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 הדבר \u0003מכל דקי דעלמא\u0004 \u0005[מחיצות קטנות שבעולם]\u0006 שלהלכה דיין ב\u0003ארבעה\u0004 טפחים?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם, לא בעיתא תשמישתא. הכא, בעיתא תשמישתא\u0004 \u0005[שם, אין שימושו מבהיל. כאן, שימושו מבהיל].\u0006 שבשאר מקומות שהמחיצה היא סמלית בלבד, די שתהא בת ארבעה טפחים. ואילו על שפת הנחל, שיש פחד לעמוד שם בלא הגנה, יש לעשות מחיצה גבוהה של ממש כדי להגן על הבריות.","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 את ההלכה הזו\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003התיר רבי שיהו בני גדר יורדין\u0004 בשבת \u0003לחמתן, ואין בני חמתן עולין לגדר. מאי טעמא\u0004 \u0005[מה הטעם],\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהני עבוד\u0004 \u0005[שאלו\u0006 בני גדר \u0005עשו]\u0006 \u0003דקה, והני לא עבוד\u0004 \u0005[ואלה\u0006 בני חמתן \u0005לא עשו]\u0006 \u0003דקה.\u0004 ולכן בני גדר מודדים להם מן המחיצה הנמצאת בקצה העיר ונמצאת חמתן בתוך תחומה, בני חמתן שלא עשו מחיצה מודדים להם רק מבתיהם והקיצונים שביניהם, אין גדר בתוך תחומם.","ומספרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי אמר:\u0004 לא מטעמי עיבור תחומין נאמר דבר זה אלא \u0003טטרוגי מטטרגי להו\u0004 \u0005[מכים ופוצעים היו]\u0006 \u0003בני גדר\u0004 את \u0003בני חמתן, ומאי \"התיר\" — התקין.\u0004 שלא היה כאן היתר מטעמי הלכה, אלא תקנה משום שלום הבריות שלא יגיעו לכלל קטטה.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003שבת\u0004 שהתקין בה תקנה זו, משום \u0003דשכיחא\u0004 \u0005[שמצויה]\u0006 \u0003בה\u0004 בשבת \u0003שכרות,\u0004 שהכל סועדים בה כרצונם ויכולים להרשות לעצמם להרבות בשתיה יותר ויבואו לידי הכאה.","ושואלים: \u0003כי אזלי להתם, נמי מטטרגי להו\u0004 \u0005[כאשר הולכים\u0006 בני גדר \u0005לשם\u0006 לחמתן, \u0005גם כן יפצעו אותם\u0006 שם\u0005]\u0006 את בני חמתן, ומה הועילה התקנה? ועונים על פי משל העממי: \u0003כלבא בלא מתיה, שב שנין לא נבח\u0004 \u0005[הכלב שלא במקומו, שבע שנים אינו נובח].\u0006 שאף שהכלב נובח על הכל כשהוא במקומו, כשאינו במקומו מפחד הוא ואינו נובח. אף בני גדר, כשהם מצויים בעיר אחרת אינם מעיזים כל כך.","ושואלים: אם כן, יש לחשוש לסכנה הפוכה, \u0003השתא נמי מטטרגי\u0004 \u0005[עכשיו גם כן יכו]\u0006 \u0003בני חמתן לבני גדר,\u0004 שבני חמתן הם בעלי הבית וייפרעו מאורחים אלה! ומשיבים: בכל זאת \u0003כולי האי לא כייפי להו\u0004 \u0005[כל כך אינם כפופים להם],\u0006 ואף שעוברים דרך עירם, אינם מעיזים לנגוע בהם בפועל, ונמצא שאינם מגיעים להכאה.","\u0003רב ספרא אמר:\u0004 גדר \u0003עיר העשויה כקשת הואי\u0004 \u0005[היתה],\u0006 ובין ראשי הקשת לא היו ארבעת אלפים אמה, ולכן אף על פי שלבני גדר עצמה נחשב החלל שבין ראשי הקשת כאילו היה בנוי, מותר להם ללכת לחמתן. מכל מקום לבני חמתן אינו נחשב אלא כשטח פנוי, ונמצא שבתי גדר שלאורך הקשת נחשבים לגביהם כמחוץ לתחום ואסורים בהליכה לשם.","ואילו \u0003רב דימי בר חיננא אמר:\u0004 גדר \u0003אנשי עיר גדולה\u0004 וחמתן \u0003אנשי עיר קטנה הואי\u0004 \u0005[היו].\u0006 שבני גדר העיר הגדולה יכלו להלך בכל חמתן הקטנה, אף שבני חמתן לא היו יכולים להלך בגדר אלא בחלקה כמבואר לעיל.","\u0003רב כהנא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את הדברים הללו. ואילו \u0003רב טביומי מתני הכי\u0004 \u0005[היה שונה כך,\u0006 בצורה אחרת\u0005]\u0006 שאמר בקיצור: \u0003רב ספרא ורב דימי בר חיננא\u0004 נחלקו בדבר \u0003חד\u0004 \u0005[אחד\u0006 מהם, רב ספרא\u0005]\u0006 \u0003אמר: עיר העשויה כקשת הואי\u0004 \u0005[היתה],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם, רב דימי בר חיננא\u0005]\u0006 \u0003אמר: אנשי עיר קטנה ואנשי עיר גדולה הואי\u0004 \u0005[היו].\u0006","\u0003אנשי עיר גדולה מהלכין את כל עיר קטנה, ואנשי עיר קטנה מהלכין את כל עיר גדולה\u0004 חוץ למידת תחומם. \u0003כיצד? מי שהיה בעיר גדולה ונתן את עירובו בעיר קטנה,\u0004 או מי שהיה \u0003בעיר קטנה ונתן את עירובו בעיר גדולה — מהלך את\u0004 כל העיר \u0003כולה\u0004 שנתן בה את העירוב, שנחשבת לו כולה כארבע אמות \u0003וחוצה לה אלפים אמה.\u0004","\u0003ר' עקיבא אומר: אין לו אלא ממקום עירובו אלפים אמה,\u0004 ואת העיר מודדים בפועל כשאר מקומות. \u0003אמר להן ר' עקיבא\u0004 לחכמים: וכי \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים לי בנותן עירובו במערה, שאין לו אלא ממקום עירובו אלפים אמה,\u0004 ואינו רשאי להלך בכל המערה כולה?","\u0003אמרו לו\u0004 חכמים: \u0003אימתי\u0004 נאמר דבר זה — \u0003בזמן שאין בה דיורין\u0004 במערה, \u0003אבל יש בה דיורין\u0004 — נעשית כולה כארבע אמות. \u0003מהלך את כולה וחוצה לה אלפים אמה. נמצא\u0004 לעתים, \u0003קל תוכה מעל גבה,\u0004 שכשיש בה דיורים מותר להלך בתוך המערה יותר מאשר על גבה.","\u0003ולמודד\u0004 תחומו ממקום מושבו \u0003שאמרו נותנין אלפים אמה\u0004 ממקומו עד סוף אלפיים — הכוונה \u0003שאפילו סוף מדתו כלה במערה\u0004 אינו רשאי להלך בה יותר מתחומו, אפילו יש בה דיורים."],["\u0003אמר רב יהודה אמר שמואל: שבת בעיר\u0004 שעדיין מחיצותיה קיימות, אבל הינה \u0003חריבה\u0004 שאין בה דיורים, \u0003ל\u0004דעת \u0003רבנן — מהלך את כולה\u0004 כארבע אמות \u0003וחוצה לה\u0004 עוד \u0003אלפים אמה.\u0004 ואולם אם רק \u0003הניח את עירובו בעיר חריבה — אין לו ממקום עירובו אלא אלפים אמה.\u0004 שלדעת חכמים יש לחלק בין מי ששובת ממש במקום, לבין מי שרק מניח בו עירוב. \u0003ר' אלעזר אומר: אחד שבת ואחד הניח — מהלך את כולה וחוצה לה אלפים אמה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 \u0003אמר להן ר' עקיבא: אי אתם מודים לי בנותן את עירובו במערה, שאין לו ממקום עירובו אלא אלפים אמה? אמרו לו: אימתי — בזמן שאין בה דיורין. הא\u0004 \u0005[הרי\u0006 נמצא\u0005]\u0006 כי \u0003באין בה דיורין מודו ליה\u0004 \u0005[מודים לו\u0006 לר' עקיבא\u0005]\u0006 שאין העיר נחשבת כארבע אמות, וקשה לדברי ר' אלעזר?!","ומתרצים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין בה דיורין\" — אינה ראויה לדירה.\u0004 אבל אם היתה העיר ריקה מתושבים, אך ראויה למגורים, הרי כולה כארבע אמות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה אחרת ממה ששנינו: \u0003שבת בעיר, אפילו היא גדולה כאנטיוכיא,\u0004 שבת \u0003במערה, אפילו היא כמערת צדקיהו מלך יהודה — מהלך את כולה וחוצה לה אלפים אמה. קתני\u0004 \u0005[שנויה\u0006 כאן\u0005]\u0006 \u0003עיר דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מערה, מה מערה\u0004 מן הסתם \u0003חריבה\u0004 שאין אנשים גרים בה, \u0003אף עיר חריבה\u0004 שאין בה דיורים, אף שמחיצותיה קיימות. ועוד נדייק: אם \u0003שבת\u0004 במקום — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל הניח — לא.\u0004","ומעתה נברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' עקיבא\u0004 שאף בהניח בה אינו יכול להלך בכולה, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע דווקא \u0003חריבה? אפילו\u0004 אם היתה \u0003ישיבה נמי!\u0004 שהרי ר' עקיבא אינו מחלק בין זו שיש בה דיורים ובין זו שאין בה דיורים. \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003וטעמא\u0004 \u0005[והטעם\u0006 דווקא\u0005]\u0006 אם \u0003שבת — אין\u0004 \u0005[כן]\u0006 יש לו אלפיים אמה מחוץ לעיר, \u0003אבל\u0004 אם רק \u0003הניח\u0004 עירובו בה — \u0003לא,\u0004 וקשה לשיטת ר' אלעזר!","ודוחים כי הדיוק מעיקרו אינו נכון, \u0003לא תימא\u0004 \u0005[תאמר]\u0006 שמדובר ב\u0003עיר דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מערה, אלא אימא\u0004 \u0005[אמור]\u0006 שמדובר ב\u0003מערה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003עיר. מה עיר ישיבה — אף מערה ישיבה,\u0004 כשם שסתם עיר מיושבת היא, אף המערה שמדובר בה מיושבת. וברייתא זו כשיטת \u0003ר' עקיבא היא\u0004 ש\u0003אמר:\u0004 שאם הניח בה \u0003אין לו ממקום עירובו אלא אלפים אמה,\u0004 ואף על פי כן אם \u0003שבת\u0004 במערה שיש בה דיורים \u0003מודי\u0004 \u0005[מודה]\u0006 ר' עקיבא שנעשתה לו כולה כארבע אמות ויכול להלך אלפיים אמה מחוץ למערה.","ומקשים: כיצד אפשר לומר כן \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כמערת צדקיהו קתני\u0004 \u0005[שנינו],\u0006 ומערה זו אין בה דיורים! ומשיבים: הכוונה \u0003כמערת צדקיהו\u0004 לענין מסוים, \u0003ולא כמערת צדקיהו\u0004 בכל הפרטים. \u0003כמערת צדקיהו\u0004 שהמערה \u0003גדולה\u0004 כמותה, \u0003ולא כמערת צדקיהו\u0004 בדיוק ש\u0003אילו התם\u0004 \u0005[שם,\u0006 מערת צדקיהו\u0005]\u0006 \u0003חריבה\u0004 היא, \u0003והכא ישיבה\u0004 \u0005[וכאן\u0006 מדובר במערה \u0005מיושבת].\u0006","מסופר: \u0003מר יהודה אשכחינהו\u0004 \u0005[מצא]\u0006 את \u0003בני מברכתא דקא מותבי עירובייהו בבי כנישתא דבי אגובר\u0004 \u0005[שהיו שמים עירובם בבית הכנסת של בית אגובר]\u0006 שהיה בתוך תחום העיר, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003גוו ביה טפי, כי היכי דלישתרי לכו טפי\u0004 \u0005[הכניסו אותו\u0006 את העירוב \u0005יותר\u0006 בתוך בית הכנסת, \u0005כדי שיותר לכם יותר]\u0006 שהרי ממקום העירוב מודדים את התחום. שסבר מר יהודה שאף אם מניח עירובו בעיר, מודדים לו אלפיים אמה ממקום עירובו ולא מקצה העיר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: פלגאה\u0004 \u0005[בעל מחלוקת],\u0006 \u0003בעירובין לית דחש להא\u0004 \u0005[אין\u0006 מי \u0005שחושש ל\u0006שיטתו \u0005זו]\u0006 של \u0003ר' עקיבא\u0004 והלכה כדברי חכמים. ובכל מקום שמניח את עירובו בעיר — כל העיר כולה נחשבת לו כארבע אמות ויכול לטלטל מגבולה אלפיים אמה בלא הבדל היכן מניחו בתוך העיר. \u0003הדר עם הגוי ב\u0004אותה \u0003חצר, או\u0004 היה דר \u0003עם מי שאינו מודה בעירוב,\u0004 אף שאינו גוי, וכגון: כותי (קראי) — \u0003הרי זה אוסר עליו\u0004 לטלטל בחצר אלא אם כן ישכור, כאשר יבואר.","","","\u0003ר' אליעזר בן יעקב אומר: לעולם איני אוסר\u0004 (הגוי) \u0003עד שיהו שני ישראלים\u0004 באותה חצר שמצד עצמם \u0003אוסרין זה על זה\u0004 בלא עירוב, וכיון שמצוי שם גוי אין העירוב מועיל להם. אבל אם דר שם רק ישראל אחד, אינו אוסר עליו. \u0003אמר רבן גמליאל: מעשה בצדוקי אחד שהיה דר עמנו במבוי בירושלים\u0004 וביטל לנו את רשותו בלא תשלום, \u0003ואמר לנו אבא: מהרו והוציאו את הכלים למבוי\u0004 והחזיקו במבוי, \u0003עד שלא\u0004 יתחרט ו\u0003יוציא\u0004 הוא ראשון ויחזיק ברשותו, ואז \u0003יאסר עליכם\u0004 להשתמש בכל המבוי שלו. הרי שאין דין זה שאינו מודה בעירוב כדין הגוי, שהרי הגוי מרגע שקיבל מעות שכירות המקום ומבטל רשותו, שוב אינו יכול להחזיק בו בחזרה ואפילו יוציא כליו אין בכך כל משמעות. \u0003ר' יהודה אומר: בלשון אחר\u0004 אמר להם: \u0003מהרו ועשו צרכיכם במבוי\u0004 לפני השבת, \u0003עד שלא יוציא\u0004 הצדוקי \u0003ויאסר עליכם.\u0004 כי בשבת עצמה אסור להם להוציא, שאין תקנת עירוב בשכנותו של הצדוקי, לפי שיכול לחזור בו ולהחזיק ברשותו בחזרה.","",""]]};
